window.PRELOADED_CHAPTERS = {
  "1": "<section class=\"chapter-section\" id=\"ch1\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (गद्य खंड)</div>\n      <h2>दो बैलों की कथा</h2>\n      <p>मुंशी प्रेमचंद | गद्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch1-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कांजीहौस में हाजिरी क्यों ली जाती होगी?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कांजीहौस (Cattle Pound) एक प्रकार का पशुओं का कारागार या बंदीगृह होता था, जहाँ लावारिस, दूसरों के खेतों में चरने वाले अथवा आवारा घूमने वाले पशुओं को पकड़कर बंद किया जाता था।</p>\n<p>यहाँ प्रतिदिन पशुओं की हाजिरी निम्नलिखित कारणों से ली जाती होगी:</p>\n<ul>\n  <li><strong>पशुओं की सही संख्या की निगरानी:</strong> कांजीहौस में बंद सभी पशुओं की सही गिनती का दैनिक रिकॉर्ड रखा जा सके ताकि कोई पशु वहाँ से भाग न जाए।</li>\n  <li><strong>स्वास्थ्य एवं जीवित होने की पुष्टि:</strong> पशुओं की शारीरिक दशा व जीवित रहने की जानकारी प्राप्त की जा सके, क्योंकि भूख-प्यास के कारण कई दुर्बल पशु मर भी जाते थे।</li>\n  <li><strong>जवाबदेही एवं नीलामी प्रक्रिया:</strong> पशुओं के मालिकों से जुर्माना वसूलने अथवा तय समय पर नीलामी करने के लिए विधिवत कानूनी रिकॉर्ड बना रहे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पशुओं की दैनिक संख्या व सुरक्षा की निगरानी का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वास्थ्य, मृत्यु व कानूनी उत्तरदायित्व/नीलामी का स्पष्टीकरण</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">छोटी बच्ची को बैलों के प्रति प्रेम क्यों उमड़ आया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>गया के घर में रहने वाली छोटी बच्ची की माँ मर चुकी थी और उसकी सौतेली माँ उस पर आए दिन अत्याचार करती थी तथा उसे कठोर यातनाएँ देती थी। बच्ची स्वयं को उपेक्षित, असहाय और अनाथ महसूस करती थी।</p>\n<p>जब उसने देखा कि गया ने हीरा और मोती को दिन भर हल में जोतकर मारा-पीटा और शाम को सूखा भूसा डालकर बाँध दिया, तो वह बैलों की मूक व्यथा और उनके स्वाभिमान भरे कष्ट को गहराई से समझ गई।</p>\n<p><strong>प्रेम उमड़ने का मुख्य कारण:</strong></p>\n<ul>\n  <li><strong>समान संवेदनात्मक पीड़ा:</strong> दोनों ही उस क्रूर परिवेश में बेसहारा, शोषित और प्रेम के भूखे थे। एक अनाथ बच्ची और मूक पशुओं के बीच आत्मीयता का गहरा बंधन स्थापित हो गया।</li>\n  <li><strong>मूक आत्मीयता:</strong> बच्ची अपनी सहानुभूति प्रकट करने के लिए रोज रात को चुपके से दोनों बैलों को एक-एक रोटी खिलाती थी, जिससे उनके बीच अटूट भावनात्मक रिश्ता बन गया।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बच्ची की पारिवारिक पृष्ठभूमि (सौतेली माँ का अत्याचार) का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बैलों की दुर्दशा और बच्ची की व्यथा के बीच आत्मीय साम्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा-शैली व अभिव्यक्ति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कहानी में बैलों के माध्यम से कौन-कौन से नीति-विषयक मूल्य उभर कर आए हैं?</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>मुंशी प्रेमचंद जी ने 'दो बैलों की कथा' के माध्यम से न केवल पशु-प्रेम को दर्शाया है, बल्कि मानवीय समाज के लिए अत्यंत महत्वपूर्ण नीति-विषयक (नैतिक) मूल्यों को भी उजागर किया है:</p>\n<ol>\n  <li><strong>स्वतंत्रता सर्वोपरि मूल्य है:</strong> स्वतंत्रता सहज और सरलता से नहीं मिलती। इसके लिए निरंतर संघर्ष, त्याग और कष्ट सहना पड़ता है। हीरा और मोती ने हर बंधन (गया की रस्सी, कांजीहौस की चारदीवारी, कसाई का खूँटा) को तोड़कर आजादी पाई।</li>\n  <li><strong>सच्ची मित्रता एवं परस्पर वफादारी:</strong> विपत्ति के समय एक-दूसरे का साथ कभी नहीं छोड़ना चाहिए। जब मोती कांजीहौस की दीवार तोड़कर अन्य जानवरों को भगा देता है, तब हीरा के बँधे होने के कारण वह स्वयं भी भागने से इनकार कर देता है।</li>\n  <li><strong>सहानुभूति व कृतज्ञता का भाव:</strong> बैलों ने उपकार करने वाली छोटी बच्ची का सम्मान किया और गया की पत्नी अथवा बच्ची को कोई नुकसान नहीं पहुँचाया, जो उनकी कृतज्ञता को दर्शाता है।</li>\n  <li><strong>मातृभूमि व गृह-प्रेम (देशभक्ति का प्रतीक):</strong> चाहे जितनी भी प्रताड़ना मिले, व्यक्ति का अपने मूल स्थान व स्वामी के प्रति अगाध प्रेम होता है। दोनों बैल अंततः झूरी की चरनी पर ही लौटकर आते हैं।</li>\n  <li><strong>नारी जाति का सम्मान:</strong> हीरा का कथन 'औरत जात पर सींग चलाना मना है' यह स्पष्ट करता है कि समाज में स्त्रियों के प्रति आदर व संरक्षण का भाव होना अनिवार्य है।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वतंत्रता का महत्व एवं संघर्षशीलता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सच्ची मित्रता, त्याग और परोपकार के उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नारी सम्मान, कृतज्ञता व देशभक्ति प्रतीकार्थ की स्पष्टता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुगठित भाषा एवं तर्कपूर्ण प्रस्तुति</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">प्रस्तुत कहानी में प्रेमचंद ने गधे की किन स्वभावगत विशेषताओं के आधार पर उसके प्रति रूढ़ अर्थ 'मूर्ख' का प्रयोग न कर किस नए अर्थ की ओर संकेत किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>सामान्यतः समाज में गधे को उसकी अत्यधिक सरलता के कारण 'मूर्खता' का प्रतीक मान लिया गया है। किसी व्यक्ति को बेवकूफ कहना हो तो उसे 'गधा' कह दिया जाता है।</p>\n<p>परंतु प्रेमचंद जी ने गधे के स्वभाव के सकारात्मक व उदात्त गुणों को रेखांकित करते हुए उसे ऋषियों-मुनियों के समान सहनशील सिद्ध किया है:</p>\n<ul>\n  <li><strong>असीम सहनशीलता व संतोष:</strong> गधा कभी क्रोध नहीं करता, चाहे उसे सूखी घास दी जाए या पीटा जाए। उसके चेहरे पर कभी असंतोष की छाया तक नहीं दिखाई देती।</li>\n  <li><strong>समभाव (सुख-दुःख में एक समान):</strong> सुख हो या दुःख, लाभ हो या हानि, उसका स्वभाव सदैव शांत और अपरिवर्तित रहता है।</li>\n  <li><strong>ऋषि-तुल्य गरिमा:</strong> लेखक के अनुसार सद्गुणों की इतनी पराकाष्ठा केवल भारत के ऋषियों में पाई जाती है। अतः प्रेमचंद ने गधे को 'मूर्ख' के स्थान पर 'सत्याग्रही, परमसंतोषी और सहनशील प्राणी' का नया अर्थ प्रदान किया है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रूढ़ अर्थ (मूर्ख) का खंडन एवं सहनशीलता का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ऋषि-मुनियों के समभाव व संतोष से तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्याकरणिक शुद्धता व सटीक निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">किन घटनाओं से पता चलता है कि हीरा और मोती में गहरी दोस्ती थी?</div>\n      <div class=\"q-marks\">4 अंक (70-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कहानी में ऐसी अनेक मार्मिक घटनाएँ वर्णित हैं जिनसे हीरा और मोती की प्रगाढ़, निस्वार्थ और अनूठी मित्रता सिद्ध होती है:</p>\n<ul>\n  <li><strong>मूक भाषा में विचार-विनिमय:</strong> दोनों बैल एक-दूसरे को चाटकर, सूँघकर अपना प्रेम प्रकट करते थे और साँड़ों की तरह सींग मिलाकर केवल विनोद भाव से शक्ति आजमाते थे।</li>\n  <li><strong>हल में एक-दूसरे का भार सहना:</strong> गाड़ी या हल में जुतने पर दोनों की यही चेष्टा रहती थी कि ज्यादा बोझ मेरी गर्दन पर रहे, साथी को कम कष्ट हो।</li>\n  <li><strong>गया के घर से मिलकर भागना:</strong> जब गया उन्हें ले गया, तो दोनों ने सलाह करके रस्सियाँ तुड़ा लीं और एक साथ वापस झूरी के घर पहुँचे।</li>\n  <li><strong>साँड का मिलकर मुकाबला करना:</strong> जब विशाल साँड ने हमला किया, तो दोनों ने एक संगठित योजना बनाई—एक आगे से वार करता तो दूसरा पीछे से, और साँड को परास्त कर दिया।</li>\n  <li><strong>कांजीहौस में साथ निभाना:</strong> कांजीहौस की दीवार टूटने पर जब मोती भाग सकता था, तब भी वह हीरा को खूँटे से बँधा देखकर वहीं रुक गया और दोनों ने साथ में सजा भुगती।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मूक प्रेम व हल में अधिक बोझ उठाने की चेष्टा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">साँड से संयुक्त मुकाबला करने का उदाहरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कांजीहौस में साथी के लिए स्वयं को संकट में डालने का त्याग</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा-प्रवाह एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">‘लेकिन औरत जात पर सींग चलाना मना है, यह भूल जाते हो।’ — हीरा के इस कथन के माध्यम से स्त्री के प्रति प्रेमचंद के दृष्टिकोण को स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>जब गया के घर में मोती गुस्से में आकर गया की पत्नी पर हमला करने की बात कहता है, तब हीरा उसे यह कहकर शांत करता है कि स्त्री पर प्रहार करना हमारी मर्यादा के विरुद्ध है।</p>\n<p><strong>प्रेमचंद के दृष्टिकोण का विश्लेषण:</strong></p>\n<ul>\n  <li><strong>स्त्री सम्मान की भारतीय परंपरा:</strong> प्रेमचंद भारतीय संस्कृति के उस उदात्त मूल्य के प्रबल समर्थक थे जहाँ नारी को पूजनीय, अबला और संरक्षणीय माना गया है। पशु भी इस मर्यादा का पालन करते हैं।</li>\n  <li><strong>शारीरिक प्रताड़ना का कड़ा विरोध:</strong> लेखक समाज में स्त्रियों के प्रति होने वाले किसी भी प्रकार के शारीरिक या मानसिक अत्याचार के सख्त खिलाफ थे।</li>\n  <li><strong>संस्कार व नैतिकता:</strong> यह कथन सिद्ध करता है कि क्रोध या विपत्ति की चरम सीमा में भी नैतिक सीमाओं और मानवीय मर्यादाओं का उल्लंघन नहीं होना चाहिए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संदर्भ (हीरा-मोती का संवाद) की स्पष्टता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेमचंद के स्त्री-सम्मान व अहिंसक दृष्टिकोण का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अभिव्यक्ति एवं भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">किसान जीवन वाले समाज में पशु और मनुष्य के आपसी संबंध को कहानी में किस तरह चित्रित किया गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>भारतीय ग्रामीण व कृषक संस्कृति में मनुष्य और पशु का संबंध केवल स्वामी और सेवक का नहीं, बल्कि एक परिवार के अभिन्न सदस्य जैसा होता है। कहानी में इसके दो परस्पर विरोधी पक्ष दिखाए गए हैं:</p>\n<ul>\n  <li><strong>आत्मीयता व प्रेम का संबंध (झूरी का चरित्र):</strong> झूरी अपने दोनों बैलों (हीरा-मोती) से पुत्रवत स्नेह करता था। वह उन्हें कभी मारता-पीटता नहीं था। उनके घर लौटने पर झूरी की आँखों से आनंद के आँसू बहने लगे और पूरा गाँव उनका स्वागत करता है।</li>\n  <li><strong>शोषण व स्वार्थ का संबंध (गया का चरित्र):</strong> गया जैसे स्वार्थी और संवेदनहीन लोग पशुओं से केवल कठोर श्रम लेना जानते हैं, उन्हें भरपेट भोजन या स्नेह नहीं देते।</li>\n</ul>\n<p>प्रेमचंद जी ने यह संदेश दिया है कि पशु भी केवल प्रेम और सम्मान की भाषा समझते हैं; यदि किसान उन्हें प्रेम दे, तो वे अपना सर्वस्व न्योछावर कर देते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">झूरी के माध्यम से भावनात्मक पारिवारिक संबंध का निरूपण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गया के माध्यम से स्वार्थी शोषण की तुलना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ग्रामीण परिवेश में पशु-मानव सहअस्तित्व का सार</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">‘इतना तो हो ही गया कि नौ-दस प्राणियों की जान बच गई। वे सब तो आशीर्वाद देंगे’ — मोती के इस कथन के आलोक में उसकी विशेषताएँ बताइए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>मोती के इस कथन से उसके चरित्र की निम्नलिखित उदात्त विशेषताएँ प्रकट होती हैं:</p>\n<ul>\n  <li><strong>परोपकारी व दयालु स्वभाव:</strong> कांजीहौस की दीवार तोड़कर उसने घोड़ों, बकरियों, गधों और भैंसों को आजाद कराया। अपनी जान जोखिम में डालकर भी उसने असहाय मूक प्राणियों की रक्षा की।</li>\n  <li><strong>सकारात्मक एवं आशावादी दृष्टिकोण:</strong> खुद न भाग पाने और पुनः पकड़े जाने पर भी उसे निराशा नहीं हुई; उसे संतोष था कि उसके प्रयास से अनेक निर्दोष जीवों का जीवन बच गया।</li>\n  <li><strong>अदम्य विद्रोही साहस:</strong> वह अन्याय और अत्याचार को मूक रहकर सहने के पक्ष में नहीं था; उसने संगठित सत्ता के प्रतीक कांजीहौस की दीवार को ढहा दिया।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परोपकार एवं निस्वार्थ सेवा भाव का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आशावादिता एवं विद्रोही स्वभाव का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch1-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch1-q9')\">\n      <div class=\"q-num\">प्रश्न 9</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए:<br>(क) 'अवश्य ही उनमें कोई ऐसी गुप्त शक्ति थी, जिससे जीवों में श्रेष्ठता का दावा करने वाला मनुष्य वंचित है।'<br>(ख) 'उस एक रोटी से उनकी भूख तो क्या शांत होती; पर दोनों के हृदय को मानो भोजन मिल गया।'</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम कथन का आशय:</strong><br>\nमनुष्य स्वयं को समस्त सृष्टि का सर्वश्रेष्ठ प्राणी मानता है क्योंकि उसके पास विकसित बुद्धि और वाणी है। परंतु हीरा और मोती बिना बोले, केवल मूक भाव से एक-दूसरे के मन की बात, पीड़ा और प्रेम को समझ लेते थे। मनुष्य अपने स्वार्थ, छल-कपट और अहंकार के कारण इस निस्वार्थ संवेदनात्मक 'मूक प्रेम की शक्ति' से वंचित हो चुका है।</p>\n<p><strong>(ख) द्वितीय कथन का आशय:</strong><br>\nविशालकाय बैलों के लिए एक छोटी-सी रोटी पेट भरने के लिए नगण्य थी। परंतु उस रोटी में छोटी अनाथ बच्ची का निस्वार्थ प्रेम, करुणा और आत्मीयता समाहित थी। उस प्रेममयी अनुभूति ने बैलों की आत्मा को तृप्त कर दिया और उन्हें यह अहसास कराया कि इस निर्दयी संसार में भी कोई उनका अपना है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): मूक प्रेम व मनुष्य के अहंकार पर व्यंग्य की व्याख्या</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): प्रेम व आत्मीयता की आत्मिक तृप्ति का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की सटीकता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 1</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">हीरा और मोती का संघर्ष भारत के स्वाधीनता संग्राम की किस ऐतिहासिक भावना का प्रतिनिधित्व करता है? सविस्तार स्पष्ट कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>'दो बैलों की कथा' केवल दो पशुओं की कहानी नहीं है, बल्कि यह परोक्ष रूप से तत्कालीन पराधीन भारत और स्वतंत्रता संग्राम का जीवंत रूपक है। जिस प्रकार हीरा और मोती को बिना किसी अपराध के गया के घर और बाद में कांजीहौस में गुलाम बना दिया गया, उसी प्रकार भारतीय जनता ब्रिटिश साम्राज्य के अधीन शोषित थी।</p><p>बैलों का बार-बार रस्सियाँ तोड़ना, संगठित होकर अत्याचार का मुकाबला करना और अंत तक हार न मानना यह सिखाता है कि आज़ादी मुफ्त में नहीं मिलती; उसके लिए निरंतर त्याग, बलिदान और एकजुटता की आवश्यकता होती है। प्रेमचंद जी ने बैलों के माध्यम से देशवासियों में स्वाधीनता की अलख जगाने का कार्य किया।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">आज के आधुनिक समाज में जहाँ स्वार्थ और एकाकीपन बढ़ रहा है, हीरा और मोती की मित्रता से युवा पीढ़ी क्या सीख ले सकती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज के भौतिकवादी युग में संबंध अक्सर स्वार्थ, लाभ-हानि और दिखावे पर टिके होते हैं। ऐसे समय में हीरा और मोती की मित्रता अनुकरणीय आदर्श प्रस्तुत करती है। वे सुख और दुःख दोनों में अविभाज्य रहे। जब मोती कांजीहौस से भाग सकता था, उसने अपने मित्र हीरा का साथ नहीं छोड़ा।</p><p>युवा पीढ़ी को यह समझना होगा कि सच्ची मित्रता संकट की घड़ी में त्याग, परस्पर विश्वास, समान संवेदनशीलता और बिना शर्त सहयोग की माँग करती है। मित्रता का आधार भौतिक लाभ नहीं, बल्कि आत्मिक जुड़ाव होना चाहिए।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <div></div>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "2": "<section class=\"chapter-section\" id=\"ch2\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (गद्य खंड)</div>\n      <h2>ल्हासा की ओर</h2>\n      <p>राहुल सांकृत्यायन | गद्य खंड (यात्रा-वृत्तांत) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch2-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">थोंग्ला के पहले के आखिरी गाँव पहुँचने पर भिखमंगे के वेश में होने के बावजूद लेखक को ठहरने के लिए उचित स्थान मिला जबकि दूसरी यात्रा के समय भद्र वेश में भी उन्हें उचित स्थान नहीं दिला सका। क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>इसके मुख्य कारण निम्नलिखित थे:</p>\n<ul>\n  <li><strong>सुमति की व्यक्तिगत जान-पहचान व प्रभाव:</strong> पहली यात्रा के समय लेखक के साथ बौद्ध भिक्षु 'सुमति' थे। उस गाँव में सुमति के अनेक यजमान और परिचित रहते थे। सुमति के प्रभाव और आदर के कारण भिखमंगे के वेश में होने पर भी लेखक को ठहरने के लिए सबसे अच्छी जगह मिली।</li>\n  <li><strong>समय और ग्रामीणों की मनोवृत्ति:</strong> दूसरी यात्रा के समय लेखक शाम के वक्त गाँव पहुँचा था। शाम के समय तिब्बत के लोग 'छङ्' (नशीला स्थानीय पेय) पीकर होश-हवास खो बैठते थे और अतिथि-सत्कार की परवाह नहीं करते थे।</li>\n  <li><strong>जातिगत या आत्मीय संबंध का अभाव:</strong> दूसरी यात्रा में सुमति साथ नहीं थे और भद्र वेश होने पर भी किसी स्थानीय व्यक्ति से आत्मीय परिचय न होने के कारण उन्हें एक गरीब के साधारण झोंपड़े में शरण लेनी पड़ी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुमति के प्रभाव और यजमानों के सत्कार का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शाम के समय 'छङ्' पीने और ग्रामीणों की मानसिकता का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा-शैली व वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch2-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">उस समय के तिब्बत में हथियार का कानून न रहने के कारण यात्रियों को किस प्रकार का भय बना रहता था?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>1929-30 के आसपास तिब्बत में आग्नेयास्त्र (बंदूक, पिस्तौल आदि) रखने संबंधी कोई सरकारी कानून या नियंत्रण नहीं था। लोग लाठी की तरह खुलेआम पिस्तौल और बंदूक लेकर घूमते थे।</p>\n<p><strong>यात्रियों को भय के कारण:</strong></p>\n<ul>\n  <li><strong>डाकुओं का आतंक:</strong> तिब्बत के निर्जन पर्वतीय मार्गों (डाँड़े) में मीलों तक कोई पुलिस चौकी या गश्त नहीं होती थी। डाकू राहगीरों को देखते ही पहले मार डालते थे और बाद में उनकी जेबें टटोलते थे कि उनके पास पैसा या सामान है या नहीं।</li>\n  <li><strong>खून का कोई सुराग न मिलना:</strong> सुनसान बीहड़ में खून हो जाने पर कोई गवाह नहीं मिलता था और न ही सरकार गुप्तचर विभाग पर धन खर्च करती थी। इसलिए यात्रियों को सदैव प्राण जाने का भय सताता रहता था।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हथियार कानून के अभाव और लाठी की तरह बंदूक रखने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">डाकुओं की नृशंस हत्यारी कार्यप्रणाली एवं बीहड़ रास्तों का खतरा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध एवं सुस्पष्ट अभिव्यक्ति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch2-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखक ने शेखर विहार में सुमति को उनके यजमानों के पास जाने से रोका, परंतु दूसरी बार रोकने का प्रयास क्यों नहीं किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>पहली बार रोकने का कारण:</strong> लेखक को डर था कि सुमति यदि आसपास के गाँवों में अपने यजमानों को 'गंडे' (मंत्रपूत कपड़े की ताबीज) बाँटने जाएँगे, तो उन्हें लौटने में हफ्तों लग जाएँगे, जिससे लेखक की यात्रा में अनावश्यक विलंब हो जाएगा।</p>\n<p><strong>दूसरी बार न रोकने का कारण:</strong> शेखर विहार के बौद्ध मंदिर में लेखक को तिब्बती अनुवाद की हस्तलिखित 'कंजूर' (बुद्धवचन अनुवाद) की 103 भारी-भरकम दुर्लभ पोथियाँ मिल गईं। लेखक अध्ययनप्रिय और जिज्ञासु स्वभाव के थे। वे उन ज्ञानवर्धक पोथियों के गंभीर अध्ययन में पूरी तरह लीन होना चाहते थे। अतः एकांत में शांत अध्ययन के उद्देश्य से उन्होंने सुमति को खुशी-खुशी यजमानों के पास जाने की अनुमति दे दी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पहली बार समय की बर्बादी व विलंब के भय का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दूसरी बार कंजूर की 103 पोथियों के अध्ययन में लीन होने का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं व्याकरणिक शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch2-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">अपनी यात्रा के दौरान लेखक को किन कठिनाइयों का सामना करना पड़ा?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>राहुल सांकृत्यायन जी को अपनी प्रथम तिब्बत यात्रा के दौरान अनेक असाधारण एवं दुर्गम कठिनाइयों का सामना करना पड़ा:</p>\n<ol>\n  <li><strong>छद्म वेश धारण करने की विवशता:</strong> उस समय भारतीयों को तिब्बत यात्रा की कानूनी अनुमति नहीं थी, अतः लेखक को भिखमंगे (छद्म भिक्षुक) के फटे-पुराने वेश में जान जोखिम में डालकर यात्रा करनी पड़ी।</li>\n  <li><strong>डाकुओं और हत्यारों का निरंतर भय:</strong> डाँड़े के बीहड़ जंगलों और घाटियों में डाकुओं से जान बचाने के लिए उन्हें 'कुची-कुची' (दया-दया) कहकर भीख माँगने का नाटक करना पड़ता था।</li>\n  <li><strong>प्रतिकूल मौसम एवं ऊँचाई:</strong> 17,000-18,000 फीट की अत्यधिक ऊँचाई पर कड़ाके की ठंड, तेज बर्फीली हवा और दूसरी ओर सामने से तेज धूप का तीखा ताप सहना पड़ा।</li>\n  <li><strong>घोड़े की सुस्ती एवं रास्ता भटकना:</strong> लङ्कोर के विकट चढ़ाई वाले मार्ग पर लेखक का घोड़ा बहुत सुस्त था, जिससे वे अपने साथियों से बहुत पीछे छूट गए और रास्ता भटककर गलत दिशा में डेढ़-दो मील आगे निकल गए।</li>\n  <li><strong>भारी बोझ स्वयं ढोना:</strong> सामान लादने के लिए कुली या खच्चर न मिलने पर उन्हें अपनी पीठ पर भारी सामान लादकर पैदल चलना पड़ा।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भिखमंगे के वेश में यात्रा व डाकुओं के भय का बिंदु</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कठिन भौगोलिक परिस्थिति (ऊँचाई, मौसम, भारी बोझ) का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रास्ता भटकने और सुस्त घोड़े की घटना का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रमबद्ध एवं प्रभावशाली प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch2-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">प्रस्तुत यात्रा-वृत्तांत के आधार पर बताइए कि उस समय का तिब्बती समाज कैसा था?</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>राहुल सांकृत्यायन के यात्रा-वृत्तांत 'ल्हासा की ओर' से तत्कालीन (लगभग 1929) तिब्बती समाज के विभिन्न पक्षों की सजीव झाँकी मिलती है:</p>\n<ul>\n  <li><strong>सकारात्मक एवं प्रगतिशील पक्ष:</strong>\n    <ul>\n      <li><strong>जाति-पाँति व छुआछूत का अभाव:</strong> तिब्बती समाज में जातिगत भेदभाव या ऊँच-नीच की भावना नहीं थी।</li>\n      <li><strong>पर्दा-प्रथा से मुक्ति:</strong> महिलाएँ किसी भी प्रकार का पर्दा नहीं करती थीं और उन्हें सामाजिक स्वतंत्रता प्राप्त थी।</li>\n      <li><strong>अतिथि-सत्कार की सरलता:</strong> कोई भी अपरिचित व्यक्ति किसी के भी घर के भीतर तक जाकर अपनी चाय बनवा सकता था या अपनी सामग्री देकर पचवा सकता था (सिवाय संदिग्ध भिखमंगों के चोरी के डर से)।</li>\n    </ul>\n  </li>\n  <li><strong>नकारात्मक एवं सामंती पक्ष:</strong>\n    <ul>\n      <li><strong>जागीरदारी एवं बौद्ध मठों (विहारों) का वर्चस्व:</strong> जमीन छोटे-बड़े जागीरदारों में बँटी थी। अधिकांश जमीन मठों की संपत्ति थी। मठ के भिक्षु जागीर के बेगार मजदूरों से काम करवाते थे और वे राजा के समान पूज्य थे।</li>\n      <li><strong>सुरक्षा एवं कानून-व्यवस्था का अभाव:</strong> हथियारों का कोई कानून न होने से डाकुओं का आतंक था और पुलिस प्रशासन अत्यंत शिथिल था।</li>\n      <li><strong>अंधविश्वास एवं धार्मिक रूढ़िवादिता:</strong> लोग बोधगया से लाए गए सामान्य कपड़ों के गंडों (ताबीजों) को चमत्कारी मानकर खरीदते थे।</li>\n    </ul>\n  </li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामाजिक समानता (छुआछूत व पर्दा प्रथा का न होना) का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अतिथि सत्कार एवं महिलाओं की स्थिति का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामंती व्यवस्था, मठों के आधिपत्य एवं कानूनहीनता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संतुलित निष्कर्ष एवं उत्कृष्ट भाषा-प्रवाह</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch2-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">‘मैं अब पुस्तकों के भीतर था।’ नीचे दिए गए विकल्पों में से कौन-सा इस वाक्य का अर्थ बतलाता है?<br>(क) लेखक पुस्तकें पढ़ने में रम गया।<br>(ख) लेखक पुस्तकों की शेल्फ़ के भीतर चला गया।<br>(ग) लेखक के चारों ओर पुस्तकें ही थीं।<br>(घ) पुस्तक में लेखक का परिचय और चित्र छपा था।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>सही उत्तर:</strong> <strong>(क) लेखक पुस्तकें पढ़ने में रम गया।</strong></p>\n<p><strong>व्याख्या:</strong> 'पुस्तकों के भीतर होना' एक लाक्षणिक मुहावरेदार प्रयोग है। इसका अर्थ यह है कि शेखर विहार के मंदिर में जब राहुल सांकृत्यायन को 'कंजूर' (बुद्धवचन) की 103 भारी हस्तलिखित पोथियाँ मिलीं, तो वे बाह्य संसार, यात्रा की थकान और सुमति की उपस्थिति को भूलकर पूरी तन्मयता, एकाग्रता और आत्मविस्मृति के साथ उनके पठन-पाठन में पूरी तरह लीन (निमग्न) हो गए थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सही विकल्प (क) का स्पष्ट चयन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लाक्षणिक अर्थ (अध्ययन में तन्मयता) की संक्षिप्त व्याख्या</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch2-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch2-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">सुमति के व्यक्तित्व की प्रमुख विशेषताओं पर प्रकाश डालिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>सुमति लेखक के सहयात्री, मार्गदर्शक और एक मंगोल बौद्ध भिक्षु थे। उनके व्यक्तित्व की प्रमुख विशेषताएँ निम्नलिखित हैं:</p>\n<ul>\n  <li><strong>मिलनसार एवं हंसमुख स्वभाव:</strong> सुमति बेहद मिलनसार थे। तिब्बत के लगभग प्रत्येक गाँव में उनके परिचित और यजमान थे, जो उनका बहुत सम्मान करते थे।</li>\n  <li><strong>व्यावहारिक एवं चतुर:</strong> वे लोगों की धार्मिक भावनाओं को भली-भाँति समझते थे और बोधगया के कपड़े के गंडे बाँटकर अपनी आजीविका और दक्षिणा प्राप्त कर लेते थे।</li>\n  <li><strong>शीघ्र क्रोधी किंतु शांत होने वाले:</strong> लेखक के देर से पहुँचने पर वे तुरंत आगबबूला हो गए, परंतु लेखक द्वारा कारण स्पष्ट करते ही उनका गुस्सा तुरंत शांत हो गया। वे एक सच्चे और निष्कपट मित्र थे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मिलनसारिता व व्यापक सामाजिक संपर्क का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यावहारिक बुद्धि एवं सरल/निष्कपट स्वभाव का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 2</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">राहुल सांकृत्यायन की तिब्बत यात्रा आज के आधुनिक पर्यटन से किस प्रकार भिन्न थी? यात्रा से व्यक्ति के दृष्टिकोण में क्या परिवर्तन आते हैं?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज का पर्यटन आधुनिक सुविधाओं, इंटरनेट, सुगम मार्गों और सुरक्षा साधनों से परिपूर्ण है। इसके विपरीत, राहुल सांकृत्यायन की यात्रा दुर्गम, प्रतिबंधित, साधनहीन और जान जोखिम में डालकर की गई थी। उन्हें भिखमंगे के वेश में पैदल और सुस्त घोड़ों पर कई सौ मील तय करने पड़े।</p><p>ऐसी साहसिक यात्राएँ मनुष्य को प्रतिकूल परिस्थितियों से जूझना, विभिन्न संस्कृतियों का पूर्वाग्रहमुक्त होकर सम्मान करना तथा मानवीय जीवन की कठिनाइयों के प्रति संवेदनशील बनाती हैं। यात्रा केवल मनोरंजन नहीं, बल्कि आत्म-विकास और ज्ञान की खोज का सशक्त माध्यम है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">सुमति द्वारा बाँटे जाने वाले 'गंडों' की घटना समाज में व्याप्त किस रूढ़िवादी प्रवृत्ति को दर्शाती है? आज के वैज्ञानिक युग में इसका क्या समाधान होना चाहिए?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>सुमति लाल कपड़े के टुकड़ों को बोधगया का पवित्र ताबीज बताकर यजमानों को बाँटते थे और जब बोधगया का कपड़ा समाप्त हो जाता, तो किसी भी सामान्य कपड़े से गंडे बना लेते थे। यह अंधविश्वास, अज्ञानता और धर्म के बाह्याडंबर को दर्शाता है जहाँ लोग आस्था के नाम पर विवेक का उपयोग नहीं करते।</p><p>वैज्ञानिक युग में इसका समाधान शिक्षा का प्रसार, तर्कसंगत सोच और अंधानुकरण के स्थान पर धर्म के मूल नैतिक मूल्यों (सत्य, करुणा, सेवा) को अपनाने में है। अंधविश्वास केवल तभी समाप्त हो सकता है जब समाज विवेकशील बने।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(1)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "3": "<section class=\"chapter-section\" id=\"ch3\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (गद्य खंड)</div>\n      <h2>उपभोक्तावाद की संस्कृति</h2>\n      <p>श्यामाचरण दुबे | गद्य खंड (निबंध) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch3-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक के अनुसार जीवन में 'सुख' से क्या अभिप्राय है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>सामान्यतः और पारंपरिक रूप से 'सुख' का अर्थ मानसिक शांति, आत्मिक संतोष, शारीरिक स्वास्थ्य और सद्कर्मों से मिलने वाला परमानंद माना जाता था।</p>\n<p>परंतु आज की उपभोक्तावादी संस्कृति में 'सुख' की परिभाषा पूरी तरह बदल गई है:</p>\n<ul>\n  <li><strong>उपभोग ही सुख:</strong> आज भौतिक वस्तुओं, विलासिता के साधनों और बाजार के नए-नए उत्पादों का निरंतर भोग करना ही 'सुख' मान लिया गया है (भोग ही सुख बन गया है)।</li>\n  <li><strong>कृत्रिम संतुष्टि:</strong> लेखक व्यंग्य करते हैं कि आज उपभोग की वस्तुएँ मनुष्य की सेवा के लिए नहीं हैं, बल्कि मनुष्य स्वयं को उत्पादों को समर्पित कर रहा है। बाह्य चमक-दमक और तात्कालिक शारीरिक तृप्ति को ही सच्चा सुख समझ लिया गया है, जो कि एक भ्रामक स्थिति है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारंपरिक आत्मिक सुख बनाम आधुनिक उपभोग-सुख की तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उपभोग सामग्री के प्रति अंधसमर्पण पर निबंधकार के व्यंग्य का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch3-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">आज की उपभोक्तावादी संस्कृति हमारे दैनिक जीवन को किस प्रकार प्रभावित कर रही है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>उपभोक्तावादी संस्कृति ने हमारे दैनिक जीवन के हर पहलू को गहराई से रूपांतरित और विकृत कर दिया है:</p>\n<ol>\n  <li><strong>बाजार का सम्मोहन और विज्ञापनों का जाल:</strong> टूथपेस्ट, साबुन, तेल से लेकर परिधानों तक हम विज्ञापनों के बहकावे में आकर जरूरत न होने पर भी अंधाधुंध खरीदारी करते हैं।</li>\n  <li><strong>दिखावे की अंधी दौड़:</strong> लोग अपनी आर्थिक क्षमता से बाहर जाकर महंगे फोन, घड़ियाँ, गाड़ियाँ और यहाँ तक कि पांच सितारा अस्पतालों व होटलों की संस्कृति को अपना रहे हैं ताकि समाज में झूठी प्रतिष्ठा बनाई जा सके।</li>\n  <li><strong>सामाजिक संबंधों में दूरियाँ व अशांति:</strong> भौतिक वस्तुओं के लोभ ने पारिवारिक प्रेम, आत्मीयता और नैतिक मर्यादाओं को पीछे धकेल दिया है। समाज में असंतोष, ईर्ष्या और अशांति फैल रही है।</li>\n  <li><strong>सांस्कृतिक पहचान का क्षरण:</strong> हमारी पारंपरिक जीवन-शैली, सादगी और आत्मनियंत्रण समाप्त हो रहा है और हम पश्चिमी संस्कृति की अंधी दासता स्वीकार कर रहे हैं।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाजार और विज्ञापनों के प्रभाव का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दिखावे की प्रवृत्ति और आर्थिक विवशता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामाजिक संबंधों एवं सांस्कृतिक क्षरण का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुव्यवस्थित भाषा-प्रवाह</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch3-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखक ने उपभोक्ता संस्कृति को हमारे समाज के लिए चुनौती क्यों कहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>लेखक ने उपभोक्ता संस्कृति को हमारे समाज के लिए गंभीर चुनौती इसलिए कहा है क्योंकि यह हमारी सांस्कृतिक जड़ों और सामाजिक ताने-बाने को भीतर से खोखला कर रही है:</p>\n<ul>\n  <li><strong>गांधीजी के आदर्शों की उपेक्षा:</strong> महात्मा गांधी ने कहा था कि हमें अपनी नींव पर सुदृढ़ रहते हुए स्वस्थ वैश्विक विचारों का स्वागत करना चाहिए। परंतु उपभोक्ता संस्कृति हमारी नींव ही हिला रही है।</li>\n  <li><strong>सीमित संसाधनों का अंधाधुंध अपव्यय:</strong> दिखावे और उपभोग के चक्कर में प्रकृति और समाज के अमूल्य संसाधनों का विनाश हो रहा है।</li>\n  <li><strong>सामाजिक असमानता व आक्रोश:</strong> समाज का एक छोटा वर्ग विलासिता में डूबा है जबकि बहुसंख्यक अभावग्रस्त है। यह खाई आगे चलकर सामाजिक विस्फोट और हिंसा को जन्म दे सकती है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गांधीजी के चिंतन और सांस्कृतिक नींव के खतरे का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संसाधनों का अपव्यय एवं वर्ग-विभेद की चुनौती का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक शब्दावली व निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch3-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए:<br>(क) 'जाने-अनजाने आज के माहौल में आपका चरित्र भी बदल रहा है और आप उत्पाद को समर्पित होते जा रहे हैं।'<br>(ख) 'प्रतिष्ठा के अनेक रूप होते हैं, चाहे वे हास्यास्पद ही क्यों न हों।'</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम कथन का आशय:</strong><br>\nउपभोक्तावादी संस्कृति इतनी सूक्ष्म और चालाक है कि मनुष्य को पता भी नहीं चलता और उसकी रुचियाँ, प्राथमिकताएँ और जीवन-मूल्य बदल जाते हैं। पहले मनुष्य अपनी बुनियादी आवश्यकताओं के लिए वस्तुएँ खरीदता था, परंतु आज उत्पाद मनुष्य पर हावी हो गए हैं। मनुष्य अपनी गरिमा भूलकर केवल विज्ञापनों और बाजार का गुलाम बन गया है।</p>\n<p><strong>(ख) द्वितीय कथन का आशय:</strong><br>\nसमाज में झूठी वाहवाही और प्रतिष्ठा पाने के लिए मनुष्य ऐसे-ऐसे विचित्र और मूर्खतापूर्ण कार्य करता है जो दूसरों की दृष्टि में हास्यास्पद लगते हैं। उदाहरण के लिए, अमेरिका में मरने से पहले ही लाखों रुपये देकर अपनी कब्र के चारों ओर सुंदर बगीचा, फव्वारे और संगीत की स्थायी व्यवस्था करवाना। यह दिखावे की अंधी सनक का चरम रूप है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): बाजार की गुलामी और मानसिक चरित्र-परिवर्तन का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): झूठी प्रतिष्ठा एवं अमेरिका की कब्र वाले दृष्टांत का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch3-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">कोई वस्तु हमारे लिए उपयोगी हो या न हो, लेकिन टी.वी. पर विज्ञापन देखकर हम उसे खरीदने के लिए लालायित होते हैं। क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>टी.वी. और सोशल मीडिया पर दिखाए जाने वाले विज्ञापन अत्यंत मनोवैज्ञानिक और सम्मोहक होते हैं:</p>\n<ul>\n  <li><strong>दृश्य-श्रव्य का सम्मोहन:</strong> विज्ञापन में आकर्षक दृश्यों, कर्णप्रिय संगीत और प्रसिद्ध अभिनेताओं/खिलाड़ियों का उपयोग कर उत्पाद को सीधे मनुष्य की आकांक्षाओं और सुंदर दिखने की इच्छा से जोड़ दिया जाता है।</li>\n  <li><strong>प्रतिष्ठा और हीनभावना का खेल:</strong> विज्ञापन यह भ्रम पैदा करते हैं कि यदि आपके पास यह उत्पाद नहीं है, तो आप आधुनिक और श्रेष्ठ नहीं हैं। इससे व्यक्ति में हीनभावना जागती है और वह भीड़ से अलग न दिखने के लिए वस्तु खरीदने को विवश हो जाता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विज्ञापनों की मनोवैज्ञानिक सम्मोहन शक्ति का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सेलिब्रिटी प्रभाव एवं झूठी प्रतिष्ठा की भावना का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अभिव्यक्ति की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch3-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch3-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">आपके अनुसार वस्तुओं को खरीदने का आधार वस्तु की गुणवत्ता होनी चाहिए या उसका विज्ञापन? तर्क देकर स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>हमारे अनुसार वस्तुओं को खरीदने का एकमात्र विवेकपूर्ण आधार <strong>वस्तु की वास्तविक गुणवत्ता और उसकी उपयोगिता</strong> होनी चाहिए, न कि उसका लुभावना विज्ञापन।</p>\n<p><strong>तर्क:</strong></p>\n<ul>\n  <li><strong>विज्ञापनों की अतिशयोक्ति:</strong> विज्ञापनों का मुख्य उद्देश्य उत्पाद बेचना होता है, जिसके लिए वे अक्सर झूठे और भ्रामक दावे करते हैं। विज्ञापन देखकर खरीदी गई वस्तु अक्सर घटिया और निरर्थक साबित होती है।</li>\n  <li><strong>आर्थिक सुरक्षा एवं स्वास्थ्य:</strong> गुणवत्तापूर्ण वस्तु लंबे समय तक चलती है, पैसे की बचत करती है और स्वास्थ्य व पर्यावरण को नुकसान नहीं पहुँचाती। अतः एक जागरूक उपभोक्ता को विज्ञापन के सम्मोहन से बचकर विवेक से निर्णय लेना चाहिए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गुणवत्ता को आधार मानने का स्पष्ट एवं तर्कपूर्ण पक्ष</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विज्ञापनों के भ्रामक दावों और उपभोक्ता जागरूकता का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा-प्रवाह व निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 3</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">उपभोक्तावाद के दौर में प्रकृति और पर्यावरण पर पड़ रहे घातक प्रभावों पर प्रकाश डालते हुए बताइए कि एक जिम्मेदार नागरिक के रूप में हमें क्या करना चाहिए?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>उपभोक्तावादी संस्कृति 'यूज एंड थ्रो' (उपयोग करो और फेंको) के सिद्धांत पर चलती है। अत्यधिक उपभोग के कारण प्राकृतिक संसाधनों का बेरहमी से दोहन हो रहा है, प्लास्टिक और इलेक्ट्रॉनिक कचरे का अंबार लग रहा है तथा कार्बन उत्सर्जन से जलवायु परिवर्तन हो रहा है।</p><p>एक जिम्मेदार नागरिक के रूप में हमें 'सादा जीवन, उच्च विचार' के सिद्धांत को अपनाना चाहिए। आवश्यकता और विलासिता में अंतर समझना चाहिए, पुनर्चक्रण (Recycle) को बढ़ावा देना चाहिए तथा केवल दिखावे के लिए वस्तुएँ खरीदने से बचना चाहिए। प्रकृति का संरक्षण ही मानवता का भविष्य सुरक्षित कर सकता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">सोशल मीडिया पर 'अनबॉक्सिंग' और 'लक्ज़री लाइफस्टाइल इन्फ्लुएंसर्स' का युवा पीढ़ी पर क्या प्रभाव पड़ रहा है? निबंध के संदर्भ में विश्लेषण कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज इंस्टाग्राम, यूट्यूब आदि पर इन्फ्लुएंसर्स द्वारा प्रदर्शित विलासितापूर्ण जीवन-शैली श्यामाचरण दुबे के 'उपभोक्तावाद की संस्कृति' का ही डिजिटल विस्तार है। इसे देखकर युवाओं में असंतोष, अवसाद और अवास्तविक अपेक्षाएँ जन्म ले रही हैं।</p><p>युवा अपनी वास्तविक आर्थिक स्थिति को भुलाकर कर्ज लेकर भी महंगे गैजेट्स और कपड़े खरीदने की अंधी होड़ में शामिल हो रहे हैं। इससे आंतरिक खुशी के बजाय बाह्य मान्यता पर निर्भरता बढ़ रही है। युवाओं को यह सिखाना जरूरी है कि स्क्रीन पर दिखने वाली चमक-दमक प्रायः प्रायोजित और कृत्रिम होती है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(2)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "4": "<section class=\"chapter-section\" id=\"ch4\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">4</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (गद्य खंड)</div>\n      <h2>साँवले सपनों की याद</h2>\n      <p>जाबिर हुसैन | गद्य खंड (डायरी शैली संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch4-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">किस घटना ने सालिम अली के जीवन की दिशा को बदल दिया और उन्हें पक्षी प्रेमी बना दिया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बचपन में सालिम अली को उनके मामा ने खेलने के लिए एक एयरगन (शिकारी खिलौना बंदूक) उपहार में दी थी। अनजाने में सालिम अली की एयरगन से चली छर्रे की गोली से नीले कंठ वाली एक छोटी-सी घरेलू गौरैया घायल होकर नीचे गिर पड़ी।</p>\n<p>घायल तड़पती हुई उस नन्ही गौरैया की पीड़ा और बेबसी ने बालक सालिम अली के हृदय को भीतर तक झकझोर दिया। वे दया और ग्लानि से भर गए। उन्होंने उस गौरैया की तीमारदारी (सेवा) की।</p>\n<p>उस एक मूक पक्षी की करुण दशा ने सालिम अली के मन में पक्षियों के प्रति असीम जिज्ञासा, संवेदना और प्रेम जगा दिया। उन्होंने अपनी पूरी जिंदगी पक्षियों के संरक्षण, खोज और अध्ययन के लिए समर्पित कर दी और वे विश्वविख्यात 'बर्ड वॉचर' (पक्षी-विज्ञानी) बन गए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बचपन में एयरगन से गौरैया के घायल होने की घटना का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हृदय-परिवर्तन एवं पक्षी-विज्ञानी बनने की यात्रा का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch4-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">सालिम अली ने पूर्व प्रधानमंत्री चौधरी चरण सिंह के सामने पर्यावरण से संबंधित किन संभावित खतरों का चित्र खींचा होगा कि जिससे उनकी आँखें नम हो गई थीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>चौधरी चरण सिंह जी गाँव की मिट्टी से जुड़े किसान नेता थे और प्रकृति व ग्रामीण परिवेश के प्रति अत्यंत संवेदनशील थे।</p>\n<p>सालिम अली ने केरल की प्रसिद्ध 'साइलेंट वैली' (शांत घाटी) को रेगिस्तानी गर्म हवा के झोंकों और पारिस्थितिकी असंतुलन से बचाने के लिए प्रधानमंत्री से भेंट की थी। उन्होंने निम्नलिखित संभावित खतरों का मार्मिक चित्र प्रस्तुत किया:</p>\n<ul>\n  <li>यदि साइलेंट वैली की प्राकृतिक हरियाली और सघन वर्षावन नष्ट हो गए, तो वहां की दुर्लभ वनस्पतियाँ और पक्षियों की प्रजातियाँ हमेशा के लिए विलुप्त हो जाएँगी।</li>\n  <li>पर्यावरण के विनाश से वर्षा चक्र बिगड़ेगा और उपजाऊ भूमि बंजर मरुस्थल में बदल जाएगी।</li>\n</ul>\n<p>मिट्टी की सोंधी महक को समझने वाले प्रधानमंत्री प्रकृति के इस भीषण विनाश की कल्पना मात्र से द्रवित हो गए और उनकी आँखें नम हो गईं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">केरल की साइलेंट वैली और गर्म हवाओं के खतरे का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुर्लभ प्रजातियों के विनाश और पर्यावरणीय संकट का मार्मिक वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चौधरी चरण सिंह की संवेदनशीलता का संदर्भ</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch4-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लॉरेंस की पत्नी फ्रीडा ने ऐसा क्यों कहा होगा कि 'मेरी छत पर बैठने वाली गौरैया लॉरेंस के बारे में ढेर सारी बातें जानती है?'</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>डी.एच. लॉरेंस प्रकृति के अनन्य प्रेमी थे। उनका जीवन बनावटीपन और आडंबर से कोसों दूर, प्रकृति के साथ सहज, नैसर्गिक और आत्मिक रूप से जुड़ा हुआ था।</p>\n<p>लॉरेंस अपना अधिकांश समय छत पर बैठी गौरैयों और पक्षियों को निहारने, उनसे मूक संवाद करने और प्रकृति की गोद में बिताते थे। पक्षियों के साथ उनका रिश्ता मनुष्य की तुलना में अधिक गहरा, पारदर्शी और आत्मीय था।</p>\n<p>अतः जब पत्रकारों ने फ्रीडा से लॉरेंस के बारे में कुछ लिखने को कहा, तो उन्होंने विनम्रतापूर्वक यह सत्य प्रकट किया कि लॉरेंस का व्यक्तित्व इतना सरल और प्रकृति-समर्पित था कि उनके बारे में मुझसे भी अधिक वह गौरैया जानती है जो घंटों उनके साथ बैठती थी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">डी.एच. लॉरेंस के प्रकृति-प्रेम और निष्कपट जीवन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गौरैया के साथ मूक आत्मीय रिश्ते और फ्रीडा के कथन की सार्थकता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं अभिव्यक्ति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch4-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आशय स्पष्ट कीजिए:<br>(क) 'वो लॉरेंस की तरह, नैसर्गिक जिंदगी का प्रतिरूप बन गए थे।'<br>(ख) 'कोई अपने जिस्म की हरारत और दिल की धड़कन देकर भी उसे लौटाना चाहे तो वह पक्षी अपने सपनों के गीत दोबारा कैसे गा सकेगा!'<br>(ग) 'सालिम अली प्रकृति की दुनिया में एक टापू बनने की बजाए अथाह सागर बनकर उभरे थे।'</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम कथन का आशय:</strong><br>\nडी.एच. लॉरेंस की भाँति सालिम अली का जीवन भी पूरी तरह बनावट और कृत्रिमता से मुक्त था। वे प्रकृति के साथ एकाकार होकर जीते थे। प्रकृति उनके लिए कोई उपभोग की वस्तु नहीं, बल्कि उनका अपना अस्तित्व थी। वे नैसर्गिक (प्राकृतिक) जीवन का सजीव प्रतीक बन गए थे।</p>\n\n<p><strong>(ख) द्वितीय कथन का आशय:</strong><br>\nसालिम अली की मृत्यु पर लेखक अत्यंत शोकाकुल होकर यह सत्य व्यक्त करते हैं कि मृत्यु एक अंतिम और शाश्वत विश्राम है। सालिम अली उस मृत पक्षी के समान हैं जो अपनी अंतिम यात्रा पर निकल चुका है। अब संसार का कोई भी व्यक्ति अपने शरीर की गर्मी (प्राण) या हृदय की धड़कन देकर भी उस महान पक्षी-प्रेमी को पुनर्जीवित नहीं कर सकता। उनके गाए अनूठे सपनों के गीत अब हमेशा के लिए शांत हो चुके हैं।</p>\n\n<p><strong>(ग) तृतीय कथन का आशय:</strong><br>\n'टापू' एक सीमित, संकुचित और चारों ओर से बँधा हुआ भूभाग होता है, जबकि 'सागर' असीम, अथाह, गहरा और व्यापक होता है। सालिम अली की दृष्टि किसी संकीर्ण दायरे या भूगोल तक सीमित नहीं थी। उनका कार्यक्षेत्र, ज्ञान और पक्षियों के प्रति करुणा संपूर्ण पृथ्वी और अनंत आकाश जितनी विस्तृत थी। वे किसी बंधे हुए टापू की तरह नहीं, बल्कि एक असीम सागर की तरह सर्वसमावेशी थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): नैसर्गिक जीवन और लॉरेंस से साम्यता की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): मृत्यु की अटल सच्चाई और अपूरणीय क्षति का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): टापू (सीमित) बनाम सागर (विराट) के लाक्षणिक अर्थ का उद्घाटन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रवाहपूर्ण एवं भावपूर्ण भाषा-शैली</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch4-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch4-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">इस पाठ के आधार पर लेखक (जाबिर हुसैन) की भाषा-शैली की चार प्रमुख विशेषताएँ बताइए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>प्रस्तुत संस्मरण 'साँवले सपनों की याद' में जाबिर हुसैन की भाषा-शैली अत्यंत विशिष्ट और सम्मोहक है:</p>\n<ol>\n  <li><strong>डायरी शैली एवं संस्मरणात्मक भावुकता:</strong> लेखक ने डायरी विधा के आधार पर अत्यंत मार्मिक, आत्मीय और भावुक शैली में सालिम अली के व्यक्तित्व को उकेरा है।</li>\n  <li><strong>मिश्रित शब्दावली (भाषा का अनोखा संगम):</strong> भाषा में हिंदी के तत्सम शब्दों (नैसर्गिक, प्रतिरूप, अंतहीन) के साथ-साथ उर्दू और अंग्रेजी के प्रचलित शब्दों (सफर, सैलानी, हरारत, बर्ड वॉचर) का अत्यंत स्वाभाविक और सुंदर प्रयोग हुआ है।</li>\n  <li><strong>चित्रात्मकता एवं काव्यात्मकता:</strong> वाक्यों में गहरी प्रतीकात्मकता और चित्रात्मकता है। पढ़ते समय पाठक की आँखों के सामने दृश्य सजीव हो उठते हैं (जैसे 'गले में दूरबीन लटकाए...')।</li>\n  <li><strong>लाक्षणिक एवं मुहावरेदार प्रयोग:</strong> 'टापू बनने की बजाए अथाह सागर बनना', 'सपनों के गीत गाना' जैसे लाक्षणिक प्रयोग भाषा को गहरा अर्थ प्रदान करते हैं।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">डायरी शैली एवं मिश्रित शब्दावली (हिंदी-उर्दू) का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चित्रात्मकता, काव्यात्मकता एवं लाक्षणिक सौंदर्य का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उदाहरण सहित सुसंगठित प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 4</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">सालिम अली के जीवन से आधुनिक युवाओं को पर्यावरण एवं जैव-विविधता संरक्षण के लिए क्या प्रेरणा लेनी चाहिए?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज जब अंधाधुंध शहरीकरण, प्रदूषण और मोबाइल टॉवरों के रेडिएशन के कारण गौरैया, गिद्ध और अनेक पक्षियों की प्रजातियाँ संकटग्रस्त हो रही हैं, सालिम अली का जीवन एक मशाल की तरह है। उन्होंने सिखाया कि प्रकृति केवल इंसानों की जागीर नहीं है, इसमें मूक पशु-पक्षियों का भी बराबर का हक है।</p><p>युवाओं को केवल उपभोक्ता बनने के बजाय पर्यावरण प्रहरी बनना चाहिए। अपने घरों की छतों पर पक्षियों के लिए दाना-पानी रखना, पेड़ों की कटाई का विरोध करना और प्राकृतिक पारिस्थितिकी तंत्र को बचाने के लिए सक्रिय योगदान देना ही सालिम अली के प्रति सच्ची श्रद्धांजलि होगी।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">'साँवले सपनों की याद' शीर्षक की सार्थकता पर अपने विचार व्यक्त कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>'साँवले सपने' उन मीठे, सुनहरे और मनमोहक सपनों का प्रतीक हैं जो सालिम अली ने पक्षियों के संरक्षण और प्रकृति की रक्षा के लिए आजीवन देखे थे। सालिम अली की मृत्यु के साथ वे सपने अब केवल स्मृतियों (यादों) में शेष रह गए हैं।</p><p>यहाँ 'साँवले' शब्द में एक हल्का-सा दुःख, उदासी और रहस्य समाहित है, जो मृत्यु के शोक और सालिम अली के अधूरे पर्यावरण-संकल्पों को दर्शाता है। अतः यह शीर्षक संस्मरण के भाव, कथ्य और वातावरण को अत्यंत मार्मिक ढंग से अभिव्यक्त करने के कारण पूर्णतः सार्थक और उपयुक्त है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(3)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "5": "<section class=\"chapter-section\" id=\"ch5\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">5</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (गद्य खंड)</div>\n      <h2>प्रेमचंद के फटे जूते</h2>\n      <p>हरिशंकर परसाई | गद्य खंड (व्यंग्य निबंध) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch5-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">हरिशंकर परसाई ने प्रेमचंद का जो शब्दचित्र हमारे सामने प्रस्तुत किया है उससे प्रेमचंद के व्यक्तित्व की कौन-कौन सी विशेषताएँ उभरकर आती हैं?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>परसाई जी द्वारा प्रस्तुत शब्दचित्र से मुंशी प्रेमचंद जी के महान एवं उदात्त व्यक्तित्व की निम्नलिखित विशेषताएँ प्रकट होती हैं:</p>\n<ol>\n  <li><strong>सादगीपूर्ण एवं आडंबरहीन जीवन:</strong> प्रेमचंद दिखावे और बनावटीपन से कोसों दूर थे। वे जैसे भीतर थे, वैसे ही बाहर थे। फोटो खिंचवाने जैसे महत्वपूर्ण अवसर पर भी वे मोटे कपड़े का कुर्ता, धोती और फटा जूता पहने सहज भाव से खड़े हैं।</li>\n  <li><strong>स्वाभिमानी एवं समझौताविहीन स्वभाव:</strong> वे परिस्थितियों के आगे कभी झुके नहीं और न ही उन्होंने अपनी दरिद्रता को छुपाने के लिए किसी से जूते माँगे। उन्होंने समाज की कुरीतियों और शोषण के विरुद्ध हमेशा संघर्ष किया, कभी उनसे समझौता नहीं किया।</li>\n  <li><strong>अपराजेय एवं दृढ़ संकल्पी:</strong> उनके चेहरे पर एक तीखा, आत्मविश्वास भरा दर्द और व्यंग्यपूर्ण मुसकान है, जो यह दर्शाती है कि अभाव भी उनके आत्मबल को डिगा नहीं सके।</li>\n  <li><strong>महान सामाजिक सरोकार:</strong> वे 'उपन्यास सम्राट' और 'युग प्रवर्तक' थे, फिर भी उनका जीवन आम जनता और किसानों के दुखों के साथ पूरी तरह एकाकार था।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सादगी एवं बाह्याडंबर से मुक्ति का बिंदु</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वाभिमान, निर्भीकता एवं समझौता न करने की प्रवृत्ति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यंग्यपूर्ण मुसकान एवं सामाजिक सरोकार का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की उत्कृष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch5-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">नीचे दी गई पंक्तियों में निहित व्यंग्य को स्पष्ट कीजिए:<br>(क) 'जूता हमेशा टोपी से कीमती रहा है। अब तो जूते की कीमत और बढ़ गई है और एक जूते पर पचीसों टोपियाँ न्योछावर होती हैं।'<br>(ख) 'तुम परदे का महत्व ही नहीं जानते, हम परदे पर कुर्बान हो रहे हैं!'<br>(ग) 'जिसे तुम घृणित समझते हो, उसकी तरफ हाथ की नहीं, पाँव की अंगुली से इशारा करते हो?'</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम पंक्ति में व्यंग्य:</strong><br>\n'टोपी' मान-सम्मान, विद्वत्ता, मर्यादा और उच्च विचारों का प्रतीक है, जबकि 'जूता' शक्ति, अधिकार, धन-दौलत और भौतिक प्रभुत्व का प्रतीक है। समाज की विडंबना यह है कि समाज में गुणी, विद्वान और विचारवान व्यक्तियों (टोपी) को धनवान, भ्रष्ट और सत्तालोलुप लोगों (जूते) के चरणों में झुकना पड़ता है। आज धन और भौतिक शक्ति के आगे नैतिकता और आत्मसम्मान को बार-बार कुर्बान किया जाता है।</p>\n\n<p><strong>(ख) द्वितीय पंक्ति में व्यंग्य:</strong><br>\n'परदा' दुर्गुणों, कमजोरियों, दरिद्रता और बुराइयों को छुपाने (दिखावे की प्रवृत्ति) का प्रतीक है। संसार अपनी कमियों को ढँकने के लिए झूठ और ढोंग का सहारा लेता है और प्रतिष्ठा बनाए रखने पर अपना सर्वस्व लुटा देता है। इसके विपरीत प्रेमचंद इतने निष्कपट, सरल और पारदर्शी थे कि वे अपनी फटेहाली को ढँकने का कोई प्रयास नहीं करते।</p>\n\n<p><strong>(ग) तृतीय पंक्ति में व्यंग्य:</strong><br>\nसामान्यतः मनुष्य किसी श्रेष्ठ या आदरणीय वस्तु की ओर हाथ की उँगली से इशारा करता है। परंतु प्रेमचंद समाज की सड़ी-गली कुरीतियों, छूआछूत, शोषण और पाखंड को इतना घृणित, नीच और तुच्छ मानते थे कि उनकी ओर हाथ की उँगली उठाना भी हाथ का अपमान समझते थे। अतः वे अपने फटे जूते से निकली पैर की उँगली से उन पर प्रहार और इशारा करते थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): टोपी (सम्मान/बुद्धि) बनाम जूता (धन/सत्ता) के व्यंग्य का उद्घाटन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): परदा (दिखावा/छल) बनाम प्रेमचंद की पारदर्शिता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ग): पैर की उँगली द्वारा सामाजिक विद्रूपताओं पर तीखे प्रहार की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं सुस्पष्ट तर्क</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch5-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">पाठ में एक जगह पर लेखक सोचता है कि 'फोटो खिचाने की अगर यह पोशाक है तो पहनने की कैसी होगी?' लेकिन अगले ही पल वह विचार बदलता है कि 'नहीं, इस आदमी की अलग-अलग पोशाकें नहीं होंगी।' आपके अनुसार लेखक के विचार बदलने की क्या वजहें हो सकती हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>लेखक के विचार बदलने के निम्नलिखित मुख्य कारण थे:</p>\n<ul>\n  <li><strong>सामान्य सांसारिक मानसिकता:</strong> आम लोग घर में पहनने के लिए साधारण कपड़े रखते हैं और बाहर जाने या फोटो खिंचवाने के लिए विशेष व सुंदर पोशाक रखते हैं। लेखक ने पहले इसी सामान्य दृष्टि से सोचा।</li>\n  <li><strong>प्रेमचंद के अनूठे व्यक्तित्व का बोध:</strong> अगले ही क्षण लेखक को अहसास हुआ कि प्रेमचंद कोई साधारण दिखावटी इंसान नहीं हैं। वे छल-कपट, दोहरे चरित्र और बनावटीपन से सर्वथा मुक्त हैं। जो व्यक्ति अंदर से जैसा है, बाहर से भी वैसा ही है। उनका संपूर्ण जीवन एक खुली किताब है, इसलिए उनके पास दोहरी पोशाकें हो ही नहीं सकतीं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामान्य मानवीय दोहरे व्यवहार का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेमचंद के निष्कपट एवं पारदर्शी व्यक्तित्व की पहचान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch5-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">'तुम भी जूते और टोपी के आनुपातिक मूल्य के मारे हुए थे' — यहाँ लेखक समाज की किस विडंबना की ओर संकेत कर रहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>यहाँ लेखक समाज की अत्यंत कड़वी और दुखद विडंबना की ओर संकेत कर रहा है:</p>\n<p>समाज में हमेशा से ही गुण, ज्ञान, साहित्य और नैतिकता (टोपी) की तुलना में भौतिक समृद्धि, धनबल और चाटुकारिता (जूते) को अधिक महत्व और प्रतिष्ठा दी जाती रही है। प्रेमचंद जैसे महान साहित्यकार, जिन्होंने समाज को अमूल्य कृतियाँ दीं, आजीवन आर्थिक तंगी और अभाव में फटे जूते पहनकर जीते रहे; जबकि चाटुकार और धनी लोग ठाठ-बाट से जीते हैं। यह गुणवानों की उपेक्षा और धन के अनुचित प्रभुत्व की सामाजिक त्रासदी है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ज्ञान/साहित्य बनाम धन/सत्ता के असंतुलन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेमचंद की उपेक्षा और सामाजिक संवेदनहीनता पर व्यंग्य</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा-शैली व व्याकरण</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch5-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch5-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">आपने यह व्यंग्य पढ़ा। इसे पढ़कर आपको लेखक (हरिशंकर परसाई) की कौन-सी बातें सबसे अधिक आकर्षित करती हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>परसाई जी के इस व्यंग्य निबंध में निम्नलिखित बातें पाठक को सर्वाधिक आकर्षित करती हैं:</p>\n<ul>\n  <li><strong>गंभीर सामाजिक विद्रूपताओं पर चोट:</strong> लेखक केवल जूते के फटने पर नहीं हँसते, बल्कि उसके माध्यम से दिखावे की संस्कृति, स्वार्थपरता और साहित्यिक उपेक्षा पर करारा प्रहार करते हैं।</li>\n  <li><strong>सहज, चुटीली और मुहावरेदार भाषा:</strong> परसाई जी की व्यंग्य-शैली इतनी पैनी है कि वह पाठक को हँसाते-हँसाते सोचने और आत्ममंथन करने पर विवश कर देती है।</li>\n  <li><strong>प्रेमचंद के प्रति अगाध आदर:</strong> व्यंग्य करते हुए भी लेखक का प्रेमचंद के प्रति अपार सम्मान और निष्ठा हर पंक्ति में छलकती है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्यंग्य के माध्यम से सामाजिक विसंगतियों के उद्घाटन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पैनी भाषा-शैली एवं प्रेमचंद के प्रति सम्मान का निरूपण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रस्तुति की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 5</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">आज के आधुनिक समाज में 'दिखावे की प्रवृत्ति' किस प्रकार मानसिक तनाव और अपराध को बढ़ावा दे रही है? पाठ के आधार पर समाधान प्रस्तुत कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज का समाज 'परदे पर कुर्बान' हो रहा है। लोग अपनी असली हैसियत छिपाकर दूसरों को प्रभावित करने के लिए महंगे वस्त्र, गैजेट्स और लाइफस्टाइल का प्रदर्शन करते हैं। जब आमदनी और दिखावे में असंतुलन बढ़ता है, तो व्यक्ति भारी कर्ज, मानसिक तनाव, हीनभावना और अवसाद का शिकार हो जाता है। कुछ युवा तो दिखावे की हवस पूरी करने के लिए साइबर अपराध और चोरी के रास्ते पर चल पड़ते हैं।</p><p>इसका एकमात्र समाधान प्रेमचंद के आदर्शों में निहित है। हमें सादगी, ईमानदारी और स्वाभिमान को जीवन का मूलमंत्र बनाना होगा। हमारी पहचान हमारे ज्ञान, चरित्र और कर्मों से होनी चाहिए, न कि हमारे जूते या परिधान से।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'प्रेमचंद के फटे जूते' पाठ में प्रयुक्त 'टीला' शब्द किस सामाजिक यथार्थ का प्रतीक है? समझाइए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>पाठ में 'टीला' मार्ग में आने वाले उस कठोर अवरोध का प्रतीक है जो प्राकृतिक नहीं, बल्कि मानव-निर्मित है। यह टीला समाज में व्याप्त जातिवाद, अंधविश्वास, भ्रष्टाचार, कुप्रथाओं और अन्यायपूर्ण व्यवस्था का प्रतिनिधित्व करता है।</p><p>आम लोग ऐसे टीलों से बचकर या समझौता करके बगल से रास्ता निकालकर निकल जाते हैं। परंतु प्रेमचंद जैसे क्रांतिकारी लेखक समझौते के विरोधी थे। उन्होंने इन सामाजिक कुरीतियों रूपी टीलों पर अपने जूते की ठोकरें मारीं, भले ही इससे उनका जूता फट गया और पैर लहूलुहान हो गया, पर उन्होंने सत्य का मार्ग नहीं छोड़ा।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(4)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "6": "<section class=\"chapter-section\" id=\"ch6\" data-book=\"kshitij-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">6</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (गद्य खंड)</div>\n      <h2>मेरे बचपन के दिन</h2>\n      <p>महादेवी वर्मा | गद्य खंड (संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch6-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">'मैं उत्पन्न हुई तो बड़ी खातिर हुई और मुझे वह सब नहीं सहना पड़ा जो अन्य लड़कियों को सहना पड़ता है।' इस कथन के आलोक में आप उस समय की लड़कियों की स्थिति पर विचार व्यक्त कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेवी वर्मा जी के इस कथन से तत्कालीन भारतीय समाज में बालिकाओं की अत्यंत दयनीय, उपेक्षित और शोचनीय दशा का पता चलता है:</p>\n<ul>\n  <li><strong>कन्या-जन्म को अभिशाप मानना:</strong> उस समय समाज में पुत्र-प्राप्ति को ही प्रतिष्ठा और मोक्ष का साधन माना जाता था। लड़की का जन्म होते ही परिवार में मातम छा जाता था और कई परिवारों में तो 'परमधाम' भेजने (अर्थात जन्म लेते ही मार डालने / कन्या भ्रूण हत्या) की क्रूर प्रथा व्याप्त थी।</li>\n  <li><strong>शिक्षा और विकास से वंचित रखना:</strong> लड़कियों को घर की चारदीवारी तक सीमित रखा जाता था। उन्हें शिक्षा प्राप्त करने का अधिकार नहीं था और बचपन में ही बाल-विवाह के बंधन में झोंक दिया जाता था।</li>\n  <li><strong>महादेवी जी का सौभाग्य:</strong> महादेवी जी के कुल में दो सौ वर्षों तक कोई लड़की पैदा नहीं हुई थी। जब वे जन्मीं तो उनके बाबा ने उन्हें दुर्गा की कृपा मानकर अत्यधिक लाड़-प्यार दिया और विदुषी बनाने का संकल्प लिया। अतः उन्हें वह पारिवारिक प्रताड़ना नहीं सहनी पड़ी जो उस काल की अन्य बालिकाओं की नियति थी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तत्कालीन समाज में कन्या-शिशु हत्या व उपेक्षा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लड़कियों की शिक्षा-वंचितता एवं बाल-विवाह का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महादेवी जी के पारिवारिक परिवेश और बाबा के प्रगतिशील दृष्टिकोण का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch6-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">लेखिका उर्दू-फ़ारसी क्यों नहीं सीख पाईं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेवी जी के बाबा चाहते थे कि वे उर्दू और फ़ारसी की अच्छी ज्ञाता बनें, क्योंकि उस समय प्रशासनिक और राजकाज की भाषा में उर्दू-फ़ारसी का बड़ा महत्व था। इसके लिए घर पर एक मौलवी साहब को पढ़ाने के लिए नियुक्त किया गया।</p>\n<p>परंतु जब पहले दिन मौलवी साहब पढ़ाने आए, तो बालिका महादेवी उनसे इतना डर गईं कि वे जाकर सीधे चारपाई के नीचे छिप गईं। उनके मन में मौलवी साहब और उस भाषा के प्रति ऐसा भय और अरुचि बैठ गई कि वे दोबारा उनके सामने नहीं आईं। इस प्रकार भय और स्वाभाविक रुचि के अभाव के कारण लेखिका उर्दू-फ़ारसी नहीं सीख सकीं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाबा की इच्छा और मौलवी साहब के आने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चारपाई के नीचे छिपने और भय/अरुचि का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch6-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखिका ने अपनी माँ के व्यक्तित्व की किन विशेषताओं का उल्लेख किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेवी वर्मा जी ने अपनी माँ (हेमरानी देवी) के व्यक्तित्व की निम्नलिखित अनुपम विशेषताएँ बताई हैं:</p>\n<ul>\n  <li><strong>धार्मिक एवं सात्विक प्रवृत्ति:</strong> उनकी माँ अत्यंत धर्मपरायण स्त्री थीं। वे नियमित रूप से पूजा-पाठ करती थीं और प्रतिदिन सवेरे 'प्रभातफेरी' के पद तथा 'मीरा के पद' भावविभोर होकर गाती थीं।</li>\n  <li><strong>हिंदी और संस्कृत की विदुषी:</strong> जबलपुर से आते समय वे अपने साथ हिंदी की पुस्तकें लाई थीं। उन्होंने ही महादेवी को सबसे पहले 'पंचतंत्र' पढ़ना सिखाया और संस्कृत के श्लोकों की शिक्षा दी।</li>\n  <li><strong>साहित्यिक संस्कार:</strong> वे स्वयं भी सुंदर पद लिखा करती थीं। महादेवी के भीतर कविता रचने का प्रारंभिक बीज और साहित्य के प्रति अगाध अनुराग उनकी माँ के ही संस्कारों की देन था।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धार्मिक स्वभाव एवं मीरा के पदों के गायन का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिंदी-संस्कृत ज्ञान और पंचतंत्र पढ़ाने का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महादेवी में साहित्यिक संस्कारों के बीजारोपण की भूमिका</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch6-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">जवारा के नवाब के साथ अपने पारिवारिक संबंधों को लेखिका ने आज के संदर्भ में 'स्वप्न जैसा' क्यों कहा है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेवी वर्मा के परिवार और जवारा के नवाब के परिवार के बीच अत्यंत आत्मीय, प्रगाढ़ और पारिवारिक संबंध थे, जिसमें धर्म की कोई दीवार नहीं थी:</p>\n<ul>\n  <li><strong>सांस्कृतिक व पारिवारिक एकता:</strong> बेगम साहिबा को महादेवी जी 'ताई' कहती थीं और उनके बच्चे महादेवी की माँ को 'चाची' कहते थे। नवाब के घर में हर त्योहार (मुहर्रम, ईद, राखी, दीवाली) मिलकर मनाया जाता था।</li>\n  <li><strong>धार्मिक भेदभाव से मुक्ति:</strong> राखी के दिन बेगम साहिबा अपने बेटों से तब तक खाना नहीं खाने देती थीं जब तक महादेवी उन्हें राखी न बाँध दें। नवाब साहब के बेटे का नामकरण भी महादेवी के परिवार ने 'मनमोहन' रखा था।</li>\n  <li><strong>आज के संदर्भ में स्वप्न क्यों:</strong> आज समाज में धर्म, जाति और संप्रदाय के नाम पर संकीर्णता, अविश्वास और नफरत की दीवारें खड़ी हो गई हैं। ऐसा निष्कपट प्रेम, साझी संस्कृति और हिंदू-मुस्लिम सौहार्द आज के खंडित समाज में दुर्लभ हो गया है, इसलिए लेखिका को वह बीता हुआ सुंदर समय एक सुनहरे स्वप्न जैसा प्रतीत होता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जवारा के नवाब परिवार के साथ आत्मीय रिश्तों (ताई, राखी, त्योहार) का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सांप्रदायिक सौहार्द एवं गंगा-जमुनी तहजीब का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आज की सांप्रदायिक कटुता से तुलना और 'स्वप्न' कहे जाने की सार्थकता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch6-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">सुभद्रा कुमारी चौहान और महादेवी वर्मा के बीच क्रास्थवेट गर्ल्स कॉलेज के छात्रावास में किस प्रकार की मित्रता थी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>क्रास्थवेट गर्ल्स कॉलेज के छात्रावास में महादेवी जी की भेंट अपनी सीनियर छात्रा सुभद्रा कुमारी चौहान से हुई, जो आगे चलकर अमर मित्रता में बदल गई:</p>\n<ul>\n  <li><strong>बड़ी बहन जैसा संरक्षण:</strong> सुभद्रा जी महादेवी से दो साल बड़ी थीं। उन्होंने महादेवी को एक स्नेहमयी बड़ी बहन की तरह दुलार और संरक्षण दिया।</li>\n  <li><strong>साहित्यिक प्रेरणा एवं सहभागिता:</strong> सुभद्रा जी पहले से ही 'खड़ी बोली' में प्रसिद्ध कवयित्री थीं। जब उन्हें महादेवी की तुकांत कविताओं का पता चला, तो उन्होंने पूरे छात्रावास में घूम-घूमकर महादेवी की प्रतिभा की घोषणा की। दोनों पेड़ की डालियों पर बैठकर साथ-साथ कविताएँ रचती थीं और कवि सम्मेलनों में भाग लेती थीं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">छात्रावास में भेंट एवं बड़ी बहन जैसे संरक्षण का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">साहित्यिक साझेदारी, कविता पाठ एवं कवि सम्मेलनों की भागीदारी</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch6-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch6-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">गांधी जी को महादेवी जी ने जो चाँदी का कटोरा दिखाया था, उससे संबंधित प्रेरक प्रसंग का वर्णन कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेवी वर्मा को एक कवि सम्मेलन में अपनी सुंदर कविता पाठ के लिए प्रथम पुरस्कार के रूप में एक बहुत नक्काशीदार चाँदी का कटोरा मिला था, जिसे पाकर वे फूली नहीं समा रही थीं।</p>\n<p>उस समय महात्मा गांधी जी आनंद भवन (इलाहाबाद) में ठहरे हुए थे। महादेवी जी बड़े गर्व से अपना कटोरा बापू को दिखाने पहुँचीं। गांधी जी ने कटोरा हाथ में लेकर देखा और हँसते हुए बोले—'तू यह कटोरा मुझे देश के स्वाधीनता कोष के लिए दान में देगी?'</p>\n<p>महादेवी जी ने बिना किसी संकोच के अपना प्रिय पुरस्कार राष्ट्रपिता के हाथों में देश-सेवा के लिए समर्पित कर दिया। बापू ने उनसे कहा कि 'कवि सम्मेलन का पुरस्कार लौटाना तो ठीक है, पर तू मुझे अपनी कविता भी सुना।' यह प्रसंग महादेवी जी के देशप्रेम और गांधी जी के प्रति अगाध श्रद्धा को दर्शाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चाँदी का कटोरा पुरस्कार में मिलने का प्रसंग</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गांधीजी द्वारा देश सेवा कोष के लिए माँगने और महादेवी के सहर्ष दान का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की प्रभावशीलता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 6</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">महादेवी वर्मा के संस्मरण से सीख लेकर आज के भारत में सांप्रदायिक सद्भाव और राष्ट्रीय एकता को कैसे सुदृढ़ किया जा सकता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>महादेवी वर्मा के बचपन में जवारा के नवाब और उनके परिवार का संबंध भारत की साझी संस्कृति ('गंगा-जमुनी तहजीब') का जीवंत प्रमाण है। वहाँ धर्म मनुष्य के आत्मीय रिश्तों के बीच कभी बाधा नहीं बना। रक्षाबंधन और ईद एक साथ पूरे उल्लास से मनाए जाते थे।</p><p>आज के भारत में जब राजनीतिक और संकीर्ण स्वार्थों के कारण समाज को बाँटने का प्रयास किया जाता है, हमें इस संस्मरण से यह सीख लेनी चाहिए कि मानवीय संवेदना, परस्पर सम्मान और प्रेम ही सच्चा धर्म है। हमें एक-दूसरे के त्योहारों, रीति-रिवाजों का आदर करना चाहिए तथा राष्ट्रीय एकता को सर्वोपरि रखना चाहिए।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">महादेवी वर्मा के परिवार में नारी शिक्षा को जो प्रोत्साहन मिला, उसने उनके जीवन को कैसे रूपांतरित किया? आज भी यह उदाहरण प्रासंगिक क्यों है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>ऐसे युग में जब बेटियों को अभिशाप मानकर मार दिया जाता था, महादेवी के बाबा और माता-पिता ने उन्हें न केवल विदुषी बनाने का संकल्प लिया बल्कि जबलपुर और इलाहाबाद के श्रेष्ठ शिक्षण संस्थानों में भेजा। इसी प्रगतिशील सोच के कारण महादेवी वर्मा छायावाद के चार प्रमुख स्तंभों में स्थापित हुईं और भारत की शीर्ष विदुषी व ज्ञानपीठ पुरस्कार विजेता बनीं।</p><p>आज भी भारत के कई ग्रामीण और रूढ़िवादी क्षेत्रों में बेटियों की शिक्षा को गौण माना जाता है। यह पाठ सिखाता है कि यदि बेटियों को समान अवसर, शिक्षा और पारिवारिक संबल मिले, तो वे राष्ट्र और समाज को ज्ञान के सर्वोच्च शिखर पर पहुँचा सकती हैं।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(5)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "7": "<section class=\"chapter-section\" id=\"ch7\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">7</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>साखियाँ एवं सबद</h2>\n      <p>कबीरदास | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">मानसरोवर सुभर जल, हंसा केलि कराहिं।\nमुक्ताफल मुक्ता चुगैं, अब उड़ि अनत न जाहिं।।\nप्रेमी ढूँढ़त मैं फिरौं, प्रेमी मिलै न कोइ।\nप्रेमी कौं प्रेमी मिलै, सब विष अमृत होइ।।\nहस्ती चढ़िये ग्यान कौ, सहज दुलीचा डारि।\nस्वान रूप संसार है, भूंकन दे झख मारि।।\nपखापखी के कारनै, सब जग रहा भुलान।\nनिरपख होइ कै हरि भजै, सोई संत सुजान।।\nहिंदू मूआ राम कहि, मुसलमान खुदाइ।\nकहै कबीर सो जीवता, जो दुहुँ के निकटि न जाइ।।\nकाबा फिरि कासी भया, रामहिं भया रहीम।\nमोट चून मैदा भया, बैठि कबीरा जीम।।\nऊँचे कुल का जनमिया, जे करनी ऊँच न होइ।\nसुबरन कलस सुरा भरा, साधू निंदै सोइ।।</div>\n    <div class=\"poet-name\">— संत कबीरदास</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास — साखियाँ (100% कवरेज)</div>\n\n  <div class=\"q-card\" id=\"ch7-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">‘मानसरोवर’ से कवि का क्या आशय है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कबीरदास जी के दोहे में 'मानसरोवर' के दो अर्थ ध्वनित होते हैं:</p>\n<ul>\n  <li><strong>स्थूल (भौतिक) अर्थ:</strong> हिमालय पर्वत पर स्थित अत्यंत पवित्र, निर्मल और स्वच्छ जल से भरी वह प्रसिद्ध प्राकृतिक झील जहाँ हंस क्रीड़ा करते हैं और मोती चुगते हैं।</li>\n  <li><strong>सूक्ष्म (आध्यात्मिक) अर्थ:</strong> साधक का पवित्र 'मन' अथवा सहस्रार चक्र (हृदय रूपी मानसरोवर), जो ईश्वरीय भक्ति, ज्ञान और आनंद के अमृत जल से लबालब भरा हुआ है। यहाँ जीवात्मा रूपी हंस मुक्ति का आनंद भोगता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भौतिक अर्थ (पवित्र हिमालयी झील) का उल्लेख</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आध्यात्मिक अर्थ (निर्मल हृदय/सहस्रार चक्र व जीवात्मा) का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवि ने सच्चे प्रेमी की क्या कसौटी बताई है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कबीरदास जी के अनुसार सच्चे ईश्वर-प्रेमी (सच्चे भक्त) की कसौटी यह है कि जब एक सच्चा प्रेमी दूसरे सच्चे प्रेमी से मिलता है, तो दोनों के मन का समस्त 'विष' (काम, क्रोध, मद, मोह, अहंकार, ईर्ष्या और वासनाएँ) 'अमृत' (सद्गुण, आनंद, प्रेम और पवित्रता) में रूपांतरित हो जाता है।</p>\n<p>अर्थात सच्चे भक्त के संपर्क में आते ही समस्त सांसारिक विकार और दुर्भावनाएँ स्वतः नष्ट हो जाती हैं और अंतःकरण निर्मल आनंद से भर जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दो सच्चे प्रेमियों के मिलन का प्रसंग</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विष (दुर्गुण/विकार) के अमृत (सद्गुण/शांति) में बदलने की कसौटी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">तीसरे दोहे में कवि ने किस प्रकार के ज्ञान को महत्व दिया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>तीसरे दोहे <em>('हस्ती चढ़िये ग्यान कौ, सहज दुलीचा डारि...')</em> में कबीरदास जी ने <strong>सहज समाधि और अनुभवजन्य आध्यात्मिक ज्ञान</strong> को सर्वोच्च महत्व दिया है।</p>\n<ul>\n  <li><strong>सहज साधना:</strong> ज्ञान ऐसा होना चाहिए जो आडंबर, अहंकार और दिखावे से मुक्त हो। 'सहज दुलीचा' का अर्थ है सहज, स्वाभाविक और अहंकार-रहित साधना का आसन।</li>\n  <li><strong>लोक-निंदा की उपेक्षा:</strong> जब हाथी चलता है तो गली के कुत्ते अकारण भौंकते हैं। उसी प्रकार ज्ञानी साधक को अज्ञानी संसार की व्यर्थ आलोचनाओं, तानों और निंदा की रत्ती भर भी परवाह किए बिना अपनी साधना में अडिग रहना चाहिए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अनुभवजन्य सहज ज्ञान एवं अहंकार-मुक्ति का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हाथी और कुत्ते के रूपक द्वारा लोक-निंदा की उपेक्षा का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रस्तुति एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">इस संसार में सच्चा संत कौन कहलाता है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कबीरदास जी के चौथे दोहे <em>('पखापखी के कारनै, सब जग रहा भुलान। निरपख होइ कै हरि भजै, सोई संत सुजान।।')</em> के अनुसार:</p>\n<p>इस संसार में 'सच्चा संत' (सुजान) वही है जो 'पखापखी' अर्थात पक्ष-विपक्ष, संप्रदायवाद, तर्क-वितर्क और धार्मिक कट्टरता के विवादों में न उलझकर <strong>निष्पक्ष (निरपख) भाव से केवल एक परमात्मा की सच्ची भक्ति</strong> में लीन रहता है। जो व्यक्ति जात-पाँत, धर्म-भेद और बाह्याडंबरों से ऊपर उठकर समभाव से प्राणीमात्र की सेवा और प्रभु का स्मरण करता है, वही सच्चा संत है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पक्ष-विपक्ष और संप्रदायवाद से परे रहने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निष्पक्ष (निरपख) भक्ति एवं समभाव का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं व्याकरण</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">अंतिम दो दोहों के माध्यम से कबीर ने किस तरह की संकीर्णताओं की ओर संकेत किया है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>अंतिम दो दोहों में कबीरदास जी ने तत्कालीन और आज के समाज में व्याप्त दो प्रमुख संकीर्णताओं पर तीखा प्रहार किया है:</p>\n<ol>\n  <li><strong>धार्मिक एवं सांप्रदायिक संकीर्णता:</strong> हिंदू 'राम' के नाम पर और मुसलमान 'खुदा' के नाम पर लड़-झगड़ कर मर मिटते हैं। वे यह नहीं समझते कि ईश्वर एक ही है। जब मनुष्य का अज्ञान रूपी मोटा आटा पिसकर बारीक मैदा बन जाता है, तो काबा ही काशी बन जाता है और राम ही रहीम हो जाते हैं। दोनों स्थानों पर एक ही निराकार प्रभु की ज्योति है।</li>\n  <li><strong>उच्च कुल और जातिगत श्रेष्ठता का अहंकार:</strong> समाज में लोग केवल उच्च कुल या जाति में जन्म लेने के आधार पर स्वयं को श्रेष्ठ और दूसरों को नीच समझते हैं। कबीर कहते हैं कि यदि किसी व्यक्ति के कर्म नीच हैं, तो ऊँचे कुल में जन्म लेने से वह महान नहीं बन सकता; ठीक उसी प्रकार जैसे सोने के कलश में यदि शराब भरी हो, तो साधुजन उसकी निंदा ही करते हैं।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिंदू-मुस्लिम के धार्मिक भेदभाव एवं काबा-काशी की एकता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जातिगत/कुलीनता के झूठे दंभ और सोने के कलश-सुरा दृष्टांत की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कर्म की प्रधानता का संदेश</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">किसी भी व्यक्ति की पहचान उसके कुल से होती है या उसके कर्मों से? तर्क सहित उत्तर दीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>किसी भी व्यक्ति की वास्तविक पहचान और श्रेष्ठता उसके <strong>सद्कर्मों, आचरण और नैतिक चरित्र से होती है, उसके कुल या जाति से कदापि नहीं।</strong></p>\n<p><strong>तर्क:</strong></p>\n<ul>\n  <li>रावण परम विद्वान महर्षि पुलस्त्य के कुल का ब्राह्मण था, परंतु अपने अहंकारी और अधर्मी कर्मों के कारण वह आज भी दुष्टता का प्रतीक माना जाता है।</li>\n  <li>इसके विपरीत, संत कबीर, रैदास और महर्षि वाल्मीकि तथाकथित निम्न कुलों में जन्मे थे, परंतु अपने उच्च विचारों, त्याग और पवित्र कर्मों के कारण वे विश्ववंदनीय महापुरुष बने। सोने के बर्तन में मदिरा भर देने से वह अमृत नहीं बन जाती।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कर्म को प्रधान मानने का सुदृढ़ पक्ष</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रावण अथवा संतों के सटीक उदाहरण द्वारा तर्क</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निष्कर्ष एवं भाषा-प्रवाह</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">काव्य-सौंदर्य स्पष्ट कीजिए:<br><em>'हस्ती चढ़िये ग्यान कौ, सहज दुलीचा डारि।<br>स्वान रूप संसार है, भूंकन दे झख मारि।।'</em></div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>भाव-सौंदर्य:</strong> कबीरदास जी साधक को यह उपदेश देते हैं कि उसे ज्ञान रूपी विशाल हाथी पर सहज साधना रूपी आसन बिछाकर निश्चिंत होकर आगे बढ़ना चाहिए। अज्ञानी संसार भौंकने वाले कुत्ते के समान है, जिसकी व्यर्थ आलोचनाओं पर ध्यान दिए बिना अपने लक्ष्य की ओर बढ़ते रहना चाहिए।</p>\n<p><strong>शिल्प-सौंदर्य:</strong></p>\n<ul>\n  <li><strong>भाषा:</strong> जनभाषा (सधुक्कड़ी / पंचमेल खिचड़ी), जो अत्यंत सजीव और प्रवाहपूर्ण है।</li>\n  <li><strong>अलंकार:</strong> 'हस्ती चढ़िये ग्यान कौ' और 'स्वान रूप संसार' में <em>सांगरूपक अलंकार</em> का सुंदर प्रयोग हुआ है।</li>\n  <li><strong>छंद व रस:</strong> यह दोहा छंद में रचित है तथा इसमें शांत रस का परिपाक हुआ है। 'झख मारि' मुहावरे का लोक-सुलभ प्रयोग हुआ है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाव-सौंदर्य (ज्ञान, सहजता, लोकनिंदा की उपेक्षा) की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिल्प-सौंदर्य (सधुक्कड़ी भाषा, रूपक अलंकार, दोहा छंद, मुहावरा)</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्याकरणिक शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास — सबद (पद 1) (100% कवरेज)</div>\n\n  <div class=\"q-card\" id=\"ch7-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">मनुष्य ईश्वर को कहाँ-कहाँ ढूँढ़ता फिरता है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>मनुष्य अपने अज्ञान के कारण ईश्वर को अपने भीतर न देखकर बाहर निम्नलिखित स्थानों पर खोजता फिरता है:</p>\n<ul>\n  <li>मंदिरों, देवालयों और मस्जिदों में,</li>\n  <li>मुसलमानों के पवित्र तीर्थ काबा तथा हिंदुओं के पवित्र धाम काशी और कैलाश पर्वत में,</li>\n  <li>विभिन्न कर्मकांडों, पूजा-पाठ, हवन, नमाज़ और यज्ञों में,</li>\n  <li>योग साधना, वैराग्य, जटा-जूट बढ़ाने अथवा संन्यास लेने के बाह्य आडंबरों में।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीर्थ स्थलों (मंदिर, मस्जिद, काबा, काशी, कैलाश) का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कर्मकांड, योग और संन्यास की साधना का वर्णन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q9\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q9')\">\n      <div class=\"q-num\">प्रश्न 9</div>\n      <div class=\"q-text\">कबीर ने ईश्वर-प्राप्ति के लिए किन प्रचलित विश्वासों का खंडन किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कबीरदास जी ने सबद (पद 1) में ईश्वर-प्राप्ति के उन सभी बाह्य आडंबरों का खंडन किया है जो तत्कालीन समाज में प्रचलित थे:</p>\n<ul>\n  <li><strong>मूर्ति पूजा एवं तीर्थाटन का खंडन:</strong> मंदिर, मस्जिद, काबा, काशी या कैलाश जाने से परमात्मा नहीं मिलते।</li>\n  <li><strong>दिखावटी कर्मकांड:</strong> यज्ञ, हवन, बलि, उपवास और दैनिक पूजा-पद्धति से मुक्ति नहीं मिलती।</li>\n  <li><strong>हठयोग और संन्यास का खंडन:</strong> घर-बार छोड़कर वैरागी बन जाना, शरीर पर भस्म मलना या कठोर योग साधना करना ईश्वर प्राप्ति का मार्ग नहीं है। कबीर के अनुसार ईश्वर पवित्र मन की सहज भक्ति से मिलते हैं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीर्थयात्रा एवं धार्मिक स्थलों के दिखावे का खंडन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कर्मकांड एवं हठयोग/संन्यास के खंडन का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch7-q10\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch7-q10')\">\n      <div class=\"q-num\">प्रश्न 10</div>\n      <div class=\"q-text\">कबीर ने ईश्वर को 'सब स्वाँसों की स्वाँस में' क्यों कहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कबीरदास जी निर्गुण-निराकार ईश्वर के उपासक हैं। उनके अनुसार परमात्मा कोई बाह्य सत्ता नहीं है जो किसी आकाश या विशेष इमारत में निवास करती हो।</p>\n<p>परमात्मा तो सर्वव्यापी, सर्वत्र विद्यमान और प्रत्येक जीव के प्राणों के मूल आधार हैं। जिस प्रकार प्रत्येक जीवित प्राणी में श्वास का स्पंदन है, उसी प्रकार उस प्राण-वायु की प्रत्येक धड़कन में परमात्मा का वास है। जैसे तिल में तेल और फूलों में सुगंध छिपी रहती है, वैसे ही घट-घट में ईश्वर रमण करते हैं। अतः उन्हें बाहर खोजने के बजाय अपने आत्म-अवलोकन से ही पाया जा सकता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ईश्वर की सर्वव्यापकता एवं घट-घट में वास का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्वास के स्पंदन और आत्म-तत्व से तादात्म्य की व्याख्या</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 7</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">कबीर का 'निरपख होइ कै हरि भजै' का सिद्धांत आज के वैश्वीकृत और विविध समाजों में शांति स्थापना के लिए किस प्रकार एक रामबाण औषधि सिद्ध हो सकता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कबीर का 'निरपख' (निष्पक्ष) भाव धार्मिक कट्टरता और सांप्रदायिक संकीर्णता की जड़ पर प्रहार करता है। आज विश्व भर में धर्म, नस्ल और संप्रदाय के नाम पर हो रही हिंसा का मूल कारण 'पखापखी' (पक्ष-विपक्ष का हठ) है।</p><p>यदि प्रत्येक मनुष्य यह समझ ले कि सभी धर्मों का सार एक ही सत्य और प्रेम है, तथा परमात्मा किसी एक संप्रदाय की निजी जागीर नहीं है, तो सारा वैमनस्य समाप्त हो जाएगा। कबीर की निष्पक्षता मनुष्य को संकीर्ण सीमाओं से ऊपर उठाकर विश्व-बंधुत्व और सर्वधर्म समभाव के सूत्र में बाँधती है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'ऊँचे कुल का जनमिया, जे करनी ऊँच न होइ' - आज के कॉरपोरेट और शैक्षणिक जगत में योग्यता (Merit) और कर्म की महत्ता के संदर्भ में इसकी प्रासंगिकता सिद्ध कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कबीरदास जी ने सदियों पहले यह स्पष्ट कर दिया था कि जन्म या पारिवारिक पृष्ठभूमि से कोई व्यक्ति महान नहीं होता, उसकी महत्ता केवल उसके ज्ञान, कौशल और नैतिक कर्मों से तय होती है।</p><p>आज के आधुनिक युग में योग्यता-आधारित व्यवस्था (Meritocracy) इसी सिद्धांत पर कार्य करती है। किसी बड़ी कंपनी या शीर्ष पद पर वही व्यक्ति सफल हो सकता है जिसके पास दक्षता, कठिन परिश्रम और ईमानदारी है, चाहे वह साधारण परिवार से ही क्यों न आया हो। वंशवाद और विशेषाधिकार के स्थान पर कर्मठता ही वास्तविक प्रगति का आधार है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(6)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "8": "<section class=\"chapter-section\" id=\"ch8\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">8</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>वाख</h2>\n      <p>ललद्यद | काव्य खंड (कश्मीरी शैली वाख) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">रस्सी कच्चे धागे की, खींच रही मैं नाव।\nजाने कब सुन मेरी पुकार, करें देव भवसागर पार।।\nपानी टपके कच्चे सकोरे, व्यर्थ प्रयास हो रहे मेरे।\nजी में उठती रह-रह हूक, घर जाने की चाह है घेरे।।\nखा-खाकर कुछ पाएगा नहीं, न खाकर बनेगा अहंकारी।\nसम खा तभी होगा समभावी, खुलेगी साँकल बंद द्वार की।।\nआई सीधी राह से, गई न सीधी राह।\nसुषुम-सेतु पर खड़ी थी, बीत गया दिन आह!\nजेब टटोली, कौड़ी न पाई। माँझी को दूँ, क्या उतराई?\nथल-थल में बसता है शिव ही, भेद न कर क्या हिंदू-मुसल्माँ।\nज्ञानी है तो स्वयं को जान, वही है साहिब से पहचान।।</div>\n    <div class=\"poet-name\">— कवयित्री ललद्यद (अनुवाद: मीरा कांत)</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch8-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">‘रस्सी’ यहाँ किसके लिए प्रयुक्त हुआ है और वह कैसी है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवयित्री ललद्यद ने 'रस्सी' शब्द का प्रयोग <strong>मनुष्य की नश्वर, क्षणभंगुर और दुर्बल श्वासों (जीवन जीने के साधनों)</strong> के लिए किया है।</p>\n<p>यह रस्सी <strong>'कच्चे धागे'</strong> की बनी है, अर्थात यह अत्यंत कमजोर, अस्थिर और नाशवान है। यह न जाने किस क्षण टूट जाए और जीवन समाप्त हो जाए, इसका कोई निश्चित भरोसा नहीं है। इसी कमजोर रस्सी के सहारे वह अपनी जीवन रूपी नाव को खींच रही हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रस्सी (श्वासों/जीवन-डोर) का लाक्षणिक अर्थ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कच्चे धागे की विशेषता (क्षणभंगुर, नश्वर, कमजोर) का उल्लेख</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch8-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवयित्री द्वारा मुक्ति के लिए किए जाने वाले प्रयास व्यर्थ क्यों हो रहे हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवयित्री अपने मुक्ति के प्रयासों की तुलना 'मिट्टी के कच्चे सकोरे' (कुल्हड़) से करती हैं, जिसमें से बूँद-बूँद पानी रिसकर बह जाता है और वह पानी को रोक नहीं पाता।</p>\n<p>उनके प्रयास निम्नलिखित कारणों से व्यर्थ हो रहे हैं:</p>\n<ul>\n  <li><strong>सांसारिक मोह-माया का बंधन:</strong> कवयित्री अभी भी पूरी तरह सांसारिक आकर्षणों, वासनाओं और नश्वर देह के बंधनों से मुक्त नहीं हो पाई हैं।</li>\n  <li><strong>ईश्वरीय कृपा का अभाव:</strong> उनकी साधना अभी पूर्ण परिपक्व नहीं हुई है, जिसके कारण प्रभु से साक्षात मिलन का क्षण नहीं आ पा रहा है और समय बीता जा रहा है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कच्चे सकोरे और रिसते पानी के रूपक का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सांसारिक मोह-बंधन एवं अपरिपक्व साधना का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch8-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कवयित्री का 'घर जाने की चाह' से क्या तात्पर्य है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'घर जाने की चाह' से कवयित्री का तात्पर्य इस भौतिक नश्वर संसार को छोड़कर <strong>परमात्मा के परम पावन धाम (परमपिता परमेश्वर की शरण)</strong> में जाने से है।</p>\n<p>आत्मा का वास्तविक और शाश्वत मूल घर परमात्मा ही है। सांसारिक देह में आत्मा एक परदेशी की भाँति भटक रही है। अतः कवयित्री भवसागर के बंधनों से मुक्त होकर अपने आराध्य शिव में विलीन हो जाने के लिए व्याकुल हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परमात्मा के लोक / मोक्ष प्राप्ति का अर्थ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्मा के मूल निवास और संसार से विरक्ति का स्पष्टीकरण</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch8-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए:<br>(क) 'जेब टटोली, कौड़ी न पाई।'<br>(ख) 'खा-खाकर कुछ पाएगा नहीं, न खाकर बनेगा अहंकारी।'</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम पंक्ति का भाव:</strong><br>\nकवयित्री ने जीवन भर हठयोग और सुषुम्ना नाड़ी की कठिन साधना में समय गँवा दिया। परंतु जब जीवन के अंतिम पड़ाव पर भवसागर पार कराने वाले माँझी (परमात्मा) को उतराई देने के लिए अपनी जेब (अंतःकरण) टटोली, तो उनके पास सत्कर्म, भक्ति, दया और परोपकार रूपी कोई पूँजी नहीं थी। सांसारिक साधना के बाद भी वे आत्मिक गुणों से शून्य रहीं।</p>\n\n<p><strong>(ख) द्वितीय पंक्ति का भाव:</strong><br>\nकवयित्री मध्यम मार्ग अपनाने की सीख देती हैं। यदि मनुष्य केवल सांसारिक भोग-विलास में डूबा रहेगा ('खा-खाकर'), तो उसे मुक्ति या ईश्वर नहीं मिलेंगे। और यदि वह सब कुछ त्यागकर हठपूर्वक तपस्या और उपवास करेगा ('न खाकर'), तो उसके मन में तपस्वी होने का मिथ्या अहंकार पैदा हो जाएगा। अतः मनुष्य को इंद्रियों का उचित संयम करते हुए समभावी (संतुलित) बनना चाहिए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): सत्कर्म रूपी पूँजी के अभाव और पछतावे की व्याख्या</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): अति-भोग और अति-त्याग का त्याग कर समभाव अपनाने का संदेश</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch8-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">बंद द्वार की साँकल खोलने के लिए ललद्यद ने क्या उपाय सुझाया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'बंद द्वार की साँकल' अज्ञानता, अहंकार और संकीर्णता के उस पर्दे का प्रतीक है जो जीवात्मा और परमात्मा के बीच की बाधा है। इसे खोलने के लिए ललद्यद ने निम्नलिखित उपाय सुझाया है:</p>\n<ul>\n  <li><strong>मध्यम मार्ग (समभाव):</strong> मनुष्य न तो पूर्णतः भोगी बने और न ही कठोर हठयोगी। वह अपनी अंतःकरण और बाह्य इंद्रियों पर संतुलित नियंत्रण रखे।</li>\n  <li><strong>समान दृष्टि:</strong> सभी प्राणियों के प्रति दया, समानता और निष्पक्षता का भाव रखे। जब मनुष्य के भीतर से अहंकार और भेदभाव मिट जाएगा, तभी चेतना व्यापक होगी और ईश्वर-मिलन के बंद द्वार की साँकल स्वतः खुल जाएगी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मध्यम मार्ग एवं इंद्रिय संयम का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अहंकार-मुक्ति एवं समभाव से चेतना के विस्तार का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक शब्दावली</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch8-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch8-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">ज्ञानी से कवयित्री का क्या अभिप्राय है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवयित्री ललद्यद के अनुसार 'ज्ञानी' वह नहीं है जिसने केवल धार्मिक पोथियाँ, वेद या शास्त्र रट लिए हों या जो धर्म के आधार पर हिंदू-मुसलमान में भेद करता हो।</p>\n<p>ज्ञानी वास्तव में वही है जो <strong>'आत्मज्ञानी'</strong> है—अर्थात जिसने अपने अंतःकरण को पहचान लिया है, अपनी आत्मा के स्वरूप को जान लिया है। जो स्वयं को पहचान लेता है, वही परमात्मा (साहिब) को भी जान लेता है, क्योंकि शिव प्रत्येक प्राणी के अंतःकरण में ज्योति रूप में विद्यमान हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुस्तकीय ज्ञान एवं धार्मिक भेद का खंडन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्मज्ञान (स्वयं की पहचान) को ही ईश्वर-पहचान मानने का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 8</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">ललद्यद के 'थल-थल में बसता है शिव ही' कथन में कौन-सा सार्वभौमिक जीवन-मूल्य छिपा है? आज के समाज में इसकी क्या आवश्यकता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कवयित्री ललद्यद के इस कथन में 'अद्वैतवाद' और 'सर्वधर्म समभाव' का अमर संदेश निहित है। 'शिव' किसी एक जाति या संप्रदाय के देवता नहीं, बल्कि इस चराचर जगत के कण-कण (थल-थल) में व्याप्त परम चेतना और कल्याणकारी शक्ति का नाम हैं।</p><p>जब परमात्मा प्रत्येक जीव में वास करते हैं, तो हिंदू और मुसलमान या जातिगत आधार पर भेदभाव करना ईश्वर का ही अपमान है। आज के समाज में जहाँ सांप्रदायिकता और नफरत बढ़ रही है, वहाँ ललद्यद का यह वाख मानवीय एकता, करुणा और परस्पर सम्मान का पाठ पढ़ाता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">हठयोग साधना और सहज जीवन के द्वंद्व को कवयित्री ने किस प्रकार सुलझाया है? विद्यार्थियों के जीवन में इसका क्या व्यावहारिक अनुप्रयोग है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कवयित्री ने अनुभव किया कि हठयोग (सुषुम्ना नाड़ी पर ध्यान केंद्रित करना, कठोर काया-क्लेश) केवल अहंकार को बढ़ाता है और अंत में व्यक्ति रिक्त-हस्त रह जाता है। अतः उन्होंने सहजता, आंतरिक पवित्रता और मध्यम मार्ग को श्रेष्ठ बताया।</p><p>विद्यार्थियों के लिए इसका सीधा अनुप्रयोग यह है कि वे अतिवाद (अत्यधिक तनाव या अत्यधिक लापरवाही) से बचें। जीवन में अध्ययन, स्वास्थ्य और नैतिक मूल्यों का संतुलित समन्वय ही वास्तविक सफलता और मानसिक शांति की कुंजी है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(7)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "9": "<section class=\"chapter-section\" id=\"ch9\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">9</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>सवैये</h2>\n      <p>रसखान | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">मानुष हौं तो वही रसखानि, बसौं ब्रज गोकुल गाँव के ग्वारन।\nजौ पसु हौं तो कहा बस मेरो, चरौं नित नंद की धेनु मंझारन।।\nपाहन हौं तो वही गिरि को, जो धर्यो कर छत्र पुरंदर धारन।\nजौ खग हौं तो बसेरो करौं, मिलि कालिंदी कूल कदंब की डारन।।\nया लकुटी अरु कामरिया पर, राज तिहूँ पुर को तजि डारौं।\nआठहुँ सिद्धि नवौ निधि को सुख, नंद की गाइ चराइ बिसारौं।।\nरसखान कबौं इन आँखिन सौं, ब्रज के बन बाग तड़ाग निहारौं।\nकोटिक एकलधौत के धाम, करील के कुंजन ऊपर वारौं।।\nमोरपखा सिर ऊपर राखिहौं, गुंज की माल गरे पहिरौंगी।\nओढ़ि पितंबर लै लकुटी, बन गोधन ग्वारनि संग फिरौंगी।।\nभावतो वोहि मेरो रसखानि, सो तेरे कहे सब स्वाँग करौंगी।\nया मुरली मुरलीधर की अधरान धरी अधरा न धरौंगी।।</div>\n    <div class=\"poet-name\">— रसखान (सवैये)</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch9-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">ब्रजभूमि के प्रति कवि का प्रेम किन-किन रूपों में अभिव्यक्त हुआ है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि रसखान का श्रीकृष्ण और उनकी लीलाभूमि ब्रज के प्रति अनन्य और अटूट प्रेम है। वे प्रत्येक जन्म में, चाहे वे किसी भी योनि में जन्म लें, केवल ब्रज में ही रहना चाहते हैं:</p>\n<ol>\n  <li><strong>मनुष्य रूप में:</strong> यदि वे मनुष्य बनें, तो गोकुल गाँव के ग्वालों के बीच बसना चाहते हैं ताकि वे कृष्ण की संगति का अनुभव कर सकें।</li>\n  <li><strong>पशु रूप में:</strong> यदि वे पशु बनें, तो नंदबाबा की गायों के बीच चरना चाहते हैं जिन्हें स्वयं कृष्ण चराया करते थे।</li>\n  <li><strong>पत्थर (पाहन) रूप में:</strong> यदि वे पत्थर बनें, तो उसी गोवर्धन पर्वत का अंग बनना चाहते हैं जिसे कृष्ण ने इंद्र के कोप से ब्रजवासियों की रक्षा के लिए अपनी कनिष्ठिका उँगली पर छत्र की तरह धारण किया था।</li>\n  <li><strong>पक्षी (खग) रूप में:</strong> यदि वे पक्षी बनें, तो यमुना (कालिंदी) के तट पर स्थित कदंब के पेड़ों की डालियों पर बसेरा करना चाहते हैं, जहाँ कृष्ण बाँसुरी बजाते थे।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मनुष्य रूप में गोकुल के ग्वाल-बाल बनने की इच्छा</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पशु रूप में नंद की गाय एवं पत्थर रूप में गोवर्धन पर्वत बनने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पक्षी रूप में यमुना तट के कदंब पर बसेरे का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch9-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवि का ब्रज के वन, बाग और सरोवर को निहारने के पीछे क्या कारण हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि रसखान की आँखें ब्रज के वनों, उपवनों और सरोवरों को निरंतर निहारते रहना चाहती हैं, क्योंकि ये स्थान केवल प्राकृतिक स्थल नहीं हैं, बल्कि ये <strong>श्रीकृष्ण की बाल-लीलाओं और मधुर स्मृतियों के प्रत्यक्ष साक्षी</strong> हैं।</p>\n<p>इन वनों में कृष्ण ने गायें चराई थीं, इन कुंजों में रासलीला रची थी और इन सरोवरों के तट पर अपनी बाँसुरी की तान छेड़ी थी। रसखान को लगता है कि इन स्थानों को देखने से उन्हें साक्षात श्रीकृष्ण के दिव्य सान्निध्य और अलौकिक प्रेम की अनुभूति होती है, जो तीनों लोकों के सुख से भी बढ़कर है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण की बाल-लीलाओं और मधुर स्मृतियों का साक्षी होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण के साक्षात सान्निध्य और आत्मिक आनंद की अनुभूति</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch9-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">एक लकुटी और कामरिया पर कवि सब कुछ न्योछावर करने को क्यों तैयार हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'लकुटी' (छोटी लाठी) और 'कामरिया' (काला कंबल) श्रीकृष्ण के ग्वाल-सखा रूप के अत्यंत प्रिय उपकरण हैं, जिन्हें ओढ़कर और लेकर वे ब्रज के वनों में गायें चराने जाते थे।</p>\n<p>कवि रसखान के लिए ये दोनों वस्तुएँ कोई सामान्य सांसारिक चीजें नहीं हैं, बल्कि इनमें उनके आराध्य प्रभु का साक्षात स्पर्श और प्रेम बसा हुआ है। अपने प्रभु के इस दिव्य स्पर्श और सान्निध्य के समक्ष संसार का समस्त ऐश्वर्य तुच्छ है। अतः वे कृष्ण की लाठी और कंबल के लिए तीनों लोकों का राज्य, आठों सिद्धियाँ, नौ निधियाँ और करोड़ों सोने के महल भी सहर्ष न्योछावर करने को तत्पर हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण के स्पर्श एवं ग्वाल रूप के प्रतीक का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">त्रैलोक्य के राज्य और अष्टसिद्धियों के त्याग का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch9-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">सखी ने गोपी से कृष्ण का कैसा रूप धारण करने का आग्रह किया था? अपने शब्दों में वर्णन कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>गोपियाँ श्रीकृष्ण के प्रेम में इतनी तन्मय थीं कि एक गोपी अपनी सखी के कहने पर कृष्ण का संपूर्ण रूप (स्वाँग) धारण करने को तैयार हो जाती है। सखी ने उससे निम्नलिखित रूप धारण करने का आग्रह किया:</p>\n<ul>\n  <li>सिर पर मोर के पंखों से बना मुकुट (मोरपखा) धारण करना,</li>\n  <li>गले में वन-फूलों और जंगली बीजों की गूँज-माला पहनना,</li>\n  <li>शरीर पर पीतांबर (पीले वस्त्र) ओढ़ना,</li>\n  <li>हाथ में लाठी (लकुटी) लेकर गायों और ग्वाल-बालों के साथ वन-वन घूमना।</li>\n</ul>\n<p>गोपी कृष्ण के इस रूप को धारण करने के लिए सहर्ष राजी हो जाती है क्योंकि इससे उसे कृष्ण के होने का आभास होता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोरपखा, गूँज की माला एवं पीतांबर धारण करने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हाथ में लाठी लेकर वन में ग्वालों संग घूमने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch9-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">आपके विचार से सखी ने गोपी से कृष्ण की मुरली को ओंठों पर न रखने का अनुरोध क्यों किया होगा?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>गोपी कृष्ण का सारा रूप धारण करने को तैयार है, परंतु मुरली को अपने ओंठों पर रखने से स्पष्ट इनकार कर देती है। इसके निम्नलिखित मुख्य कारण हैं:</p>\n<ul>\n  <li><strong>सौतिया डाह (ईर्ष्या का भाव):</strong> गोपियाँ मुरली को अपनी 'सौत' मानती थीं। कृष्ण रात-दिन उस मुरली को अपने ओंठों से लगाए रखते थे और मुरली के कारण ही वे गोपियों को भूल जाते थे।</li>\n  <li><strong>मुरली को जूठी न करने की श्रद्धा:</strong> मुरली पर केवल कृष्ण के अधरों (ओंठों) का अधिकार है। किसी अन्य के ओंठों पर रखकर वे उस दिव्य मुरली को अपवित्र या मर्यादाहीन नहीं करना चाहती थीं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मुरली के प्रति सौतिया डाह (ईर्ष्या) का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कृष्ण के अधरों की अनन्य मर्यादा का सम्मान</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch9-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch9-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">भाव और शिल्प सौंदर्य स्पष्ट कीजिए:<br><em>'या मुरली मुरलीधर की अधरान धरी अधरा न धरौंगी।'</em></div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>भाव-सौंदर्य:</strong> गोपी कहती है कि वह अपनी सखी के कहने पर कृष्ण का मोरमुकुट, पीतांबर और लाठी सब धारण कर लेगी, परंतु जिस मुरली को मुरलीधर कृष्ण ने हमेशा अपने ओंठों पर रखा, उसे वह अपने ओंठों पर कभी नहीं रखेगी। इसमें गोपियों का कृष्ण के प्रति अनन्य प्रेम तथा मुरली के प्रति गहरा ईर्ष्या-भाव (सौतिया डाह) अत्यंत सजीवता से अभिव्यक्त हुआ है।</p>\n<p><strong>शिल्प-सौंदर्य:</strong></p>\n<ul>\n  <li><strong>यमक अलंकार का चमत्कार:</strong> 'अधरान धरी' (ओंठों पर रखी हुई) और 'अधरा न' (ओंठों पर नहीं) में सुंदर यमक अलंकार है।</li>\n  <li><strong>अनुप्रास अलंकार:</strong> 'म' और 'ध' वर्ण की आवृत्ति से नाद-सौंदर्य उत्पन्न हुआ है।</li>\n  <li><strong>भाषा व छंद:</strong> माधुर्य गुण से युक्त सरस 'ब्रजभाषा' तथा गेय 'सवैया छंद' का अत्यंत मनोरम प्रयोग है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाव-सौंदर्य (गोपी का प्रेम और मुरली के प्रति ईर्ष्या) की स्पष्टता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिल्प-सौंदर्य (यमक एवं अनुप्रास अलंकार, ब्रजभाषा, सवैया छंद)</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">व्याकरणिक शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 9</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">मुस्लिम कवि होते हुए भी रसखान का श्रीकृष्ण के प्रति यह अनन्य समर्पण भारतीय साझी संस्कृति (गंगा-जमुनी तहजीब) का क्या अनुपम उदाहरण प्रस्तुत करता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कवि रसखान (मूल नाम: सैयद इब्राहिम) का जीवन और साहित्य इस बात का सबसे उज्ज्वल प्रमाण है कि ईश्वर-प्रेम और भक्ति की कोई संकीर्ण मजहबी सीमा नहीं होती। उन्होंने जाति, धर्म और संप्रदाय की समस्त सीमाओं को लाँघकर श्रीकृष्ण की भक्ति में अपना सर्वस्व समर्पित कर दिया।</p><p>उनका यह समर्पण भारतीय संस्कृति की उदारता, समन्वय और सर्वसमावेशी आत्मा को दर्शाता है। आज जब समाज को धर्म के नाम पर बाँटने की चेष्टा की जाती है, तब रसखान के सवैये हमें यह याद दिलाते हैं कि प्रेम और कला किसी मजहब की मोहताज नहीं होतीं, वे केवल हृदय की पवित्रता की माँग करती हैं।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">रसखान के सवैयों में प्रकृति (गोवर्धन पर्वत, यमुना तट, कदंब के पेड़, करील के कुंज) के प्रति जो अगाध अनुराग है, वह आधुनिक पर्यावरण संचेतना से कैसे जुड़ता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>रसखान केवल अमूर्त ईश्वर से प्रेम नहीं करते, बल्कि वे कृष्ण से जुड़े हर प्राकृतिक तत्व—पेड़, नदी, पर्वत, गाय और झाड़ियों से गहरा भावनात्मक रिश्ता जोड़ते हैं। वे करील के काँटेदार कुंजों के लिए भी सोने के महलों को त्यागने को तैयार हैं।</p><p>यह दृष्टिकोण सिखाता है कि प्रकृति केवल उपभोग की वस्तु नहीं है, बल्कि वह परमात्मा की सजीव अभिव्यक्ति है। यदि हम अपने आस-पास की नदियों, पहाड़ों और वृक्षों के प्रति ऐसा ही पावन अनुराग रखें, तो पर्यावरण प्रदूषण और विनाश की समस्या का सहज ही समाधान हो सकता है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(8)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "10": "<section class=\"chapter-section\" id=\"ch10\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">10</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>कैदी और कोकिला</h2>\n      <p>माखनलाल चतुर्वेदी | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">क्या गाती हो? क्यों रह-रह जाती हो?\nकोकिल बोलो तो! क्या लाती हो? संदेशा किसका है?\nकोकिल बोलो तो!\nऊँची काली दीवारों के घेरे में,\nडाकू, चोरों, बटमारों के डेरे में,\nजीने को देते नहीं पेट भर खाना,\nमरने भी देते नहीं, तड़प रह जाना!\nजीवन पर अब दिन-रात कड़ा पहरा है,\nशासन है या तम का प्रभाव गहरा है?\nहिमकर निराश कर चला रात भी काली,\nइस समय कालिमा-मयी जगी क्यों आली?\nक्यों हूक पड़ी? वेदना बोझ वाली सी?\nकोकिल बोलो तो! क्या लूटा?\nमृदुल वैभव की रखवाली सी, कोकिल बोलो तो!\nक्या हुई बावली? अर्धरात्रि को चीखी,\nकोकिल बोलो तो! किस दावानल की ज्वालाएँ हैं दीखीं?\nकोकिल बोलो तो!</div>\n    <div class=\"poet-name\">— माखनलाल चतुर्वेदी</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch10-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कोयल की कूक सुनकर कवि की क्या प्रतिक्रिया थी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>आधी रात के सन्नाटे और अंधकार में जेल की काल-कोठरी के ऊपर जब कोयल कूकती है, तो कवि माखनलाल चतुर्वेदी अत्यंत विस्मित, व्यथित और उद्वेलित हो उठते हैं।</p>\n<p>कवि कोयल से प्रश्न करते हैं कि तू इस असमय क्यों गा रही है? क्या तू स्वाधीनता सेनानियों के लिए किसी क्रांति का गुप्त संदेशा लाई है? अथवा पराधीन भारत रूपी जंगल में लगी किसी दावानल (विद्रोह की आग) की लपटें देखकर तू बावली हो गई है? कवि को कोयल की कूक में उल्लास नहीं, बल्कि असह्य वेदना और विद्रोह की गहरी चीख सुनाई देती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आधी रात में कूकने पर विस्मय व उद्वेलन का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रांति के संदेशे अथवा दावानल के अंदेशे का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch10-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवि ने कोकिल के बोलने के किन कारणों की संभावना बताई?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि ने आधी रात में कोयल के बोलने के पीछे निम्नलिखित महत्वपूर्ण संभावनाएँ व्यक्त की हैं:</p>\n<ol>\n  <li>कोयल देशभक्त कैदियों के लिए कोई महत्वपूर्ण गुप्त संदेश या प्रेरणा लेकर आई है।</li>\n  <li>उसने देश में भड़कने वाली स्वतंत्रता संग्राम की क्रांति रूपी 'दावानल' (जंगल की भीषण आग) की ज्वालाएँ देख ली हैं।</li>\n  <li>वह जेलों में बंद स्वाधीनता सेनानियों पर हो रहे अमानवीय अंग्रेजी अत्याचारों को देखकर गहरे दुःख और आक्रोश से चीख पड़ी है।</li>\n  <li>वह कैदियों के भीतर ब्रिटिश दमन के विरुद्ध संघर्ष और विद्रोह का बीजारोपण करने आई है।</li>\n  <li>अथवा उसकी वेदना का बोझ इतना अधिक बढ़ गया है कि वह उसे अपने भीतर दबा नहीं सकी और बावली होकर आधी रात में ही कूक पड़ी।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गुप्त संदेश और दावानल की ज्वालाएँ देखने की संभावना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अंग्रेजी अत्याचारों पर आक्रोश और विद्रोह के बीज बोने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">वेदना के असहनीय बोझ का वर्णन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रमबद्ध एवं शुद्ध भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch10-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">किस शासन की तुलना तम (अंधकार) के प्रभाव से की गई है और क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि ने <strong>अंग्रेजी (ब्रिटिश) औपनिवेशिक शासन</strong> की तुलना 'तम' (काले अंधकार) के प्रभाव से की है।</p>\n<p><strong>कारण:</strong></p>\n<ul>\n  <li>जिस प्रकार घना अंधकार प्रकाश, सत्य और न्याय को पूरी तरह ढक लेता है, उसी प्रकार अंग्रेजी शासन अन्याय, दमन, क्रूरता और शोषण पर आधारित था।</li>\n  <li>अंग्रेज निष्पाप भारतीय देशभक्तों को चोर-डाकुओं की तरह काल-कोठरी में बंद कर अमानवीय यातनाएँ देते थे। उनका पूरा तंत्र विवेकहीन, संवेदनहीन और काला (अन्यायपूर्ण) था, इसलिए कवि ने इसे 'तम का गहरा प्रभाव' कहा है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ब्रिटिश शासन का स्पष्ट उल्लेख</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अंधकार (अन्याय, दमन, क्रूरता) से तुलना का तार्किक कारण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch10-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कविता के आधार पर पराधीन भारत की जेलों में दी जाने वाली यंत्रणाओं (यातनाओं) का वर्णन कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'कैदी और कोकिला' कविता में ब्रिटिश काल की जेलों में स्वतंत्रता सेनानियों को दी जाने वाली अत्यंत क्रूर और बर्बर यातनाओं का सजीव चित्रण हुआ है:</p>\n<ul>\n  <li><strong>अपराधियों के साथ रखना:</strong> देशभक्तों को सामान्य राजनीतिक कैदी न मानकर डाकुओं, चोरों और बटमारों (रास्ते के लुटेरों) के साथ दस फुट की तंग और सीलन भरी काल-कोठरियों में बंद रखा जाता था।</li>\n  <li><strong>हाथ-पैरों में भारी बेड़ियाँ:</strong> कैदियों को भारी लोहे की हथकड़ियों और बेड़ियों में जकड़कर रखा जाता था।</li>\n  <li><strong>पशुओं जैसा कठोर श्रम:</strong> कैदियों के पेट पर भारी चमड़े का जूआ बाँधकर कुएँ से पानी खींचने (कोल्हू चलाने) और पत्थर तुड़वाने (गिट्टियाँ फोड़ने) का काम लिया जाता था।</li>\n  <li><strong>भूख-प्यास से तड़पाना:</strong> उन्हें न तो पेट भर भोजन दिया जाता था और न ही चैन से मरने दिया जाता था। दिन-रात गालियाँ और पहरेदारों की प्रताड़ना सहनी पड़ती थी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">काल-कोठरी और लुटेरों संग रखने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पेट पर जूआ बाँधकर कोल्हू चलवाने और पत्थर तुड़वाने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हथकड़ियों, भूख-प्यास और गालियों की यंत्रणा का विवरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रभावशाली भाषा-प्रवाह</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch10-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए:<br>(क) 'मृदुल वैभव की रखवाली सी, कोकिल बोलो तो!'<br>(ख) 'हूँ मोट खींचता लगा पेट पर जूआ, खाली करता हूँ ब्रिटिश अकड़ का कुँआ।'</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम पंक्ति का भाव:</strong><br>\nईश्वर ने कोयल को अत्यंत मधुर, कोमल और कर्णप्रिय कंठ प्रदान किया है। वह संसार में मिठास, आनंद और कोमलता (मृदुल वैभव) की स्वाभाविक संरक्षिका मानी जाती है। कवि आश्चर्य से पूछता है कि जब तेरा स्वभाव इतना कोमल और मधुर है, तो तू इस आधी रात में काल-कोठरी के ऊपर करुण चीख क्यों मार रही है? तेरे इस मधुर वैभव को किसने लूट लिया है?</p>\n\n<p><strong>(ख) द्वितीय पंक्ति का भाव:</strong><br>\nकवि अपने पेट पर चमड़े का जूआ बाँधकर कोल्हू से पानी का 'मोट' (चमड़े का बड़ा पात्र) खींचते हैं। कवि इसे अपनी विवशता नहीं, बल्कि स्वाभिमान का कार्य मानते हैं। वे कहते हैं कि मैं जेल में केवल पानी नहीं खींच रहा हूँ, बल्कि अपने अदम्य साहस और दृढ़ता से ब्रिटिश हुकूमत के घमंड और क्रूरता रूपी कुएँ को खाली कर रहा हूँ। अंग्रेज मुझे झुकाना चाहते हैं, पर मैं अपने श्रम से उनके अहंकार को तोड़ रहा हूँ।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): कोयल के मधुर कंठ व करुण चीख के विरोधाभास की व्याख्या</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): मोट खींचने के आत्मगौरव और ब्रिटिश अकड़ तोड़ने के प्रतीकार्थ का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch10-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">कवि को कोयल से ईर्ष्या क्यों हो रही है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि और कोयल की परिस्थितियों में जमीन-आसमान का अंतर है। कवि को कोयल से निम्नलिखित कारणों से स्वाभाविक ईर्ष्या (स्पर्धा) होती है:</p>\n<ul>\n  <li><strong>रहने का स्थान:</strong> कोयल हरी-भरी डालियों पर स्वतंत्र विचरण करती है, जबकि कवि एक काली, संकरी और अँधेरी दस फुट की काल-कोठरी में बंद हैं।</li>\n  <li><strong>उड़ान का दायरा:</strong> कोयल के लिए पूरा खुला आकाश (विस्तृत नभ) उपलब्ध है, जबकि कवि का संसार केवल दस फुट के कमरे तक सीमित है।</li>\n  <li><strong>गीत और अभिव्यक्ति:</strong> कोयल जब कूकती है तो लोग प्रशंसा में 'वाह-वाह' करते हैं, जबकि कवि के लिए जेल में रोना या आह भरना भी कानूनन जुर्म माना जाता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्वतंत्रता बनाम पराधीनता का तुलनात्मक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हरी डाली बनाम काल-कोठरी और गीत बनाम रोने के अधिकार का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch10-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch10-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">‘हथकड़ियों को गहना क्यों कहा गया है?’</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि माखनलाल चतुर्वेदी ने लोहे की हथकड़ियों को बंधन या लज्जा की वस्तु न मानकर <strong>'ब्रिटिश राज का गहना' (आभूषण)</strong> कहा है, क्योंकि:</p>\n<ul>\n  <li>वे किसी चोरी या अपराध के कारण जेल नहीं गए थे, बल्कि भारत माता को स्वतंत्र कराने के पुनीत राष्ट्रीय कर्तव्य के कारण बंदी बने थे।</li>\n  <li>स्वाधीनता सेनानियों के लिए मातृभूमि की बेड़ियों को काटने के प्रयास में पहनी गई हथकड़ियाँ किसी आभूषण की तरह गौरव, त्याग और स्वाभिमान का प्रतीक थीं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अपराध न होकर देश-सेवा का गौरव होना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हथकड़ियों को त्याग, स्वाभिमान व आभूषण मानने का स्पष्टीकरण</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 10</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">'कैदी और कोकिला' कविता आज की युवा पीढ़ी में देशप्रेम और राष्ट्रीय चेतना के किन शाश्वत मूल्यों को जाग्रत करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>माखनलाल चतुर्वेदी की यह ओजस्वी कविता यह सिखाती है कि स्वतंत्रता सहज ही नहीं मिलती; उसके लिए हमारे पूर्वजों ने जेलों में कोल्हू के बैल बनकर अमानवीय यातनाएँ सही हैं। कवि ने हथकड़ियों को गहना और कष्टों को गौरव मानकर हँसते-हँसते सहा।</p><p>आज की युवा पीढ़ी को इस बलिदान का मूल्य समझना चाहिए। देश की आजादी और संप्रभुता की रक्षा करना, राष्ट्र के विकास में योगदान देना तथा अन्याय के विरुद्ध निर्भीक होकर खड़े होना ही इस कविता का शाश्वत संदेश है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">कविता में प्रयुक्त 'काली' शब्द की आवृत्ति किस प्रकार तत्कालीन औपनिवेशिक वातावरण के भयावह यथार्थ को साकार करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कविता में 'काली' शब्द का प्रयोग अनेक संदर्भों में हुआ है—काली तू, रजनी भी काली, शासन की करनी भी काली, काली लहर कल्पना काली, काल-कोठरी काली, टोपी काली, कमली काली और लौह-श्रृंखला काली।</p><p>यह आवृत्ति केवल रंग का बोध नहीं कराती, बल्कि यह तत्कालीन पराधीन भारत के घोर निराशा, क्रूरता, अमानवीय अत्याचार, अन्यायपूर्ण विदेशी नीतियों और स्वतंत्रता सेनानियों के दमघोंटू वातावरण का एक अत्यंत सशक्त मनोवैज्ञानिक और प्रतीकात्मक चित्र प्रस्तुत करती है। यह कविता के प्रभाव को कई गुना बढ़ा देती है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(9)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "11": "<section class=\"chapter-section\" id=\"ch11\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">11</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>ग्राम श्री</h2>\n      <p>सुमित्रानंदन पंत | काव्य खंड (प्रकृति सौंदर्य) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">फैली खेतों में दूर तलक, मखमल की कोमल हरियाली,\nलिपटीं जिससे रवि की किरणें, चाँदी की सी उजली जाली!\nतिनकों के हरे-हरे तन पर, हिल हरित रुधिर है रहा झलक,\nश्यामल भू-तल पर झुका हुआ, नभ का चिर निर्मल नील फलक!\nरोमांचित-सी लगती वसुधा, आई जौ गेहूँ में बाली,\nअरहर सनई की सोने की, किंकणियाँ हैं शोभाशाली!\nउड़ती भीनी मल्लाक्त गंध, पीली-पीली सरसों फूली,\nलो, हरित धरा से झाँक रही, नीलम की कलि तीसी नीली!\nरंग-रंग के फूलों में रिलमिल, हँस रही सखियाँ मटर खड़ी,\nमखमली पेटियों-सी लटकीं, छीमियाँ, छिपाए बीज लड़ी!</div>\n    <div class=\"poet-name\">— सुमित्रानंदन पंत</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch11-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कवि ने गाँव को 'हरता जन मन' क्यों कहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'हरता जन मन' का अर्थ है—समस्त लोगों के मन को अपनी सुंदरता से सम्मोहित और आकर्षित कर लेना। कवि ने गाँव को ऐसा इसलिए कहा है क्योंकि:</p>\n<ul>\n  <li>गाँव के खेतों में दूर-दूर तक मखमली हरी-भरी फसलें लहलहा रही हैं, जिन पर सुनहरी धूप चाँदी की जाली जैसी चमकती है।</li>\n  <li>गेहूँ और जौ में बालियाँ आ चुकी हैं, सरसों के पीले-पीले फूलों से धरती स्वर्णमयी लग रही है, और आम, अमरूद, बेर व तरबूजों की बहुलता प्रकृति को अलौकिक सौंदर्य प्रदान कर रही है। गाँव का यह अनुपम और शांत प्राकृतिक वैभव प्रत्येक मनुष्य के मन को शांति और आनंद से भर देता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'हरता जन मन' का अर्थ और प्राकृतिक सम्मोहन का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लहलहाती फसलों, सरसों और फलों के सौंदर्य का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch11-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कविता में किस मौसम के सौंदर्य का वर्णन है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कविता में <strong>शिशिर और वसंत ऋतु (शीत ऋतु के अंतिम चरण और वसंत के आगमन काल)</strong> के मनोहारी प्राकृतिक सौंदर्य का वर्णन है।</p>\n<p>इस समय खेतों में गेहूँ और जौ की बालियाँ निकल आती हैं, सरसों में पीले फूल खिलते हैं, पेड़ों से पतझड़ के बाद नई कोंपलें फूटती हैं, आम के बौर महकने लगते हैं और धूप हल्की गुनगुनी व सुखद हो जाती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिशिर/वसंत ऋतु के संधिकाल का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फसलों व मौसम के लक्षणों (सरसों, गेहूँ, गुनगुनी धूप) का स्पष्टीकरण</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch11-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">गाँव को 'मरकत डिब्बे सा खुला' क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'मरकत' (पन्ना) एक अत्यंत मूल्यवान, पारदर्शी और गहरे हरे रंग का रत्न होता है। कवि ने गाँव को 'मरकत डिब्बे सा खुला' इसलिए कहा है क्योंकि:</p>\n<ul>\n  <li>गाँव के खेतों में चारों ओर फैली मखमली हरियाली मरकत (पन्ने) के समान चमकीली और हरी-भरी है।</li>\n  <li>इस हरी-भरी धरती के ऊपर नीला, स्वच्छ और शांत आकाश ढक्कन की तरह फैला हुआ है। जैसे पन्नों से भरा कोई रत्नजड़ित डिब्बा खुला छोड़ दिया गया हो, वैसे ही गाँव की हरीतिमा पर विभिन्न रंगों के फूल, फसलें और धूप चमक रही हैं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मरकत (पन्ना रत्न) और हरियाली की उपमा का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खुले नीले आकाश रूपी ढक्कन और रत्न-सदृश सौंदर्य का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा-शैली व वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch11-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">अरहर और सनई के खेत कवि को कैसे दिखाई देते हैं?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि सुमित्रानंदन पंत को अरहर और सनई के पके हुए खेत ऐसे प्रतीत होते हैं मानो <strong>धरती रूपी सुंदरी ने अपनी कमर पर सोने की करधनी (किंकिणी)</strong> पहन रखी हो।</p>\n<p>जब हवा चलती है, तो अरहर और सनई की सूखी फलियों के अंदर के बीज परस्पर टकराकर मधुर, रुनझुन और छन-छन करती हुई आवाज पैदा करते हैं, जो करधनी में लगे घुँघरुओं की झंकार जैसी अत्यंत मनमोहक लगती है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धरती की सोने की करधनी (किंकिणी) का रूपक</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बीजों के बजने से घुँघरू जैसी मधुर ध्वनि का वर्णन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch11-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए:<br>(क) 'बालू के साँपों से अंकित / गंगा की सतरंगी रेती'<br>(ख) 'हँसमुख हरियाली हिम आतप / सुख से अलसाए-से सोए'</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम पंक्ति का भाव:</strong><br>\nगंगा नदी के किनारे फैली हुई रेत पर जब सूर्य की किरणें पड़ती हैं, तो वह अनेक रंगों (सतरंगी) में चमक उठती है। नदी की लहरों और हवा के बहाव के कारण रेत पर टेढ़े-मेढ़े लहरियादार निशान बन गए हैं, जो देखने में ऐसे लगते हैं मानो बहुत से रंग-बिरंगे साँप रेत पर रेंगकर चले गए हों। इसमें प्रकृति का अत्यंत सूक्ष्म चित्रात्मक सौंदर्य उभरा है।</p>\n\n<p><strong>(ख) द्वितीय पंक्ति का भाव:</strong><br>\nसर्दियों की गुनगुनी, मीठी धूप (हिम आतप) खेतों में फैली लहलहाती हरी फसलों पर चमक रही है। ऐसा प्रतीत होता है मानो हरियाली खिली हुई धूप का आनंद लेकर मंद-मंद मुसकरा रही है और ठंड के प्रभाव से दोनों (हरियाली और धूप) आलस्य और असीम सुख में डूबकर एक साथ सो रहे हों। इसमें मानवीकरण अलंकार का अद्भुत सौंदर्य है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): सतरंगी रेती और बालू के साँपों के चित्रात्मक सौंदर्य की व्याख्या</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): हरियाली व शीतकालीन धूप के मानवीकरण और आलस्य के भाव का उद्घाटन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रवाहपूर्ण भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch11-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch11-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">खेतों में फैली हरियाली और फूलों का चित्रण कवि ने किन सुंदर उपमानों से किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>प्रकृति के सुकुमार कवि सुमित्रानंदन पंत ने अद्भुत उपमानों का प्रयोग किया है:</p>\n<ul>\n  <li><strong>हरियाली के लिए:</strong> खेतों की कोमल घास को 'मखमल' की उपमा दी है और धूप की किरणों को 'चाँदी की उजली जाली' कहा है।</li>\n  <li><strong>मटर और फलियों के लिए:</strong> मटर की फलियों को 'मखमली पेटियाँ' कहा है जिनमें बीजों की लड़ियाँ छिपी हैं, तथा मटर के पौधों को सखियों की तरह सज-धज कर मुसकराते हुए दिखाया है।</li>\n  <li><strong>तीसी के फूल:</strong> नीले रंग की तीसी को हरी धरती से झाँकती हुई 'नीलम की कली' कहा है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मखमल व चाँदी की जाली के उपमान का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मखमली पेटियों (मटर) और नीलम की कली (तीसी) के उपमानों का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 11</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'ग्राम श्री' कविता में प्रकृति का जो चित्रात्मक वर्णन है, वह पाठक की इंद्रियों (दृश्य, स्पर्श, गंध, श्रव्य) को कैसे जाग्रत करता है? सोदाहरण समझाइए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>पंत जी की कविता बिंब-विधान का उत्कृष्ट उदाहरण है:</p><ul><li><strong>दृश्य बिंब:</strong> 'मरकत डिब्बे सा खुला गाँव', 'चाँदी की सी उजली जाली'।</li><li><strong>स्पर्श बिंब:</strong> 'मखमल की कोमल हरियाली', 'सुख से अलसाए-से सोए'।</li><li><strong>घ्राण (गंध) बिंब:</strong> 'उड़ती भीनी मल्लाक्त गंध' (सरसों की सोंधी महक)।</li><li><strong>श्रव्य (ध्वनि) बिंब:</strong> अरहर-सनई की किंकिणियों (करधनी) की रुनझुन आवाज।</li></ul><p>यह बहु-इंद्रिय संवेदी चित्रण पाठक को ऐसा अनुभव कराता है मानो वह स्वयं गाँव के खेतों के बीच खड़ा होकर उस पावन प्रकृति को जी रहा हो।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">आधुनिक कंक्रीट के शहरों में रहने वाले लोगों के लिए 'ग्राम श्री' का ग्रामीण जीवन क्या संदेश देता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज का शहरी मनुष्य धूल, धुआँ, कृत्रिमता और मानसिक अवसाद से घिरा हुआ है। वह प्रकृति के सहज सौंदर्य और ताजगी से पूरी तरह कट चुका है।</p><p>'ग्राम श्री' कविता याद दिलाती है कि वास्तविक आनंद, मानसिक शांति और स्वास्थ्य प्रकृति की गोद में ही संभव है। यह कविता हमें कृषि-संस्कृति का आदर करने, पेड़-पौधों के संरक्षण तथा कंक्रीट के जंगलों के बीच भी प्राकृतिक हरियाली को बचाने की प्रेरणा देती है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(10)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "12": "<section class=\"chapter-section\" id=\"ch12\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">12</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>मेघ आए</h2>\n      <p>सर्वेश्वर दयाल सक्सेना | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">मेघ आए बड़े बन-ठन के सँवर के।\nआगे-आगे नाचती-गाती बयार चली,\nदरवाजे-खिड़कियाँ खुलने लगीं गली-गली,\nपाहुन ज्यों आए हों गाँव में शहर के,\nमेघ आए बड़े बन-ठन के सँवर के।\nपेड़ झुक झाँकने लगे गरदन उचकाए,\nधूल भागी घाघरा उठाए,\nबाँकी चितवन उठा, नदी ठिठकी, घूँघट सरके,\nमेघ आए बड़े बन-ठन के सँवर के।\nबूढ़े पीपल ने आगे बढ़कर जुहार की,\n‘बरस बाद सुधि लीन्हीं’—\nबोली अकुलाई लता ओट हो किवार की,\nहरषाया ताल लाया पानी परात भर के,\nमेघ आए बड़े बन-ठन के सँवर के।\nक्षितिज अटारी पर दामिनी दमकी,\n‘क्षमा करो गाँठ खुल गई अब भरम की,’\nबाँध टूटा झर-झर मिलन के अश्रु ढरके,\nमेघ आए बड़े बन-ठन के सँवर के।</div>\n    <div class=\"poet-name\">— सर्वेश्वर दयाल सक्सेना</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch12-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">बादलों के आने पर प्रकृति में जिन गतिशील क्रियाओं को कवि ने चित्रित किया है, उन्हें लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि सर्वेश्वर दयाल सक्सेना ने मेघों के आगमन पर प्रकृति में होने वाली निम्नलिखित जीवंत एवं गतिशील क्रियाओं का मानवीकरण किया है:</p>\n<ol>\n  <li><strong>तेज हवा (बयार) का चलना:</strong> बादलों के आगे-आगे तेज हवा नाचती-गाती हुई संदेशवाहक की तरह चलने लगी, जिससे गली-गली में घरों के दरवाजे और खिड़कियाँ खुलने लगीं।</li>\n  <li><strong>पेड़ों का झुकना:</strong> तेज आंधी में पेड़ गरदन उचका-उचकाकर झुकने लगे मानो वे मेहमान को देखने की उत्सुकता में झाँक रहे हों।</li>\n  <li><strong>धूल का भागना:</strong> बवंडर उठने पर धूल अपना घाघरा समेटकर चंचल बालिका की तरह तेजी से भागने लगी।</li>\n  <li><strong>नदी का ठिठकना:</strong> नदी की गति कुछ क्षणों के लिए मंद पड़ गई मानो कोई नई नवेली वधू घूँघट सरकाकर तिरछी नजरों (बाँकी चितवन) से दामाद को देख रही हो।</li>\n  <li><strong>पीपल द्वारा स्वागत:</strong> पुराने विशाल पीपल के वृक्ष ने झुककर आगे बढ़कर वृद्ध मुखिया की तरह मेहमान का आदरपूर्वक अभिवादन (जुहार) किया।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हवा के नाचने और खिड़कियाँ खुलने का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पेड़ों के उचकने और धूल के घाघरा उठाकर भागने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नदी के ठिठकने और पीपल द्वारा जुहार करने की क्रियाएँ</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch12-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">निम्नलिखित किसके प्रतीक हैं: धूल, पेड़, नदी, लता, ताल?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कविता में ग्रामीण परिवेश के संदर्भ में इन प्राकृतिक उपादानों को निम्नलिखित मानवीय प्रतीकों के रूप में प्रस्तुत किया गया है:</p>\n<ul>\n  <li><strong>धूल:</strong> गाँव की चंचल, नटखट और अल्हड़ बालिका का प्रतीक है जो मेहमान के आने की सूचना देने घाघरा उठाकर दौड़ती है।</li>\n  <li><strong>पेड़:</strong> गाँव के उन उत्सुक ग्रामीणों और पुरुषों के प्रतीक हैं जो नए दामाद को देखने के लिए गरदन उचका रहे हैं।</li>\n  <li><strong>नदी:</strong> गाँव की नवविवाहिता अथवा बहू का प्रतीक है जो मर्यादावश घूँघट सरकाकर तिरछी दृष्टि से मेहमान को देखती है।</li>\n  <li><strong>लता:</strong> विरहिणी प्रेमिका अथवा नववधू की प्रतीक है जो दरवाजे की ओट में छिपकर अपने प्रियतम के देर से आने पर उलाहना देती है।</li>\n  <li><strong>ताल (तालाब):</strong> घर के उस सेवक या आत्मीय सदस्य का प्रतीक है जो आदरपूर्वक परात में पानी भरकर दामाद के पैर धोने के लिए लाता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धूल, पेड़ एवं नदी के प्रतीकार्थ का सही निरूपण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लता (विरहिणी वधू) एवं ताल (सेवक/पैर धोने वाले) के प्रतीक का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुद्ध शब्दावली</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch12-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लता ने बादल रूपी मेहमान को किस तरह देखा और क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>लता ने बादल रूपी मेहमान को <strong>'किवार (दरवाजे) की ओट में छिपकर व्याकुल (अकुलाई) होकर'</strong> देखा।</p>\n<p><strong>कारण:</strong></p>\n<ul>\n  <li><strong>सामाजिक लज्जा व मर्यादा:</strong> भारतीय ग्रामीण संस्कृति में विवाहिता या प्रेमिका अपने पति/प्रियतम के सामने सबके समक्ष खुलकर नहीं आती, वह संकोचवश दरवाजे की ओट में खड़ी रहती है।</li>\n  <li><strong>मान और उलाहना:</strong> बादल पूरे एक वर्ष बाद आए थे। लता लंबे वियोग के कारण मन ही मन रूठी हुई थी, इसलिए उसने ओट में छिपकर उलाहना दिया—<em>'बरस बाद सुधि लीन्हीं'</em> (अर्थात आपने पूरे एक साल बाद मेरी खबर ली है)।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दरवाजे की ओट से व्याकुल होकर देखने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भारतीय मर्यादा एवं एक वर्ष के वियोग के उलाहने का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch12-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">भाव स्पष्ट कीजिए:<br>(क) 'क्षमा करो गाँठ खुल गई अब भरम की'<br>(ख) 'बाँकी चितवन उठा, नदी ठिठकी, घूँघट सरके।'</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p><strong>(क) प्रथम पंक्ति का भाव:</strong><br>\nलता रूपी नववधू के मन में यह भ्रम (संदेह) था कि उसका प्रियतम (मेघ) अब कभी लौटकर नहीं आएगा और वह उसे भूल चुका है। परंतु जब आकाश रूपी अटारी पर बिजली चमकी और बादलों का आगमन हुआ, तो लता का यह संशय हमेशा के लिए दूर हो गया। उसने अपने प्रियतम से मन ही मन क्षमा माँगी कि मैंने आप पर व्यर्थ अविश्वास किया। इसके बाद मिलन के प्रेमाश्रु (मूसलाधार वर्षा) बरसने लगे।</p>\n\n<p><strong>(ख) द्वितीय पंक्ति का भाव:</strong><br>\nमेघ रूपी सुंदर दामाद के गाँव में आने पर नदी रूपी ग्रामीण युवती की चाल कुछ पल के लिए ठिठक (रुक) गई। उसने लज्जावश अपना घूँघट थोड़ा-सा सरकाया और तिरछी नजरों (बाँकी चितवन) से उस सजे-सँवरे दामाद को देखने लगी। इसमें ग्रामीण वधुओं की सहज लज्जा, संकोच और उत्सुकता का अत्यंत सजीव मानवीकरण हुआ है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (क): भ्रम टूटने, क्षमा-याचना और मिलन के अश्रु की व्याख्या</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग (ख): नदी के मानवीकरण, तिरछी चितवन और घूँघट सरकाने का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं अभिव्यक्ति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch12-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">मेघ रूपी मेहमान के आने से गाँव के वातावरण में क्या-क्या परिवर्तन हुए?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>मेघ रूपी शहरी दामाद के बन-ठन कर आने से पूरे गाँव में उल्लास, हलचल और उमंग का वातावरण छा गया:</p>\n<ul>\n  <li>नाचती हुई शीतल बयार बहने लगी और लोग घरों की खिड़कियाँ-दरवाजे खोलकर बाहर देखने लगे।</li>\n  <li>धूल चंचल बालिका की तरह दौड़ पड़ी और पेड़ गरदन उचकाकर देखने लगे।</li>\n  <li>सूख रहा तालाब जल से लबालब भर गया और बूढ़े पीपल ने आगे बढ़कर उनका सत्कार किया।</li>\n  <li>आकाश में बिजली कड़क उठी और मूसलाधार बारिश होने से चारों ओर हरियाली और शीतलता फैल गई। लंबे समय से चल रहा विरह और सूखा समाप्त हो गया।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उल्लास और हलचल के वातावरण का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हवा, धूल, पेड़, तालाब और वर्षा के परिवर्तनों का क्रमबद्ध वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch12-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch12-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">कविता में प्रयुक्त 'मानवीकरण अलंकार' के दो सुंदर उदाहरण स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कविता 'मेघ आए' पूरी तरह मानवीकरण अलंकार (Personification) पर आधारित है। इसके दो प्रमुख उदाहरण निम्नलिखित हैं:</p>\n<ol>\n  <li><strong>'मेघ आए बड़े बन-ठन के सँवर के':</strong> यहाँ निर्जीव बादलों को शहर से आए सजे-धजे, सँवरे हुए दामाद के मानवीय रूप में प्रस्तुत किया गया है।</li>\n  <li><strong>'बूढ़े पीपल ने आगे बढ़कर जुहार की':</strong> यहाँ सदियों पुराने विशाल पीपल के वृक्ष को गाँव के वृद्ध मुखिया के रूप में मेहमान का हाथ जोड़कर अभिवादन करते हुए दिखाया गया है।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मेघ के दामाद रूपी मानवीकरण का उदाहरण व व्याख्या</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पीपल के वृद्ध मुखिया रूपी मानवीकरण का उदाहरण व व्याख्या</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 12</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'मेघ आए' कविता भारतीय ग्रामीण संस्कृति में अतिथि-सत्कार और दामाद के स्वागत की किस अनुपम परंपरा को रेखांकित करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>भारतीय लोक-संस्कृति में 'अतिथि देवो भव' की भावना सर्वोपरि है, विशेषकर जब गाँव में किसी का दामाद (पाहुन) आता है, तो पूरा गाँव उसके स्वागत में उमड़ पड़ता है। बच्चे (धूल) दौड़कर खबर देते हैं, बुजुर्ग (पीपल) स्वागत करते हैं, महिलाएँ घूँघट की ओट से देखती हैं और आदरपूर्वक पैर धोने के लिए जल (तालाब) लाया जाता है।</p><p>सर्वेश्वर दयाल सक्सेना ने बादलों के प्राकृतिक आगमन को इस पारंपरिक ग्रामीण पारिवारिक उत्सव से जोड़कर प्रकृति और संस्कृति का ऐसा अनुपम तादात्म्य स्थापित किया है जो अन्यत्र दुर्लभ है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">पर्यावरण असंतुलन के कारण आज वर्षा की अनियमितता से किसानों पर क्या प्रभाव पड़ रहा है? कविता के परिप्रेक्ष्य में समझाइए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कविता में दिखाया गया है कि एक वर्ष के सूखे और वियोग के बाद जब मेघ आते हैं, तो सारी प्रकृति और किसान समुदाय में नया जीवन संचारित हो जाता है। बादलों के आने पर ही ताल भरते हैं और फसलें लहलहाती हैं।</p><p>आज ग्लोबल वार्मिंग और वनों की कटाई के कारण मानसून अनिश्चित हो गया है—कहीं सूखा तो कहीं बाढ़। इससे किसान कर्ज और निराशा के गर्त में डूब रहे हैं। यह कविता हमें यह मूल्य सिखाती है कि प्रकृति का संतुलन बनाए रखना मानव जीवन और अन्नदाता की समृद्धि के लिए अनिवार्य है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(11)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "13": "<section class=\"chapter-section\" id=\"ch13\" data-book=\"kshitij-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">13</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">क्षितिज भाग-1 (काव्य खंड)</div>\n      <h2>बच्चे काम पर जा रहे हैं</h2>\n      <p>राजेश जोशी | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">कोहरे से ढँकी सड़क पर बच्चे काम पर जा रहे हैं\nसुबह-सुबह\nबच्चे काम पर जा रहे हैं\nहमारे समय की सबसे भयानक पंक्ति है यह\nभयानक है इसे विवरण की तरह लिखा जाना\nलिखा जाना चाहिए इसे सवाल की तरह\nकाम पर क्यों जा रहे हैं बच्चे?\nक्या अंतरिक्ष में गिर गई हैं सारी गेंदें?\nक्या दीमकों ने खा लिया है सारी रंग-बिरंगी किताबों को?\nक्या काले पहाड़ के नीचे दब गए हैं सारे खिलौने?\nक्या किसी भूकंप में ढह गई हैं सारे मदरसों की इमारतें?\nक्या सारे मैदान, सारे बगीचे और घरों के आँगन\nखत्म हो गए हैं एकाएक?\nतो फिर बचा ही क्या है इस दुनिया में?\nकितना भयानक होता अगर ऐसा होता\nभयानक है लेकिन इससे भी ज्यादा यह कि हैं सारी चीजें हस्बमामूल\nपर दुनिया की हजारों सड़कों पर गुजरते हुए\nबच्चे, बहुत छोटे-छोटे बच्चे काम पर जा रहे हैं।</div>\n    <div class=\"poet-name\">— राजेश जोशी</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch13-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">कविता की पहली दो पंक्तियों को पढ़ने तथा विचार करने से आपके मन-मस्तिष्क में जो चित्र उभरता है, उसे लिखकर व्यक्त कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कविता की प्रारंभिक पंक्तियों <em>('कोहरे से ढँकी सड़क पर बच्चे काम पर जा रहे हैं, सुबह-सुबह...')</em> को पढ़ते ही मन-मस्तिष्क में अत्यंत करुण, विचलित करने वाला और मार्मिक दृश्य उभरता है:</p>\n<p>कड़ाके की भीषण ठंड है, चारों ओर घना कोहरा छाया हुआ है जहाँ ठीक से देखना भी कठिन है। ऐसी ठिठुरती ठंड में, जब संपन्न घरों के बच्चे गर्म बिस्तरों में सो रहे होते हैं, तब फटे-पुराने पतले कपड़ों में काँपते हुए, नंगे पाँव या टूटी चप्पलों में छोटे-छोटे मासूम बच्चे मजदूरी करने, पेट की आग बुझाने के लिए कारखानों, चाय की दुकानों या ढाबों की ओर विवश कदमों से जा रहे हैं। उनके चेहरों पर बचपन की हँसी नहीं, बल्कि लाचारी और समय से पहले आई प्रौढ़ता का भारी दर्द है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कोहरे, ठंड और फटे कपड़ों में ठिठुरते बच्चों का मार्मिक दृश्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बचपन के उल्लास के स्थान पर लाचारी और विवशता का सजीव चित्रण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं संवेदना</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch13-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">कवि का मानना है कि बच्चों के काम पर जाने की भयानक बात को विवरण की तरह न लिखकर सवाल की तरह पूछा जाना चाहिए कि 'काम पर क्यों जा रहे हैं बच्चे?' कवि की दृष्टि में इसे प्रश्न के रूप में क्यों पूछा जाना चाहिए?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि की दृष्टि में इसे एक सामान्य समाचार या 'विवरण' की तरह नहीं लिखा जाना चाहिए, क्योंकि विवरण केवल सूचना देता है और पाठक उसे पढ़कर उदासीन बना रहता है।</p>\n<p>इसे <strong>'ज्वलंत सवाल' (प्रश्न)</strong> की तरह इसलिए पूछा जाना चाहिए ताकि:</p>\n<ul>\n  <li>यह समाज, शासन और व्यवस्था के सोए हुए विवेक और संवेदनशीलता को झकझोर सके।</li>\n  <li>प्रश्न पूछने से जवाबदेही तय होती है। समाज यह सोचने को मजबूर हो कि जिस उम्र में इन बच्चों के हाथों में किताबें और खिलौने होने चाहिए, उस उम्र में वे कठोर श्रम करने को क्यों विवश हैं? इस अन्यायपूर्ण सामाजिक व्यवस्था का दोषी कौन है?</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विवरण की उदासीनता बनाम प्रश्न की चुभन का अंतर</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामाजिक जवाबदेही और व्यवस्था को झकझोरने का उद्देश्य</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch13-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">सुविधा और मनोरंजन के उपकरणों से बच्चे वंचित क्यों हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>हमारे समाज में गरीब और वंचित वर्ग के बच्चे खेल-कूद, शिक्षा और मनोरंजन के बुनियादी साधनों से निम्नलिखित कारणों से वंचित हैं:</p>\n<ul>\n  <li><strong>चरम गरीबी और भुखमरी:</strong> इन बच्चों के परिवारों की आर्थिक स्थिति इतनी दयनीय होती है कि माता-पिता के लिए दो वक्त की रोटी जुटाना भी दूभर होता है। ऐसे में किताबें या खिलौने खरीदना उनके लिए असंभव सपना है।</li>\n  <li><strong>सामाजिक व आर्थिक विषमता:</strong> समाज में संसाधनों का वितरण अत्यंत असमान है। पूँजीवादी व्यवस्था में गरीबों का निरंतर शोषण होता है।</li>\n  <li><strong>परिवार के भरण-पोषण की विवशता:</strong> परिवार को जीवित रखने के लिए नन्हे बच्चों को भी कम उम्र में मजदूरी के दलदल में धकेल दिया जाता है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आर्थिक विपन्नता और भुखमरी का मुख्य कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सामाजिक विषमता और बालश्रम की विवशता का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch13-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">दिन-प्रतिदिन के जीवन में हर कोई बच्चों को काम पर जाते देख रहा है/रही है, फिर भी किसी को कुछ अटपटा नहीं लगता। इस उदासीनता के क्या कारण हो सकते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>आज के समाज में इस भयानक संवेदनहीनता और उदासीनता के प्रमुख कारण निम्नलिखित हैं:</p>\n<ul>\n  <li><strong>संवेदनाओं का मर जाना (आत्मकेंद्रित होना):</strong> आधुनिक मनुष्य केवल अपने स्वार्थ और अपने परिवार तक सीमित हो गया है। दूसरों के दुखों से उसे कोई सरोकार नहीं रहा।</li>\n  <li><strong>परिस्थिति को 'नियति' मान लेना:</strong> लोग मान लेते हैं कि यह तो इन गरीबों का भाग्य है और यह कभी बदल नहीं सकता।</li>\n  <li><strong>सस्ते श्रम का लोभ:</strong> समाज के अनेक दुकानदार, ढाबा मालिक और ठेकेदार जानबूझकर बच्चों से काम करवाते हैं क्योंकि बच्चे कम मजदूरी में बिना विरोध किए घंटों काम करते हैं। लोग इसे सामान्य मानकर अनदेखा कर देते हैं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्मकेंद्रित स्वार्थपरता एवं संवेदनहीनता का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाग्यवादिता एवं सस्ते श्रम के शोषणकारी रवैये का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch13-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">आपने अपने शहर में बच्चों को कब-कब और कहाँ-कहाँ काम करते देखा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>हमने अपने दैनिक जीवन में शहर के विभिन्न स्थानों पर नन्हे बच्चों को अत्यंत प्रतिकूल परिस्थितियों में कठोर श्रम करते देखा है:</p>\n<ul>\n  <li>चाय की दुकानों, ढाबों और होटलों में जूठे बर्तन धोते और टेबल साफ करते हुए,</li>\n  <li>सड़क के चौराहों और ट्रैफिक सिग्नलों पर अखबार, फूल या खिलौने बेचते और भीख माँगते हुए,</li>\n  <li>ऑटो-रिपेयरिंग गैराजों में ग्रीस और कालिख से सने हाथों से भारी औजार उठाते हुए,</li>\n  <li>ईंट-भट्ठों, निर्माण स्थलों (कंस्ट्रक्शन साइटों) पर सिर पर ईंटें ढोते हुए, तथा सुबह-सुबह कचरे के ढेरों से प्लास्टिक और कबाड़ बीनते हुए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ढाबों, होटलों और चाय की दुकानों पर बर्तन धोने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ट्रैफिक सिग्नल, गैराज, निर्माण स्थलों और कबाड़ बीनने का वास्तविक विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch13-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch13-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">बच्चों का काम पर जाना धरती के एक बड़े हादसे के समान क्यों है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि ने बच्चों के काम पर जाने को धरती का सबसे बड़ा 'हादसा' (दुर्घटना) इसलिए कहा है क्योंकि:</p>\n<ol>\n  <li><strong>मानवता और भविष्य की हत्या:</strong> बच्चे किसी भी देश और संपूर्ण मानव जाति का भविष्य होते हैं। यदि उनका बचपन ही छीन लिया जाए, तो पूरी मानव सभ्यता का भविष्य अंधकारमय हो जाता है।</li>\n  <li><strong>मौलिक अधिकारों का हनन:</strong> प्रत्येक बच्चे को खेलने, कूदने, पढ़ने और स्वस्थ वातावरण में विकसित होने का प्राकृतिक और संवैधानिक अधिकार है। काम पर जाना उनके इन सभी अधिकारों की नृशंस हत्या है।</li>\n  <li><strong>अपराध और अशिक्षा का दुष्चक्र:</strong> बालश्रम के कारण बच्चे अशिक्षित रह जाते हैं, जिससे वे जीवन भर शोषण, गरीबी और अपराध के दुष्चक्र से बाहर नहीं निकल पाते। जिस समाज में बच्चे खिलौनों के बजाय औजार उठाने लगें, उस समाज के जीवित रहने का कोई नैतिक औचित्य नहीं बचता।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भविष्य के अंधकारमय होने और मानवता पर आघात का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिक्षा एवं खेल के प्राकृतिक अधिकारों के हनन का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अशिक्षा एवं गरीबी के दुष्चक्र का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं तर्क</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 13</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">बालश्रम (Child Labour) केवल एक सामाजिक कुरीति नहीं बल्कि एक जघन्य अपराध है। एक जागरूक नागरिक के रूप में हम इसे समाप्त करने में क्या सक्रिय भूमिका निभा सकते हैं?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>बालश्रम मानवता के माथे पर एक काला कलंक है। इसे केवल कानूनों के भरोसे नहीं छोड़ा जा सकता, इसके लिए जन-जागरूकता आवश्यक है।</p><p>एक जागरूक नागरिक के रूप में हमारा कर्तव्य है कि हम कभी किसी होटल, ढाबे, दुकान या घरेलू कार्य में बच्चों को काम पर न रखें और न ही ऐसे प्रतिष्ठानों का समर्थन करें जो बालश्रम कराते हैं। यदि हम किसी बच्चे को काम करते देखें, तो तुरंत चाइल्ड हेल्पलाइन (1098) पर सूचित करें तथा गरीब बच्चों की शिक्षा के लिए किताबें, कपड़े और आर्थिक सहायता प्रदान करने में आगे आएँ। जब तक हर बच्चे के हाथ में कलम नहीं होगी, राष्ट्र महान नहीं बन सकता।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'हस्बमामूल' (यथावत/जैसी थीं वैसी) शब्द के माध्यम से कवि समाज की किस भयावह विडंबना पर चोट कर रहे हैं?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कवि कहते हैं कि यदि भूकंप में सारे स्कूल ढह जाते या अंतरिक्ष में सारी गेंदें गिर जातीं, तो बच्चों का काम पर जाना एक स्वाभाविक विवशता होती। परंतु सबसे भयानक बात यह है कि सारी गेंदें, बगीचे, स्कूल और खिलौने दुनिया में सुरक्षित (हस्बमामूल) मौजूद हैं, फिर भी गरीब बच्चों को उनसे वंचित कर काम पर भेजा जा रहा है।</p><p>यह शब्द समाज में व्याप्त चरम विषमता, संवेदनहीनता और स्वार्थपरता की ओर संकेत करता है जहाँ प्रचुर साधन होने के बाद भी एक बड़ा वर्ग बुनियादी मानवीय गरिमा से वंचित है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(12)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(14)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "14": "<section class=\"chapter-section\" id=\"ch14\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">14</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>इस जल प्रलय में</h2>\n      <p>फणीश्वरनाथ रेणु | पूरक पाठ्यपुस्तक (रिपोर्ताज) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch14-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">बाढ़ की खबर सुनकर लोग किस तरह की तैयारी करने लगे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>1975 में जब पटना में पुनपुन नदी का पानी तेजी से शहर में घुसने लगा, तो बाढ़ की खबर सुनते ही लोग अपने दैनिक जीवन की आवश्यक वस्तुओं को सुरक्षित करने में जुट गए:</p>\n<ul>\n  <li>दुकानदारों ने निचले तल से अपना माल उठाकर ऊपरी मंजिलों या सुरक्षित ऊँचे स्थानों पर पहुँचाना शुरू कर दिया।</li>\n  <li>आम नागरिकों ने घरों में कई दिनों के लिए पर्याप्त राशन, ईंधन (कोयला, मिट्टी का तेल, गैस), मोमबत्तियाँ, माचिस, पीने का पानी और जरूरी दवाइयाँ (विशेषकर कंपोज की गोलियाँ आदि) जमा कर लीं।</li>\n  <li>लोग रिक्शों, कारों और ट्रकों पर अपना कीमती घरेलू सामान लादकर सुरक्षित ऊँचे इलाकों की ओर पलायन करने लगे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राशन, ईंधन, मोमबत्ती, पीने के पानी आदि के संग्रहण का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निचले तलों से सामान ऊपर चढ़ाने व ऊँचे स्थानों पर जाने का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">बाढ़ के सही रूप को देखने के लिए लेखक क्यों उत्सुक था?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>फणीश्वरनाथ रेणु जी ने अपने जीवन में बाढ़ पीड़ितों की सेवा अनेक बार की थी और बाढ़ पर कई संवेदनशील कहानियाँ तथा रिपोर्ताज लिखे थे। परंतु वे गाँव के ऐसे अंचल में जन्मे और पले-बढ़े थे जहाँ चारों ओर से बाढ़ से घिरे होने पर भी उनका गाँव कभी नहीं डूबा था।</p>\n<p>उन्होंने बाढ़ के विनाश और पीड़ितों की करुण दशा को तो देखा था, परंतु किसी विशाल शहर (जैसे पटना) के भीतर बाढ़ के पानी के घुसने, सड़कों और कॉलोनियों के एक-एक कर जलमग्न होने के जीवंत दृश्य को उन्होंने कभी अपनी आँखों से नहीं देखा था। इस नए और भयावह प्रत्यक्ष अनुभव को देखने के लिए वे अत्यंत उत्सुक और रोमांचित थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गाँव में पले-बढ़े होने और स्वयं बाढ़ न भुगतने की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहरी परिवेश में पानी घुसने के प्रत्यक्ष दृश्य को देखने की जिज्ञासा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">'मृत्यु का तरल दूत' किसे कहा गया है और क्यों?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'मृत्यु का तरल दूत' <strong>बाढ़ के तेजी से बढ़ते हुए फेनिल, गंदले और मटमैले जल</strong> को कहा गया है।</p>\n<p><strong>कारण:</strong></p>\n<ul>\n  <li>जिस प्रकार यमराज का दूत किसी जीव के प्राण हरने आता है, उसी प्रकार बाढ़ का यह जल असीम गति से आगे बढ़कर जन-धन, मकानों, पशुओं और मनुष्य के जीवन को लीलने आ रहा था।</li>\n  <li>इसके प्रवाह के सामने जो भी आया, वह बहकर काल के गाल में समा गया। यह पानी जीवन देने वाला अमृत नहीं, बल्कि सर्वनाश और मौत लाने वाला द्रव (तरल) था, इसलिए लेखक ने इसे 'मृत्यु का तरल दूत' की संज्ञा दी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बाढ़ के मटमैले, उफनते जल को तरल दूत मानने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">यमदूत सदृश जन-धन के विनाश और मृत्यु लाने के तार्किक कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आपदाओं से निपटने के लिए अपनी तरफ से कुछ उपयोगी सुझाव दीजिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>प्राकृतिक अथवा मानव-निर्मित आपदाओं (बाढ़, भूकंप, चक्रवात आदि) के समय जन-धन की रक्षा के लिए निम्नलिखित व्यावहारिक कदम उठाए जाने चाहिए:</p>\n<ol>\n  <li><strong>पूर्व चेतावनी एवं मौसम प्रणाली:</strong> आधुनिक उपग्रह प्रणाली और सायरन के माध्यम से आपदा आने से पूर्व ही जनता को सुरक्षित स्थानों पर स्थानांतरित करने की पूर्व-योजना होनी चाहिए।</li>\n  <li><strong>जल निकासी एवं तटबंधों का रखरखाव:</strong> शहरों के नालों की समय पर सफाई तथा नदियों के तटबंधों की नियमित मरम्मत अनिवार्य रूप से की जाए।</li>\n  <li><strong>आपदा प्रबंधन दल (NDRF) की त्वरित तैनाती:</strong> लाइफ-जैकैट, मोटरबोट, हेलीकॉप्टर तथा बचाव दलों को आवश्यक उपकरणों के साथ अलर्ट रखा जाए।</li>\n  <li><strong>राशन, स्वच्छ जल एवं प्राथमिक चिकित्सा का सुरक्षित भंडार:</strong> महामारी (हैजा, मलेरिया, डायरिया) से बचाव के लिए दवाइयाँ और ओ.आर.एस. के पैकेट पर्याप्त मात्रा में सुरक्षित रखे जाएँ।</li>\n  <li><strong>नागरिक जागरूकता एवं प्रशिक्षण:</strong> स्कूलों और मोहल्लों में आपदा से निपटने के लिए नियमित 'मॉक ड्रिल' कराई जाए ताकि लोग घबराने के बजाय धैर्य से कार्य करें।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पूर्व चेतावनी प्रणाली एवं जल निकासी/तटबंध का रखरखाव</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राहत एवं बचाव दल (NDRF) तथा नौकाओं की व्यवस्था</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">राशन, स्वच्छ जल एवं संक्रामक रोगों की दवाइयों का प्रबंध</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जन-जागरूकता एवं मॉक ड्रिल का बिंदु</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुव्यवस्थित भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">‘ईह! जब दानापुर डूब रहा था तो पटनियाँ बाबू लोग उलटकर देखने भी नहीं गए... अब बूझो!’ — इस कथन द्वारा लोगों की किस मानसिकता पर चोट की गई है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बाढ़ के समय एक ग्रामीण व्यक्ति द्वारा बोले गए इस तीखे कथन से समाज में व्याप्त <strong>शहरी संवेदनहीनता, आत्मकेंद्रित स्वार्थपरता और क्षेत्रीय ईर्ष्या</strong> की मानसिकता पर करारा प्रहार किया गया है।</p>\n<p>जब दानापुर के गरीब और ग्रामीण लोग बाढ़ में डूब रहे थे, तब पटना के संपन्न और सुविधाभोगी 'बाबू लोग' अपने महलों में आराम से बैठे रहे और उन्होंने पीड़ितों की सुध तक नहीं ली। जब वही संकट पटना पर आया, तो ग्रामीण व्यक्ति ने व्यंग्य किया। यह कथन यह दर्शाता है कि जब तक विपत्ति स्वयं पर नहीं आती, तब तक मनुष्य दूसरों के दर्द के प्रति पूरी तरह उदासीन रहता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शहरी संवेदनहीनता और स्वार्थपरता की पहचान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विपत्ति के समय दूसरों के प्रति उदासीनता पर व्यंग्य का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">खरीद-बिक्री बंद हो चुकने पर भी पान की बिक्री अचानक क्यों बढ़ गई थी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बाढ़ के भय से पूरे बाजार की अन्य सभी दुकानें बंद हो चुकी थीं, परंतु केवल पान की दुकान पर असामान्य भीड़ उमड़ रही थी। इसके निम्नलिखित मुख्य कारण थे:</p>\n<ul>\n  <li><strong>रेडियो से समाचार सुनने की उत्सुकता:</strong> पान की दुकान पर एक ट्रांजिस्टर (रेडियो) रखा था, जहाँ लाउडस्पीकर पर पटना आकाशवाणी से बाढ़ के ताजा समाचार और चेतावनी प्रसारित हो रही थी। लोग समाचार जानने के लिए वहाँ जमा हो रहे थे।</li>\n  <li><strong>समय बिताने और घबराहट कम करने का साधन:</strong> बाढ़ के कारण लोग भयभीत और खाली थे। वे पान खाते हुए एक-दूसरे से बाढ़ की चर्चा कर रहे थे और आगामी खतरे का अनुमान लगा रहे थे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुकान पर रेडियो से बाढ़ के समाचार सुनने की जिज्ञासा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लोगों का भय, चर्चा और पान खाकर समय बिताने की प्रवृत्ति</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">नौजवान के पानी में उतरते ही कुत्ता भी पानी में कूद पड़ा। दोनों ने किन भावनाओं के वशीभूत होकर ऐसा किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>जब डॉक्टर साहब ने कहा कि नौजवान तो नाव में बैठ सकता है किंतु उसके बीमार कुत्ते को नहीं ले जाया जाएगा, तब उस स्वाभिमानी नौजवान ने अकेले सुरक्षित रहने से इनकार कर दिया और वह तुरंत बाढ़ के पानी में कूद पड़ा। उसे देखते ही उसका वफादार कुत्ता भी पानी में छपाक से कूद पड़ा।</p>\n<p><strong>भावनाएँ:</strong></p>\n<ul>\n  <li><strong>परस्पर अनन्य प्रेम एवं वफादारी:</strong> दोनों के बीच मनुष्य और पशु की सीमाओं से परे आत्मीयता का गहरा बंधन था।</li>\n  <li><strong>सच्ची निष्ठा एवं सह-अस्तित्व:</strong> दोनों में से कोई भी एक-दूसरे को विपत्ति में छोड़कर अकेले नहीं जीना चाहता था। वे जीना चाहते थे तो साथ, और मरना चाहते थे तो साथ।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नौजवान के स्वाभिमान और पशु-प्रेम का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कुत्ते की वफादारी और सुख-दुःख में साथ निभाने की भावना का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch14-q8\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch14-q8')\">\n      <div class=\"q-num\">प्रश्न 8</div>\n      <div class=\"q-text\">‘अच्छा है, कुछ भी नहीं। कलम थी, वह भी चोरी चली गई। अच्छा है, कुछ भी नहीं-मेरे पास।’ — लेखक के इस कथन में कौन-सी मानसिक दशा झलकती है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बाढ़ का उफनता पानी जब लेखक के घर के पास पहुँच गया, तो पहले उन्होंने सोचा कि काश उनके पास एक मूवी कैमरा या टेपरिकॉर्डर होता ताकि वे इस भयावह दृश्य को रिकॉर्ड कर लेते। फिर उन्होंने सोचा कि कम से कम कलम होती तो वे लिख लेते, पर कलम भी चोरी हो चुकी थी।</p>\n<p>अंततः वे कहते हैं कि अच्छा है, मेरे पास कुछ भी नहीं है। इसमें लेखक की <strong>कलाकार की बौद्धिक तड़प और एक विवश असहाय मूक दर्शक की मानसिक दशा</strong> झलकती है। वे संकट के समय केवल एक मूक और निष्पक्ष दर्शक बनकर उस प्राकृतिक प्रलय का सीधा साक्षात्कार करना चाहते थे, बिना किसी उपकरण या साहित्यिक औपचारिकता के।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रिकॉर्डिंग और कलम के अभाव की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कलाकार के उद्वेलन और मूक दर्शक बनकर प्रलय झेलने की मानसिक दशा का उद्घाटन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं अभिव्यक्ति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 14</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">फणीश्वरनाथ रेणु की रिपोर्ताज शैली की उन विशेषताओं का उल्लेख कीजिए जो इसे सामान्य पत्रकारिता से अलग और साहित्यिक बनाती हैं।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>रेणु जी की रिपोर्ताज शैली केवल सूखी घटनाएँ और आंकड़े प्रस्तुत नहीं करती, बल्कि उसमें मानवीय संवेदना, आंतरिक भय, हास्य-व्यंग्य और स्थानीय बोलचाल (आंचलिकता) का अद्भुत संगम होता है।</p><p>वे सिनेमा हॉल के पास खड़े रिक्शेवालों की बातचीत, लाउडस्पीकर की गूँजती आवाज, पान की दुकान का दृश्य और 'मृत्यु के तरल दूत' जैसे प्रतीकात्मक बिंबों का ऐसा सजीव ताना-बाना बुनते हैं कि पाठक केवल समाचार नहीं पढ़ता, बल्कि उस प्रलयंकारी माहौल को स्वयं अपनी आँखों से देखता और महसूस करता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">आपदा के समय 'अफवाहों' का फैलना किस प्रकार संकट को और अधिक भयावह बना देता है? इससे बचने के लिए नागरिकों को क्या सावधानी बरतनी चाहिए?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>पाठ में दिखाया गया है कि कैसे 'राजभवन डूब गया', 'कॉफी हाउस में पानी आ गया' जैसी आधी-अधूरी बातों से शहर में भगदड़ और घबराहट फैल गई थी। आपदा के समय अफवाहें जनता में अनावश्यक भय, कालाबाजारी और मानसिक उन्माद पैदा करती हैं।</p><p>नागरिकों को केवल आधिकारिक सरकारी स्रोतों, प्रमाणित रेडियो/टेलीविजन बुलेटिनों पर ही विश्वास करना चाहिए। सोशल मीडिया पर बिना पुष्टि के कोई भी संदेश फॉरवर्ड नहीं करना चाहिए तथा संकट की घड़ी में धैर्य, संयम और पारस्परिक सहयोग बनाए रखना चाहिए।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(13)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(15)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "15": "<section class=\"chapter-section\" id=\"ch15\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">15</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>मेरे संग की औरतें</h2>\n      <p>मृदुला गर्ग | पूरक पाठ्यपुस्तक (संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch15-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखिका ने अपनी नानी को कभी देखा भी नहीं फिर भी उनके व्यक्तित्व से वे क्यों प्रभावित थीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>मृदुला गर्ग जी की नानी का देहांत उनकी माँ के विवाह से पहले ही हो गया था, इसलिए लेखिका ने उन्हें कभी प्रत्यक्ष रूप से नहीं देखा था। फिर भी वे अपनी नानी के व्यक्तित्व से गहराई से प्रभावित थीं क्योंकि:</p>\n<ul>\n  <li><strong>पारंपरिक होकर भी क्रांतिकारी चेतना:</strong> नानी अनपढ़, पर्दानशीं और पारंपरिक महिला थीं, परंतु उनके भीतर देश की स्वतंत्रता के लिए अटूट और ज्वलंत निष्ठा थी।</li>\n  <li><strong>अंतिम समय में असाधारण निर्णय:</strong> अपनी मृत्यु निकट जानकर उन्होंने पति के विलायती अंग्रेज-भक्त मित्रों की परवाह न करते हुए स्वतंत्रता सेनानी प्यारेलाल शर्मा को बुलवाया और वचन लिया कि उनकी बेटी (लेखिका की माँ) का विवाह किसी अंग्रेज-परस्त अधिकारी से नहीं, बल्कि एक सच्चे स्वाधीनता सेनानी से ही कराया जाए। यह उनके अदम्य स्वाभिमान और देशप्रेम का अनुपम प्रमाण था।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नानी के अनपढ़ व पर्दानशीं होने के बावजूद स्वतंत्रता चेतना का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्यारेलाल शर्मा से बेटी के विवाह हेतु दिए गए क्रांतिकारी वचन का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch15-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">लेखिका की नानी की आज़ादी के आंदोलन में किस प्रकार की भागीदारी रही?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>लेखिका की नानी ने आजादी के आंदोलन में कभी प्रत्यक्ष रूप से सड़कों पर उतरकर, धरने-प्रदर्शन करके या जेल जाकर भाग नहीं लिया। परंतु उनकी परोक्ष (अप्रत्यक्ष) भागीदारी अत्यंत सशक्त और निर्णायक थी:</p>\n<ul>\n  <li>उनके पति विलायत से बैरिस्ट्री पढ़कर आए थे और अंग्रेजों की शान-शौकत वाली जिंदगी जीते थे, परंतु नानी ने कभी अपनी भारतीय सादगी से समझौता नहीं किया।</li>\n  <li>अपने जीवन के अंतिम पलों में उन्होंने अपने पति के प्रभाव को दरकिनार करते हुए अपनी इकलौती बेटी का रिश्ता एक क्रांतिकारी देशभक्त से तय करवाया। इस प्रकार उन्होंने अपनी संतान का जीवन देश की स्वाधीनता की वेदी पर समर्पित कर दिया, जो कि प्रत्यक्ष भागीदारी से भी कहीं अधिक प्रभावशाली योगदान था।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रत्यक्ष आंदोलन में न जाने किंतु मानसिक रूप से पूर्ण समर्पित होने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पति के विलायती प्रभाव का विरोध एवं बेटी का विवाह स्वतंत्रता सेनानी से कराने का महत्व</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch15-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखिका की माँ परंपरा का निर्वाह न करते हुए भी सबके दिलों पर राज करती थीं। इस कथन के आलोक में लेखिका की माँ के व्यक्तित्व की विशेषताएँ लिखिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>लेखिका की माँ एक पारंपरिक भारतीय गृहिणी की तरह न तो खाना बनाती थीं, न बच्चों का लालन-पालन करती थीं और न ही सास-ससुर की सेवा में जुटी रहती थीं। उनका अधिकांश समय पुस्तकें पढ़ने, संगीत सुनने और साहित्य-चर्चा में बीतता था। फिर भी वे परिवार के प्रत्येक सदस्य के दिल पर राज करती थीं, जिसके कारण निम्नलिखित थे:</p>\n<ol>\n  <li><strong>सत्यनिष्ठा एवं ईमानदारी:</strong> वे कभी झूठ नहीं बोलती थीं, जिसके कारण पूरे परिवार में उनके वचनों को पत्थर की लकीर माना जाता था।</li>\n  <li><strong>गोपनीयता का सम्मान (निष्ठा):</strong> वे कभी एक व्यक्ति की गुप्त बात दूसरे को नहीं बताती थीं। घर के बाहर के लोग भी अपने रहस्य उनसे साझा करते थे और वे उनकी सच्ची मित्र व सलाहकार थीं।</li>\n  <li><strong>सादगी और निष्पक्षता:</strong> वे खादी की साड़ियाँ पहनती थीं जो उनके नाजुक शरीर के लिए भारी होती थीं। वे किसी के निजी जीवन में हस्तक्षेप नहीं करती थीं और सबको अपनी स्वतंत्रता से जीने देती थीं।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पारंपरिक घरेलू कार्यों से विमुख होने की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सत्यवादिता और कभी झूठ न बोलने की विशेषता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गोपनीयता की रक्षा, निष्पक्षता एवं साहित्यिक अभिरुचि का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुव्यवस्थित भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch15-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">आप अपनी कल्पना से लिखिए कि परदादी ने पतोहू के लिए पहले बच्चे के रूप में लड़की पैदा होने की मन्नत क्यों माँगी होगी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>उस युग में जब पूरा समाज पुत्र-प्राप्ति के लिए मंदिरों में माथा टेकता था, परदादी द्वारा सरेआम भगवान से पहली संतान के रूप में 'लड़की' माँगना एक अत्यंत विस्मयकारी और साहसिक कदम था। इसके संभावित कारण निम्नलिखित हो सकते हैं:</p>\n<ul>\n  <li><strong>रूढ़ियों और परंपराओं को तोड़ने की चाह:</strong> परदादी लीक से हटकर चलने वाली स्वतंत्र विचारों की महिला थीं। वे समाज की दकियानूसी सोच को चुनौती देना चाहती थीं।</li>\n  <li><strong>कन्या के प्रति अगाध आदर:</strong> वे मानती थीं कि बेटियाँ परिवार की वास्तविक शक्ति, मर्यादा और लक्ष्मी होती हैं। घर में पहले से कोई पुत्री न होने के कारण वे परिवार में एक बालिका की किलकारियाँ सुनना चाहती थीं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लीक से हटकर चलने और सामाजिक रूढ़ियों को चुनौती देने का भाव</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुत्री के प्रति सम्मान और परिवार में बालिका की आकांक्षा का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch15-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">डराने-धमकाने, उपदेश देने या दबाव डालने की जगह सहजता से किसी को भी सही राह पर लाया जा सकता है — पाठ के आधार पर तर्क सहित सिद्ध कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>पाठ में लेखिका की परदादी और चोर का प्रसंग इस मानवीय मूल्य को अत्यंत प्रामाणिक रूप से सिद्ध करता है:</p>\n<p>जब एक चोर हवेली में सेंध लगाकर परदादी के कमरे में घुसा, तो परदादी की नींद खुल गई। उन्होंने शोर मचाने या उसे पकड़वाने के बजाय अत्यंत सहजता से उससे पीने के लिए पानी माँगा। जब चोर ने बताया कि वह चोर है, तब भी परदादी ने घृणा नहीं की। उन्होंने उसके हाथ से आधा लोटा पानी पिया और आधा उसे पिलाते हुए कहा—<em>'अब हम दोनों माँ-बेटे हुए। चाहे तो तू चोरी कर या खेती।'</em></p>\n<p>परदादी के इस अगाध विश्वास, मातृत्व और आत्मीय व्यवहार ने चोर की अंतरात्मा को झकझोर कर रख दिया। किसी उपदेश या लाठी ने नहीं, बल्कि उस निस्वार्थ मातृत्व ने चोर का हृदय-परिवर्तन कर दिया। उसने उसी क्षण चोरी का धंधा हमेशा के लिए छोड़ दिया और ईमानदारी से खेती करने लगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परदादी और चोर के संवाद एवं पानी पिलाने की घटना का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मातृत्व, विश्वास और अपनत्व से चोर के हृदय-परिवर्तन का विश्लेषण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता एवं नैतिक निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch15-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch15-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">'शिक्षा बच्चों का जन्मसिद्ध अधिकार है' — इस दिशा में लेखिका (मृदुला गर्ग) के प्रयासों का उल्लेख कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>शादी के बाद जब लेखिका कर्नाटक के एक छोटे और पिछड़े कस्बे 'बागलकोट' में पहुँचीं, तो वहाँ उनके बच्चों के पढ़ने के लिए कोई अच्छा स्कूल नहीं था।</p>\n<p>लेखिका ने इसे नियति मानकर हाथ पर हाथ रखकर बैठने के बजाय सक्रिय प्रयास किए:</p>\n<ul>\n  <li>उन्होंने कैथोलिक बिशप से स्कूल खोलने की प्रार्थना की, परंतु उन्होंने मना कर दिया।</li>\n  <li>लेखिका ने हार नहीं मानी। उन्होंने स्थानीय नागरिकों और अन्य उत्साही माताओं के सहयोग से स्वयं एक प्राइमरी स्कूल खोला जिसमें अंग्रेजी, हिंदी और कन्नड़ तीन भाषाएँ पढ़ाई जाती थीं।</li>\n  <li>उन्होंने उस स्कूल को कर्नाटक सरकार से विधिवत मान्यता भी दिलवाई, जहाँ आगे चलकर अनेक प्रतिष्ठित अधिकारियों और नागरिकों के बच्चे शिक्षित हुए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बागलकोट में स्कूल के अभाव की समस्या का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बिशप के इनकार के बाद स्वयं प्राइमरी स्कूल खोलने का साहसिक प्रयास</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सरकारी मान्यता दिलवाने और शिक्षा अधिकार की पूर्ति का वर्णन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 15</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">'मेरे संग की औरतें' पाठ में वर्णित महिलाएँ अपनी व्यक्तिगत स्वतंत्रता (Space) को बनाए रखते हुए भी परिवार को कैसे जोड़े रखती थीं? आधुनिक महिलाओं के लिए इसका क्या संदेश है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>पाठ की सभी महिलाएँ (नानी, दादी, माँ और बहनें) पारंपरिक बंधनों में बँधकर नहीं जीती थीं। वे सब लीक से हटकर अपनी मर्जी से जीती थीं, परंतु उन्होंने कभी परिवार को तोड़ा नहीं। लेखिका की माँ ने घर के काम न करने पर भी कभी बच्चों पर अपने विचार नहीं थोपे और सबको अपनी स्वतंत्रता दी।</p><p>आधुनिक महिलाओं और परिवारों के लिए संदेश यह है कि व्यक्तिगत स्वतंत्रता और पारिवारिक एकजुटता एक-दूसरे के विरोधी नहीं हैं। यदि परिवार के सदस्यों में परस्पर विश्वास, सम्मान और एक-दूसरे के व्यक्तित्व (Personal Space) को स्वीकार करने की उदारता हो, तो परिवार और समाज अधिक सुदृढ़ बनता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">लेखिका की बहनों (मंजुल भगत, चित्रा, अचला) और स्वयं लेखिका के साहित्यिक योगदान से क्या सिद्ध होता है? नारी सशक्तीकरण के संदर्भ में विचार व्यक्त कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>लेखिका की चारों बहनों ने स्वतंत्र चिंतन, लेखन और स्वावलंबन का मार्ग चुना। शादी के बाद भी उन्होंने अपनी प्रतिभा और रचनात्मकता को चूल्हे-चौके तक सीमित नहीं होने दिया। किसी ने हिंदी में लिखा तो किसी ने अंग्रेजी में।</p><p>यह सिद्ध करता है कि वास्तविक नारी सशक्तीकरण केवल कानूनी अधिकारों से नहीं आता, बल्कि यह बौद्धिक स्वतंत्रता, आत्म-विश्वास और अपनी रचनात्मक क्षमताओं को समाज के समक्ष निडरता से प्रस्तुत करने से आता है। जब स्त्री अपनी पहचान स्वयं गढ़ती है, तभी वह समाज का सच्चा मार्गदर्शन कर सकती है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(14)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(16)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "16": "<section class=\"chapter-section\" id=\"ch16\" data-book=\"kritika\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">16</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">कृतिका भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>रीढ़ की हड्डी</h2>\n      <p>जगदीशचंद्र माथुर | पूरक पाठ्यपुस्तक (एकांकी नाटक) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch16-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">रामस्वरूप और गोपाल प्रसाद बात-बात पर 'एक हमारा जमाना था...' कहकर अपने समय की तुलना वर्तमान समय से करते हैं। इस प्रकार की तुलना कहाँ तक तर्कसंगत है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बुजुर्गों द्वारा अपने बीते हुए समय को सर्वश्रेष्ठ बताना और बात-बात पर <em>'एक हमारा जमाना था...'</em> कहकर वर्तमान पीढ़ी को कमतर आँकना किसी भी दृष्टि से <strong>पूरी तरह तर्कसंगत नहीं है।</strong></p>\n<p><strong>कारण:</strong></p>\n<ul>\n  <li>समय परिवर्तनशील है। हर युग की अपनी सामाजिक, आर्थिक और नैतिक परिस्थितियाँ होती हैं। पुराने समय में यदि सादगी थी, तो बाल-विवाह, अशिक्षा और पर्दा-प्रथा जैसी भीषण बुराइयाँ भी थीं।</li>\n  <li>वर्तमान युग में विज्ञान, स्त्री-शिक्षा और मानवीय अधिकारों का अभूतपूर्व विकास हुआ है। अतः अतीत का अंधानुकरण करने या वर्तमान की हर अच्छी बात को नकारने के बजाय दोनों के सकारात्मक मूल्यों का समन्वय करना ही श्रेयस्कर है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">परिवर्तनशीलता और तुलना के अतार्किक होने का पक्ष</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अतीत की कुरीतियों बनाम आधुनिक शिक्षा व मानवीय अधिकारों का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch16-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">रामस्वरूप का अपनी बेटी (उमा) को उच्च शिक्षा दिलवाना और विवाह के लिए छिपाना, यह विरोधाभास उनकी किस विवशता को उजागर करता है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रामस्वरूप एक आधुनिक और प्रगतिशील विचारों के पिता हैं, जिन्होंने अपनी बेटी उमा को बी.ए. तक उच्च शिक्षा दिलवाई, संगीत और चित्रकला सिखाई। परंतु विवाह के समय वे लड़के वालों से उसकी शिक्षा छिपाकर केवल 'मैट्रिक पास' बताते हैं।</p>\n<p><strong>यह विरोधाभास निम्नलिखित सामाजिक विवशताओं को उजागर करता है:</strong></p>\n<ol>\n  <li><strong>पुरुष प्रधान समाज की संकीर्ण मानसिकता:</strong> समाज में आज भी पढ़ी-लिखी, स्वाभिमानी और स्वतंत्र विचारों वाली बहू को स्वीकार करने से हिचकिचाहट होती है। वर पक्ष (गोपाल प्रसाद) चाहता है कि बहू कम पढ़ी-लिखी हो ताकि वह उनकी कठपुतली बनकर रहे।</li>\n  <li><strong>एक लाचार पिता की चिंता:</strong> बेटी का विवाह किसी अच्छे और संपन्न परिवार में हो जाए, इस सामाजिक दबाव और भय के कारण रामस्वरूप अपनी प्रगतिशील सोच को दबाकर झूठ का सहारा लेने को विवश हो जाते हैं। यह हमारे पितृसत्तात्मक समाज का दुखद दोगलापन है।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उच्च शिक्षा दिलवाने और विवाह में छिपाने के विरोधाभास का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पुरुष प्रधान समाज में शिक्षित वधु के प्रति संकीर्णता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पिता की सामाजिक विवशता और समाज के दोहरे चरित्र का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch16-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">अपनी बेटी का रिश्ता तय करने के लिए रामस्वरूप उमा से जिस प्रकार के व्यवहार की अपेक्षा कर रहे हैं, वह उचित क्यों नहीं है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रामस्वरूप चाहते हैं कि उमा चेहरे पर पाउडर लगाकर सजे-सँवरे, सिर झुकाकर दबी आवाज में बात करे, गाना गाकर और अपनी सिलाई-कढ़ाई दिखाकर लड़के वालों को रिझाए, तथा अपनी उच्च शिक्षा को पूरी तरह छिपा ले।</p>\n<p>यह अपेक्षा सर्वथा <strong>अनुचित और स्त्री-गरिमा के विरुद्ध</strong> है क्योंकि:</p>\n<ul>\n  <li>लड़की कोई बाजार में बिकने वाली निर्जीव वस्तु या 'भेड़-बकरी' नहीं है जिसे ग्राहक के सामने सजाकर पेश किया जाए।</li>\n  <li>स्त्री भी एक स्वतंत्र व्यक्तित्व, आत्मसम्मान और भावनाओं से युक्त मनुष्य है। विवाह दो आत्माओं और समान विचारों का पवित्र बंधन है, न कि झूठे दिखावे और चाटुकारिता पर आधारित कोई सौदा।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सजने-संवरने और झूठ बोलने की अनुचित अपेक्षा का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्त्री के आत्मसम्मान, व्यक्तित्व और वस्तु मानने के विरोध का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch16-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">गोपाल प्रसाद विवाह को 'बिजनेस' मानते हैं और रामस्वरूप अपनी बेटी की उच्च शिक्षा छिपाते हैं। क्या आप मानते हैं कि दोनों ही समान रूप से दोषी हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>हाँ, नैतिक दृष्टि से दोनों ही दोषी हैं, परंतु दोनों के अपराध की प्रकृति और नीयत में बड़ा अंतर है:</p>\n<ul>\n  <li><strong>गोपाल प्रसाद अधिक दोषी हैं:</strong> वे पेशे से वकील और संपन्न होकर भी विवाह को शुद्ध 'व्यापार' (बिजनेस) मानते हैं। वे बहू को केवल घर की दासी और कम पढ़ी-लिखी रखना चाहते हैं ताकि उनका पुरुषवादी वर्चस्व बना रहे। उनका दृष्टिकोण घोर स्वार्थी, अहंकारी और दकियानूसी है।</li>\n  <li><strong>रामस्वरूप विवशतावश दोषी हैं:</strong> उन्होंने बेटी को पढ़ाया-लिखाया, परंतु समाज की संकीर्णता और बेटी के हाथ पीले करने की सामाजिक चिंता के कारण वे कायर बनकर झूठ का सहारा लेते हैं। उनका अपराध समाज के दबाव से उत्पन्न विवशता है, फिर भी झूठ बोलना अनुचित है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गोपाल प्रसाद के व्यापारिक दृष्टिकोण और दकियानूसी सोच का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रामस्वरूप की सामाजिक विवशता और कायरतापूर्ण झूठ का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch16-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">‘...आपके लाड़ले बेटे की रीढ़ की हड्डी भी है या नहीं...’ — उमा इस कथन के माध्यम से शंकर की किन कमियों की ओर संकेत करना चाहती है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>उमा जब अपने आत्मसम्मान पर प्रहार होते देखती है, तो वह निडर होकर गोपाल प्रसाद से यह बात कहती है। इसके माध्यम से वह शंकर की निम्नलिखित गंभीर कमियों को उजागर करती है:</p>\n<ol>\n  <li><strong>शारीरिक दुर्बलता एवं झुककर चलना:</strong> शंकर शारीरिक रूप से कमजोर है, वह सीधा तनकर खड़ा भी नहीं हो सकता और कूबड़ निकाले झुककर चलता है।</li>\n  <li><strong>चरित्रहीनता एवं अनैतिकता:</strong> वह पिछले साल मेडिकल कॉलेज के पास लड़कियों के हॉस्टल के चक्कर काटते हुए पकड़ा गया था और जूते खाकर मुँह छिपाकर भागा था। उसका नैतिक चरित्र अत्यंत भ्रष्ट और कलंकित है।</li>\n  <li><strong>आत्मविश्वास और रीढ़ (स्वतंत्र व्यक्तित्व) का अभाव:</strong> शंकर की अपनी कोई सोच, निर्णय लेने की क्षमता या व्यक्तित्व नहीं है। वह पूरी तरह अपने रूढ़िवादी पिता के इशारों पर कठपुतली की तरह 'खीं-खीं' करके हँसने वाला एक कायर और रीढ़हीन युवक है।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शारीरिक कमजोरी (झुककर चलना) का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हॉस्टल के प्रसंग द्वारा अनैतिक चरित्र का भंडाफोड़</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'रीढ़ की हड्डी' के लाक्षणिक अर्थ (व्यक्तित्व/स्वाभिमान का अभाव) की व्याख्या</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रभावशाली भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch16-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">शंकर जैसे लड़के या उमा जैसी लड़की — समाज को कैसे व्यक्तित्व की आवश्यकता है? तर्क सहित उत्तर दीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>आज के प्रगतिशील और आधुनिक समाज को <strong>उमा जैसे साहसी, सुशिक्षित और स्वाभिमानी व्यक्तित्व की नितांत आवश्यकता है</strong>, न कि शंकर जैसे रीढ़हीन और चरित्रहीन युवकों की।</p>\n<p><strong>तर्क:</strong></p>\n<ul>\n  <li>उमा उच्च शिक्षित है, कला और संगीत में दक्ष है तथा अन्याय और अपमान के विरुद्ध निडरता से सच बोलने का साहस रखती है। ऐसे ही साहसी युवा समाज को कुप्रथाओं और दहेज के दानव से मुक्त करा सकते हैं।</li>\n  <li>इसके विपरीत, शंकर जैसे व्यक्तित्वहीन, कायर और चरित्रहीन लोग समाज पर बोझ होते हैं जो केवल रूढ़ियों को बढ़ावा देते हैं और देश को पीछे धकेलते हैं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उमा जैसे शिक्षित व स्वाभिमानी व्यक्तित्व का पक्ष</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शंकर जैसे रीढ़हीन युवकों की सामाजिक निरर्थकता का तर्क</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch16-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch16-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">‘रीढ़ की हड्डी’ शीर्षक की सार्थकता स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>प्रस्तुत एकांकी का शीर्षक 'रीढ़ की हड्डी' अत्यंत सटीक, व्यंग्यात्मक, अर्थपूर्ण और प्रतीकात्मक है:</p>\n<ul>\n  <li><strong>शारीरिक दृष्टिकोण:</strong> जिस प्रकार रीढ़ की हड्डी के बिना मानव शरीर सीधा खड़ा नहीं हो सकता, उसी प्रकार शंकर शारीरिक रूप से रीढ़हीन है और झुककर चलता है।</li>\n  <li><strong>नैतिक एवं सामाजिक दृष्टिकोण:</strong> यहाँ 'रीढ़ की हड्डी' मनुष्य के <strong>स्वाभिमान, चरित्र, नैतिकता और स्वतंत्र व्यक्तित्व</strong> का प्रतीक है। शंकर चरित्र और विचारों से रीढ़हीन है, तथा गोपाल प्रसाद और रामस्वरूप जैसे लोग भी पुरानी रूढ़ियों के आगे झुककर अपनी सामाजिक रीढ़ गँवा चुके हैं। केवल उमा ही इस नाटक में रीढ़ वाली (स्वाभिमानी) पात्र है। अतः यह शीर्षक पूर्णतः सार्थक है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शारीरिक अर्थ (शंकर का झुककर चलना) का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नैतिक/प्रतीकात्मक अर्थ (चरित्र, स्वाभिमान, स्वतंत्र चिंतन की कमी) का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीर्षक की सार्थकता का तार्किक निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 16</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">विवाह के समय कन्या-पक्ष को हीन और वर-पक्ष को श्रेष्ठ मानने की मानसिकता समाज के विकास में किस प्रकार बाधक है? इसे दूर करने के उपाय सुझाइए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>हमारे समाज में विवाह के समय लड़के वालों को 'ग्राहक' या 'मालिक' और लड़की वालों को 'याचक' समझा जाता है। यह सामंती और दकियानूसी मानसिकता स्त्री-पुरुष समानता के मूल सिद्धांत पर कुठाराघात करती है। इसी से दहेज-प्रथा, घरेलू हिंसा और कन्या-भ्रूण हत्या जैसी कुरीतियाँ जन्म लेती हैं।</p><p>इसे दूर करने के लिए बेटियों को आत्मनिर्भर और शिक्षित बनाना होगा। विवाह को दो परिवारों का समान सम्मान का रिश्ता समझा जाए। जब तक युवा स्वयं आगे आकर दहेज और इस असमान व्यवहार का विरोध नहीं करेंगे, तब तक समाज का वास्तविक विकास संभव नहीं है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">उमा का आक्रोश तत्कालीन और वर्तमान समाज की शिक्षित युवतियों के किस मौन विद्रोह को वाणी देता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>उमा का यह कहना कि—'क्या हम बेजुबान भेड़-बकरियाँ हैं जिन्हें मेज-कुर्सी की तरह मोल-भाव करके खरीदा जाए?' समाज की हर उस पढ़ी-लिखी लड़की का आक्रोश है जिसे अपनी योग्यता साबित करने के लिए रूढ़ियों के सामने झुकना पड़ता है।</p><p>उमा का यह विद्रोह यह संदेश देता है कि शिक्षा केवल डिग्री पाने के लिए नहीं है, वह मनुष्य को स्वाभिमान से सिर उठाकर जीना सिखाती है। उमा ने उस पाखंडी व्यवस्था के चेहरे से नकाब उतार दिया जो महिलाओं की शिक्षा को अपराध और उनकी स्वाधीनता को खतरा मानती है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(15)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(17)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "17": "<section class=\"chapter-section\" id=\"ch17\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">17</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (गद्य खंड)</div>\n      <h2>दुःख का अधिकार</h2>\n      <p>यशपाल | गद्य खंड (कहानी) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch17-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">किसी व्यक्ति की पोशाक को देखकर हमें क्या अधिकार और सहूलियतें मिलती हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>समाज में किसी व्यक्ति की पोशाक (वस्त्र) देखकर ही लोग उसकी सामाजिक, आर्थिक और बौद्धिक हैसियत का अनुमान लगाते हैं:</p>\n<ul>\n  <li><strong>विशेषाधिकार और सम्मान:</strong> अच्छी, आकर्षक और भद्र पोशाक पहनने वाले व्यक्ति के लिए समाज के बंद दरवाजे स्वतः खुल जाते हैं। उसे हर जगह आदर, विशेषाधिकार और प्राथमिकता मिलती है।</li>\n  <li><strong>श्रेणी निर्धारण:</strong> पोशाक ही समाज में मनुष्य का दर्जा और श्रेणी तय करती है। लोग व्यक्ति के आंतरिक गुणों के बजाय उसके बाह्य परिधान से उसके साथ व्यवहार तय करते हैं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पोशाक द्वारा सामाजिक/आर्थिक श्रेणी निर्धारण का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सम्मान, विशेषाधिकार और बंद दरवाजे खुलने की सुविधा का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch17-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">पोशाक हमारे लिए कब बंधन और अड़चन बन जाती है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>जब हम अपने से नीचे की श्रेणी या समाज के अत्यंत दीन-हीन, गरीब और पीड़ित व्यक्तियों के साथ सहानुभूति प्रकट करना चाहते हैं या उनके दुख-दर्द में सहभागी बनना चाहते हैं, तब हमारी <strong>भद्र और संभ्रांत पोशाक हमारे लिए अड़चन बन जाती है</strong>।</p>\n<p>जिस प्रकार वायु की लहरें कटी हुई पतंग को एकदम नीचे गिरने से रोकती हैं, उसी प्रकार हमारी प्रतिष्ठा वाली पोशाक हमें झुककर गरीब के आँसू पोंछने या जमीन पर बैठकर उससे बात करने से रोक देती है। हम अपनी झूठी सामाजिक प्रतिष्ठा के कैदी बनकर रह जाते हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">निचले वर्ग के दुख में सहभागी बनने में पोशाक की बाधा</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कटी पतंग के दृष्टांत और झूठी प्रतिष्ठा के बंधन का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch17-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लड़के की मृत्यु के अगले ही दिन बुढ़िया खरबूजे बेचने बाजार क्यों आ गई?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बुढ़िया का जवान बेटा भगवाना खेत में खरबूजे तोड़ते समय साँप के डसने से मर गया था। उसके कफ़न-दफ़न और ओझा की झाड़-फूँक में घर का सारा अन्न और बचा-खुचा पैसा समाप्त हो चुका था।</p>\n<p>अगले ही दिन घर में भगवाना के छोटे-छोटे अनाथ बच्चे भूख से बिलख रहे थे और उसकी बीमार बहू को तेज बुखार था जिसके इलाज के लिए एक पैसा भी नहीं था। उस बेबस बुढ़िया के सामने <strong>भूख और मौत का नंगा नाच</strong> हो रहा था। अपने भूखे पोते-पोतियों की जान बचाने के लिए वह कलेजे पर पत्थर रखकर, सूतक के नियमों को तोड़कर, रोते हुए बाजार में खरबूजे बेचने को विवश हो गई।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बेटे की मृत्यु और कफन-दफन में सब कुछ लुट जाने की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूख से बिलखते पोते-पोतियों और बीमार बहू की जान बचाने की विवशता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं संवेदना</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch17-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">बुढ़िया के दुख को देखकर लेखक के मन में अपने पड़ोस की संभ्रांत महिला की याद क्यों आई?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>बुढ़िया को फुटपाथ पर सिर घुटनों में छिपाकर फफक-फफक कर रोते देखकर लेखक को अपने पड़ोस की एक धनी और संभ्रांत महिला की याद आ गई, जिसका जवान बेटा भी पिछले वर्ष मरा था।</p>\n<p><strong>तुलना का कारण (सामाजिक विषमता):</strong></p>\n<ul>\n  <li><strong>संभ्रांत महिला का दुख:</strong> उसके पास दुख मनाने का पूरा अधिकार और साधन थे। वह ढाई महीने तक बिस्तर पर अचेत पड़ी रही, दो-दो डॉक्टर सिरहाने बैठे रहते थे, बर्फ माथे पर रखी जाती थी और पूरा शहर उसके दुख में दुखी होकर सहानुभूति जता रहा था।</li>\n  <li><strong>बुढ़िया का दुख:</strong> बुढ़िया का दुख भी उतना ही गहरा था, परंतु उसके पास दुख मनाने की सहूलियत (अधिकार) नहीं थी। गरीबी के कारण उसे बेटे की लाश ठंडी होते ही बाजार में बैठना पड़ा, जहाँ लोग उस पर पत्थर और ताने मार रहे थे। इस तुलना से लेखक ने समाज के क्रूर वर्ग-विभेद को उजागर किया।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पड़ोस की संभ्रांत महिला के पुत्र-शोक और सुविधाओं का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बुढ़िया के पुत्र-शोक और आजीविका की क्रूर विवशता की तुलना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुख मनाने के अधिकार के वर्ग-विभेद का उद्घाटन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch17-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch17-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">‘दुःख का अधिकार’ शीर्षक की सार्थकता स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>प्रस्तुत कहानी का शीर्षक 'दुःख का अधिकार' अत्यंत व्यंग्यात्मक, मर्मस्पर्शी और पूर्णतः सार्थक है:</p>\n<p>कहानी यह कड़वा सच उजागर करती है कि प्रकृति ने दुख, पीड़ा और आँसू सभी मनुष्यों को समान दिए हैं, परंतु हमारे इस विषमतावादी समाज में <strong>'दुख मनाने का अधिकार' भी केवल धनवानों को ही प्राप्त है।</strong> एक अमीर व्यक्ति अपने स्वजन की मृत्यु पर महीनों विलाप कर सकता है, परंतु एक निर्धन व्यक्ति के लिए रोना और शोक मनाना भी अपराध बन जाता है क्योंकि उसे अगले ही पल रोटी के लिए संघर्ष करना पड़ता है। यह शीर्षक समाज की क्रूर संवेदनहीनता पर तीखा प्रहार करता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुख की स्वाभाविक मानवीय समानता का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अमीर बनाम गरीब के दुख मनाने की विवशता पर व्यंग्य का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शीर्षक की सार्थकता का तार्किक निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 17</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">किसी असहाय व्यक्ति की स्थिति जाने बिना उस पर टिप्पणी करना या उसका उपहास उड़ाना कहाँ तक उचित है? पाठ के आधार पर अपने विचार लिखिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>बाजार के लोग बुढ़िया के बेटे की मृत्यु का सच और उसकी भुखमरी की लाचारी जाने बिना उस पर फब्तियाँ कस रहे थे कि—'कैसी बेहया है, बेटे को मरे एक दिन नहीं हुआ और दुकान लगा ली।' यह समाज की घोर संवेदनहीनता और क्रूरता है।</p><p>हमें किसी के बाह्य आचरण को देखकर तुरंत राय नहीं बनानी चाहिए, बल्कि उसके पीछे छिपे दर्द, विवशता और परिस्थितियों को समझने का प्रयास करना चाहिए। परदुखकातरता, सहानुभूति और दूसरों के कष्ट में सहायता का हाथ बढ़ाना ही सच्चा मानवीय धर्म है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">यशपाल की यह कहानी आर्थिक असमानता के साथ-साथ अंधविश्वास (सूतक प्रथा) पर भी किस प्रकार प्रहार करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कहानी में लोग बुढ़िया से खरबूजे इसलिए नहीं खरीद रहे थे क्योंकि उसके घर में 'सूतक' लगा था और उनका धर्म भ्रष्ट हो जाता। लोग एक भूखे परिवार को रोटी देने के बजाय रूढ़िवादी धार्मिक नियमों को बड़ा मान रहे थे।</p><p>यशपाल जी ने दिखाया कि जब पेट की भूख और जान बचाने का सवाल हो, तो ऐसे पाखंडी नियम अमानवीय बन जाते हैं। सच्चा धर्म मानवता की रक्षा करना है, न कि अंधविश्वासों के नाम पर असहायों को भूखा मारना।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(16)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(18)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "18": "<section class=\"chapter-section\" id=\"ch18\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">18</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (गद्य खंड)</div>\n      <h2>एवरेस्ट : मेरी शिखर यात्रा</h2>\n      <p>बचेंद्री पाल | गद्य खंड (आत्मकथात्मक यात्रा-वृत्तांत) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch18-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">नम्छे बाज़ार पहुँचकर लेखिका ने क्या देखा और स्थानीय शेरपा लोग एवरेस्ट को क्या नाम देते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>नम्छे बाज़ार शेरपालैंड का एक अत्यंत महत्वपूर्ण नगरीय क्षेत्र है। यहाँ पहुँचकर लेखिका बचेंद्री पाल ने पहली बार <strong>एवरेस्ट पर्वत (शिखर)</strong> को निहारा, जो उनके ठीक सामने बादलों के बीच अपनी अलौकिक ऊँचाई के साथ खड़ा था।</p>\n<p>लेखिका ने देखा कि एवरेस्ट के शिखर पर तेज बर्फीली हवाओं (150 किमी/घंटा या उससे अधिक) के कारण एक विशाल बर्फीला ध्वज (प्लूम) लहरा रहा था, जो दस किलोमीटर से भी अधिक लंबा था। स्थानीय नेपाली और शेरपा लोग एवरेस्ट को <strong>'सागरमाथा'</strong> (स्वर्ग का भाल / माथा) नाम से पुकारते हैं, और लेखिका को यह नाम अत्यंत सुंदर लगा।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नम्छे बाज़ार में एवरेस्ट को पहली बार देखने का विवरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिखर पर विशाल बर्फीले प्लूम (ध्वज) के दृश्य का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">'सागरमाथा' नाम और उसके सौंदर्य की स्पष्टता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch18-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">हिमपात किस तरह होता है और उससे क्या-क्या भयानक परिवर्तन आते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>पर्वतीय क्षेत्रों में हिमपात (बर्फ गिरना) अपने आप में बर्फ के खण्डों का अव्यवस्थित ढंग से गिरना होता है। ग्लेशियर के बहने से बर्फ में अचानक बड़ी-बड़ी गहरी दरारें (क्रेवास) पड़ जाती हैं और बर्फ की विशाल चट्टानें तत्काल गिर पड़ती हैं।</p>\n<p><strong>भयानक परिवर्तन:</strong></p>\n<ul>\n  <li>रास्ते रातों-रात पूरी तरह नष्ट हो जाते हैं और नए खतरनाक मार्ग बन जाते हैं।</li>\n  <li>अचानक भारी बर्फ खिसकने से हिम-स्खलन (Avalanche) होता है जिसमें पर्वतारोही दब जाते हैं, जैसा कि खंभू हिमपात पर हुआ था जहाँ एक शेरपा कुली की मौत हो गई थी और कई घायल हो गए थे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हिमपात और ग्लेशियर खिसकने की प्रक्रिया का वैज्ञानिक स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दरारें पड़ने, रास्ते बदलने और हिम-स्खलन के जानलेवा खतरों का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch18-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कैंप-3 में लेखिका के साथ क्या भयानक दुर्घटना घटी और उनकी जान कैसे बची?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>15-16 मई 1984 की रात को कैंप-3 (ल्होत्से की बर्फीली सीधी ढलान पर) लेखिका अपने तंबू में गहरी नींद में सो रही थीं।</p>\n<p><strong>दुर्घटना:</strong> रात को लगभग 12:30 बजे अचानक एक बहुत भारी और कठोर बर्फीला पिंड (लौत्से ग्लेशियर से टूटा हिमखंड) उनके तंबू पर अत्यंत प्रचंड वेग से आ गिरा। तंबू पल भर में तहस-नहस हो गया और लेखिका पूरी तरह उस भारी बर्फ की कब्र में जिंदा दब गईं। उनकी साँसें रुकने ही वाली थीं।</p>\n<p><strong>जान कैसे बची:</strong> उनके साथी 'लोपसांग' ने अपनी स्विस छुरी से तेजी से तंबू के कपड़े को चीरा और लेखिका के चारों ओर जमी कठोर बर्फ की सिल्लियों को अपनी कुल्हाड़ी से काटकर हटाया। उन्होंने बड़ी मुश्किल से लेखिका को उस बर्फ की कब्र से खींचकर बाहर निकाला और इस प्रकार लेखिका को नया जीवन मिला।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ल्होत्से ग्लेशियर से विशाल हिमखंड गिरने और बर्फ में दबने की दुर्घटना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लोपसांग द्वारा स्विस छुरी और कुल्हाड़ी से बर्फ काटकर बचाने की वीरता</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता एवं प्रवाह</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch18-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch18-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">एवरेस्ट के शिखर पर पहुँचकर लेखिका ने क्या-क्या किया?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>23 मई 1984 को दोपहर 1:07 बजे बचेंद्री पाल ने एवरेस्ट के सर्वोच्च शिखर पर अपने कदम रखे। वे एवरेस्ट पर चढ़ने वाली प्रथम भारतीय महिला बनीं। शिखर पर पहुँचकर उन्होंने निम्नलिखित कार्य किए:</p>\n<ol>\n  <li><strong>सुरक्षा का प्रबंध:</strong> चोटी बहुत संकरी और दोनों ओर हजारों मीटर गहरी ढलान थी। उन्होंने बर्फ की कुल्हाड़ी को सुरक्षा के लिए बर्फ में गहराई से गाड़ा।</li>\n  <li><strong>मातृभूमि व ईश्वर को नमन:</strong> वे घुटनों के बल बैठीं, सागरमाथा के ताज का चुंबन लिया और ईश्वर के प्रति कृतज्ञता व्यक्त की।</li>\n  <li><strong>हनुमान चालीसा व दुर्गा माँ का चित्र:</strong> उन्होंने अपने थैले से हनुमान चालीसा और माँ दुर्गा का चित्र निकाला, उनकी संक्षिप्त पूजा की और उन्हें बर्फ में दबा दिया।</li>\n  <li><strong>अंगदोरजी का आभार एवं राष्ट्रीय ध्वज:</strong> उन्होंने अपने दल के नेता अंगदोरजी को गले लगाकर धन्यवाद दिया तथा भारत का तिरंगा गर्व से लहराया।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शिखर पर पहुँचने का समय (23 मई 1:07 दोपहर) और सुरक्षा व्यवस्था</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सागरमाथा के चुंबन और नमन की भावनात्मक क्रिया</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">हनुमान चालीसा, दुर्गा चित्र बर्फ में रखने एवं तिरंगा लहराने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 18</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">बचेंद्री पाल की यह सफलता भारत की नारी शक्ति और संकल्प के किस विराट रूप को दर्शाती है? आज की छात्राओं के लिए उनका जीवन क्या प्रेरणा देता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>एक साधारण ग्रामीण परिवार से निकलकर दुनिया के सबसे ऊँचे और दुर्गम पर्वत शिखर को फतह करना यह साबित करता है कि यदि मन में दृढ़ इच्छाशक्ति, अदम्य साहस और लक्ष्य के प्रति समर्पण हो, तो कोई भी बाधा नारी को रोक नहीं सकती।</p><p>यह पाठ आज की छात्राओं को रूढ़ियों की जंजीरें तोड़ने, जोखिम लेने और आत्मविश्वास के साथ अपने सपनों को सच करने की प्रेरणा देता है। असफलता और मृत्यु के भय को पार करके ही इतिहास रचा जाता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">बचेंद्री पाल द्वारा अपने साथी पर्वतारोहियों (की, जय आदि) के लिए नीचे उतरकर चाय और जूस ले जाने की घटना उनके किस मानवीय गुण को उजागर करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>शिखर की ओर बढ़ते हुए जब लेखिका अपने साथियों से आगे थीं, तब वे अपनी सफलता की परवाह न करके भारी बर्फ में नीचे उतरीं और अपने साथियों को गर्म चाय व जूस पिलाया।</p><p>यह घटना उनके 'टीम स्पिरिट' (सामूहिक भावना), निस्वार्थ सेवा, सहृदयता और सहकर्मियों के प्रति गहरी संवेदनशीलता को प्रकट करती है। एक सच्चा लीडर वही होता है जो केवल अपनी जीत नहीं देखता, बल्कि अपनी पूरी टीम का संबल बनता है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(17)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(19)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "19": "<section class=\"chapter-section\" id=\"ch19\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">19</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (गद्य खंड)</div>\n      <h2>तुम कब जाओगे, अतिथि</h2>\n      <p>शरद जोशी | गद्य खंड (व्यंग्य) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch19-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">चार दिनों से लेखक के घर अतिथि के टिके रहने पर आतिथ्य-सत्कार में क्या-क्या बदलाव आए?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>अतिथि के अत्यधिक लंबे प्रवास के कारण लेखक के घर के आतिथ्य-सत्कार में निम्नलिखित क्रमिक गिरावट आई:</p>\n<ul>\n  <li><strong>पहले दिन:</strong> अतिथि का भव्य स्वागत हुआ, आलिंगन किया गया और रात्रिभोज में दो-दो सब्जियों के साथ सिनेमा (फिल्म) दिखाई गई।</li>\n  <li><strong>दूसरे दिन:</strong> दोपहर को लंच गरिमामय रहा और रात को डिनर को मध्यमवर्गीय स्तर से ऊँचा रखा गया।</li>\n  <li><strong>तीसरे-चौथे दिन:</strong> सत्कार की ऊष्मा समाप्त हो गई। गरिष्ठ भोजन खिचड़ी और दलिया में बदल गया, मुस्कुराहटें गायब हो गईं, बातचीत की जगह चुप्पी ने ले ली और लेखक की पत्नी की आँखों में उपवास और खीझ तैरने लगी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पहले दिन के उत्साह, सिनेमा व गरिष्ठ भोजन का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दिन बीतने के साथ खिचड़ी, चुप्पी और सत्कार की ऊष्मा के बुझने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं व्यंग्य</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch19-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">‘संबंधों का संक्रमण के दौर से गुजरना’ — इस कथन से लेखक का क्या तात्पर्य है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'संक्रमण' उस स्थिति को कहते हैं जहाँ एक पुरानी अवस्था समाप्त हो रही हो और नई अवस्था का रूप स्पष्ट न हो।</p>\n<p>लेखक के घर आए अतिथि के संदर्भ में इसका तात्पर्य यह है कि अतिथि और मेजबान के बीच जो आत्मीयता, प्रेम, आदर और उत्साह पहले दिन था, वह चार दिन बीतते-बीतते समाप्त हो गया। अब उन दोनों के बीच न तो प्रेम बचा था और न ही कोई नया विषय बातचीत के लिए। संबंध अब प्रेम से बदलकर बोरियत, कटुता, तनाव और मौन घृणा में तब्दील हो रहे थे।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संक्रमण का अर्थ और संबंधों में बदलाव का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उत्साह व प्रेम का बोरियत व कटुता में बदलने का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch19-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch19-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">लेखक ने अतिथि को 'देवता' और 'राक्षस' के संदर्भ में किस प्रकार प्रस्तुत किया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>भारतीय परंपरा में कहा जाता है कि <em>'अतिथि देवो भव'</em> (अतिथि देवता के समान होता है)।</p>\n<p>लेखक व्यंग्य करते हैं कि देवता की सबसे बड़ी विशेषता यह होती है कि वह कुछ क्षणों के लिए दर्शन देता है और आशीर्वाद देकर तुरंत अंतर्धान (गायब) हो जाता है। परंतु जो अतिथि चार-चार दिन तक खूँटा गाड़कर बैठ जाए, धोबी से कपड़े धुलवाए और जाने का नाम न ले, उसका देवत्व समाप्त हो जाता है और वह एक शोषक, संवेदनहीन 'राक्षस' जैसा लगने लगता है जो मेजबान के आर्थिक और मानसिक चैन को निगल जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">देवता के क्षणिक दर्शन और आशीर्वाद देकर विदा होने की विशेषता</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अनावश्यक लंबे ठहराव द्वारा देवत्व के राक्षस में बदलने का व्यंग्य</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 19</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">अतिथि बनकर किसी के घर जाते समय हमें किन शिष्टाचारों और मर्यादाओं का ध्यान रखना चाहिए? पाठ के आलोक में समझाइए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>अतिथि को यह समझना चाहिए कि आधुनिक युग में प्रत्येक परिवार के पास समय, धन और स्थान की सीमाएँ होती हैं। अतः किसी के घर बिना पूर्व सूचना के नहीं जाना चाहिए और न ही अकारण लंबे समय तक ठहरना चाहिए।</p><p>मेजबान की दिनचर्या में बाधा न पहुँचाना, अपने व्यक्तिगत कार्यों का बोझ उन पर न डालना तथा उनके सत्कार का दुरुपयोग न करना ही सच्चे अतिथि का लक्षण है। अपनी मर्यादा बनाए रखकर समय पर विदा ले लेना ही दोनों पक्षों के सम्मान को सुरक्षित रखता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">शरद जोशी के इस व्यंग्य में मध्यमवर्गीय परिवार की किन आर्थिक और सामाजिक विवशताओं का यथार्थ चित्रण हुआ है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>यह व्यंग्य एक आम मध्यमवर्गीय परिवार के उस संकट को दर्शाता है जहाँ बजट सीमित होता है। अतिथि के आने पर बजट बिगड़ जाता है, पत्नी पर गृहकार्य का अतिरिक्त बोझ पड़ता है और दैनिक शांति भंग हो जाती है।</p><p>मध्यमवर्ग मर्यादावश मुँह खोलकर अतिथि को जाने के लिए नहीं कह पाता, परंतु भीतर ही भीतर आर्थिक तंगी और मानसिक तनाव से घुटता रहता है। लेखक ने इस मौन पीड़ा को हास्य-व्यंग्य के माध्यम से अत्यंत मार्मिक रूप में उकेरा है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(18)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(20)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "20": "<section class=\"chapter-section\" id=\"ch20\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">20</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (गद्य खंड)</div>\n      <h2>वैज्ञानिक चेतना के वाहक : चंद्रशेखर वेंकट रामन्</h2>\n      <p>धीरज मालवीय | गद्य खंड (जीवनी) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch20-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">रामन् के मन में समुद्र के नीले रंग को देखकर क्या जिज्ञासा जागी और उन्होंने इसकी क्या व्याख्या की?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>1921 में जब सी.वी. रामन् एक जलपोत (जहाज) से इंग्लैंड से भारत लौट रहे थे, तो भूमध्य सागर के गहरे नीले पानी को देखकर उनके बाल-सुलभ जिज्ञासु मन में यह वैज्ञानिक प्रश्न उठा कि—<strong>'समुद्र के पानी का रंग नीला ही क्यों होता है?'</strong></p>\n<p>उस समय यह माना जाता था कि समुद्र का नीला रंग आकाश के परावर्तन के कारण होता है। परंतु रामन् ने अपने जहाजी सफर में ही 'प्रिज्म' और 'स्पेक्ट्रोस्कोप' की सहायता से प्रयोग कर यह सिद्ध किया कि समुद्र का नीला रंग आकाश के परावर्तन से नहीं, बल्कि जल के अणुओं द्वारा सूर्य के प्रकाश के प्रकीर्णन (Scattering) के कारण होता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भूमध्य सागर के नीले पानी को देखकर जिज्ञासा उठने का प्रसंग</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आकाश के परावर्तन के पुराने सिद्धांत का खंडन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">जल के अणुओं द्वारा प्रकाश के प्रकीर्णन की सही वैज्ञानिक खोज</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch20-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">‘रामन् प्रभाव’ (Raman Effect) क्या है और इसका आधुनिक विज्ञान में क्या महत्व है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>28 फरवरी 1928 को सी.वी. रामन् ने अपनी युगांतरकारी खोज की घोषणा की, जिसे विश्व भर में 'रामन् प्रभाव' के नाम से जाना जाता है:</p>\n<ul>\n  <li><strong>खोज का स्वरूप:</strong> जब एकवर्णीय (सिंगल वेवलेंथ) प्रकाश किसी पारदर्शी माध्यम (ठोस, द्रव या गैस) से होकर गुजरता है, तो प्रकीर्णित प्रकाश की किरणों में मूल प्रकाश की आवृत्ति के अलावा कुछ अन्य आवृत्तियों की किरणें भी उपस्थित होती हैं। ऐसा प्रकाश के फोटॉनों और माध्यम के अणुओं के बीच ऊर्जा के आदान-प्रदान के कारण होता है।</li>\n  <li><strong>महत्व:</strong> रामन् प्रभाव ने अणुओं और परमाणुओं की आंतरिक संरचना को समझने के लिए एक सशक्त 'एक्स-रे' का कार्य किया। इससे किसी भी पदार्थ के रासायनिक संघटन को बिना तोड़े-फोड़े जाना जा सकता है। इस खोज के लिए उन्हें 1930 में भौतिकी का प्रतिष्ठित 'नोबेल पुरस्कार' प्रदान किया गया।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एकवर्णीय प्रकाश और प्रकीर्णन में आवृत्ति परिवर्तन का स्पष्टीकरण</span><span class=\"marking-marks\">2.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अणुओं की आंतरिक संरचना की पहचान में उपयोगिता का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नोबेल पुरस्कार एवं 28 फरवरी (राष्ट्रीय विज्ञान दिवस) का संदर्भ</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch20-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch20-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">सरकारी नौकरी छोड़कर रामन् ने कलकत्ता विश्वविद्यालय में प्रोफेसर का पद क्यों स्वीकार किया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>सी.वी. रामन् भारत सरकार के वित्त विभाग में 'डिप्टी एकाउंटेंट जनरल' के पद पर अत्यंत उच्च वेतन, सरकारी सुख-सुविधाओं और प्रतिष्ठा के साथ कार्यरत थे।</p>\n<p>परंतु उनका सच्चा अनुराग केवल और केवल <strong>वैज्ञानिक अनुसंधान और भौतिक विज्ञान की साधना</strong> में था। जब आशुतोष मुखर्जी ने उन्हें कलकत्ता विश्वविद्यालय में भौतिकी के 'पालित प्रोफेसर' पद का प्रस्ताव दिया (जिसमें सरकारी नौकरी की तुलना में वेतन बहुत कम था), तो उन्होंने धन और विलासिता को ठोकर मारकर विज्ञान के लिए अपना जीवन समर्पित कर दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उच्च वेतन एवं वित्त विभाग की प्रतिष्ठित नौकरी का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">विज्ञान साधना के प्रति निष्ठा एवं कम वेतन पर भी विश्वविद्यालय पद स्वीकारना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 20</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">साधनों के अभाव में भी सी.वी. रामन् ने जो विश्वस्तरीय वैज्ञानिक खोजें कीं, उससे आज के भारतीय छात्रों को क्या सीख मिलती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>रामन् ने जब अपनी ऐतिहासिक खोजें कीं, तब भारत में आधुनिक प्रयोगशालाएँ या महंगे उपकरण नहीं थे। उन्होंने अत्यंत सस्ते, देशी और साधारण उपकरणों (मात्र 200-300 रुपये के सामान) से नोबेल पुरस्कार स्तर का अनुसंधान कर दिखाया।</p><p>यह पाठ छात्रों को सिखाता है कि महान वैज्ञानिक उपलब्धियों के लिए महंगे संसाधनों से अधिक महत्वपूर्ण 'अदम्य लगन, सूक्ष्म दृष्टि और अटूट जिज्ञासा' होती है। कठिनाइयों का रोना रोने के बजाय अपनी बुद्धि और संकल्प से समस्याओं का समाधान खोजना ही सच्ची वैज्ञानिक चेतना है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">भारतीय संगीत वाद्यों (मृदंगम, तबला, वीणा) पर रामन् के शोध ने पश्चिमी वैज्ञानिकों की किस भ्रांति को तोड़ा?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>पश्चिमी वैज्ञानिकों का मानना था कि भारतीय वाद्ययंत्र (तबला, मृदंगम आदि) पाश्चात्य वाद्यों (वायलिन, पियानो) की तुलना में वैज्ञानिक रूप से अविकसित और बेसुरा ध्वनि उत्पन्न करने वाले हैं।</p><p>रामन् ने ध्वनिकी (Acoustics) पर गहन प्रयोग कर यह वैज्ञानिक रूप से सिद्ध किया कि भारतीय वाद्यों की बनावट, चमड़े का खिंचाव और स्याही का लेप अद्भुत संवादी आवृत्तियाँ (Harmonics) पैदा करता है जो अत्यंत सुरीली और अद्वितीय होती हैं। उन्होंने भारतीय वाद्य-कला की वैज्ञानिक श्रेष्ठता को विश्व स्तर पर प्रमाणित किया।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(19)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(21)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "21": "<section class=\"chapter-section\" id=\"ch21\" data-book=\"sparsh-gadh\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">21</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (गद्य खंड)</div>\n      <h2>शुक्रतारे के समान</h2>\n      <p>स्वामी आनंद | गद्य खंड (संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch21-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">महादेव भाई देसाई के व्यक्तित्व की तुलना 'शुक्रतारे' से क्यों की गई है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>आकाश में शुक्रतारा भोर के समय अपनी अद्वितीय आभा और उज्ज्वलता के साथ चमकता है, परंतु उसका जीवन-काल बहुत संक्षिप्त होता है; वह थोड़ी देर में ही अस्त हो जाता है।</p>\n<p>उसी प्रकार महादेव भाई देसाई ने भारत के स्वतंत्रता संग्राम के क्षितिज पर गांधीजी के निजी सचिव के रूप में अपनी असाधारण प्रतिभा, विद्वत्ता, विनम्रता और कर्मठता की ऐसी दिव्य चमक बिखेरी कि सब विस्मित रह गए। परंतु मात्र 50 वर्ष की अल्पायु में ही अत्यधिक कार्यभार और देश-सेवा के कारण उनका आकस्मिक निधन हो गया। उनके इस तेजपूर्ण किंतु संक्षिप्त जीवन के कारण ही लेखक ने उन्हें 'शुक्रतारे के समान' कहा है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुक्रतारे की उज्ज्वलता एवं संक्षिप्त जीवन-काल का रूपक</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महादेव भाई की अद्वितीय प्रतिभा, कर्मठता और अल्पायु में निधन का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch21-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch21-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">महादेव भाई की लिखावट (हैंडराइटिंग) की क्या विशेषता थी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेव भाई देसाई की लिखावट अत्यंत सुंदर, मोती जैसी सुडौल और कलात्मक थी। उनकी लिखावट की विशेषताएँ निम्नलिखित थीं:</p>\n<ul>\n  <li>वे तेज गति से लिखवाए गए भाषणों को भी शॉर्टहैंड के बिना पूरी शुद्धता से पूर्ण वाक्यों में लिख लेते थे।</li>\n  <li>उनके अक्षरों में कहीं कोई काँट-छाँट नहीं होती थी। अक्षर इतने साफ और स्पष्ट होते थे कि मानो मोतियों की लड़ी पिरो दी गई हो। तत्कालीन वायसराय और ब्रिटिश अधिकारी भी उनके सुंदर हस्तलेख को देखकर दाँतों तले उँगली दबा लेते थे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोती जैसे सुडौल, सुंदर और बिना काँट-छाँट के अक्षरों का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">द्रुत गति से लिखने की क्षमता और वायसराय द्वारा प्रशंसा का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 21</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">महादेव भाई देसाई का गांधीजी के प्रति निष्काम समर्पण आज के युवाओं को कर्तव्यनिष्ठा का क्या संदेश देता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>महादेव भाई ने अपनी व्यक्तिगत महत्वाकांक्षाओं और स्वास्थ्य की बलि देकर दिन-रात गांधीजी के विचारों और देश की आजादी के लिए काम किया। वे कभी श्रेय या पद के पीछे नहीं भागे; उन्होंने हमेशा पर्दे के पीछे रहकर देश की सेवा की।</p><p>उनका जीवन सिखाता है कि सच्ची महानता आत्म-प्रचार में नहीं, बल्कि अपने कर्तव्य के प्रति पूर्ण समर्पण और ईमानदारी में है। यदि हम अपने दायित्व को पूरी निष्ठा से निभाएँ, तो हमारा योगदान भी इतिहास में अमर हो जाता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">महादेव भाई के चले जाने के बाद गांधीजी द्वारा बार-बार 'महादेव' पुकारना उनके बीच के किस आत्मिक संबंध को दर्शाता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आगा खाँ पैलेस में महादेव भाई के आकस्मिक निधन के बाद जब प्यारेलाल जी गांधीजी के सचिव बने, तो गांधीजी कई बार अनजाने में प्यारेलाल को भी 'महादेव' कहकर पुकार बैठते थे।</p><p>यह दर्शाता है कि महादेव भाई केवल एक सचिव नहीं थे, बल्कि वे गांधीजी के 'बाह्य प्राण' और आत्मा के अभिन्न अंग थे। उनका रिश्ता औपचारिक न होकर गहरा आध्यात्मिक, बौद्धिक और आत्मीय था जिसकी शून्यता गांधीजी के जीवन में कभी नहीं भर सकी।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(20)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(22)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "22": "<section class=\"chapter-section\" id=\"ch22\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">22</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (काव्य खंड)</div>\n      <h2>पद</h2>\n      <p>संत रैदास | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">अब कैसे छूटै राम नाम रट लागी।\nप्रभु जी, तुम चंदन हम पानी, जाकी अंग-अंग बास समानी।\nप्रभु जी, तुम घन बन हम मोरा, जैसे चितवत चंद चकोरा।\nप्रभु जी, तुम दीपक हम बाती, जाकी जोति बरै दिन राती।\nप्रभु जी, तुम मोती हम धागा, जैसे सोनहिं मिलत सुहागा।\nप्रभु जी, तुम स्वामी हम दासा, ऐसी भक्ति करै रैदासा।।\n\nऐसी लाल तुझ बिनु कउनु करै।\nगरीब निवाजु गुसईआ मेरा माथै छत्रु धरै।।\nजाकी छोति जगत कउ लागै ता पर तुहीं ढरै।\nनीचहु ऊच करै मेरो गोबिंदु काहू ते न डरै।।\nनामदेव कबीरु तिलोचनु सधना सैनु तरै।\nकहि रविदासु सुनहु रे संतहु हरिजीउ ते सभै सरै।।</div>\n    <div class=\"poet-name\">— संत रैदास (रविदास)</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch22-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">पहले पद में कवि ने अपने और ईश्वर के बीच किन-किन उपमानों से संबंध स्थापित किया है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>संत रैदास ने अपने आराध्य प्रभु के साथ अनन्य और अविभाज्य संबंध को प्रकट करने के लिए निम्नलिखित सुंदर उपमानों का प्रयोग किया है:</p>\n<ol>\n  <li><strong>चंदन और पानी:</strong> प्रभु चंदन के समान सुगंधित हैं और भक्त पानी है। पानी में मिलकर चंदन की सुगंध भक्त के अंग-अंग में समा जाती है।</li>\n  <li><strong>बादल (घन) और मोर:</strong> प्रभु उमड़ते बादलों के समान हैं और भक्त वन में नाचने वाले मोर के समान है जो बादलों को देखकर आनंदमग्न हो उठता है।</li>\n  <li><strong>चाँद और चकोर:</strong> प्रभु चंद्रमा हैं और भक्त चकोर पक्षी है जो रात भर एकटक प्रेम से चाँद को निहारता रहता है।</li>\n  <li><strong>दीपक और बाती:</strong> प्रभु दीपक हैं और भक्त उसकी बाती है, जिसकी ज्योति दिन-रात जलकर संसार को प्रकाश देती है।</li>\n  <li><strong>मोती और धागा:</strong> प्रभु उज्ज्वल मोती हैं और भक्त धागा है जिसमें मोती पिरोए जाते हैं।</li>\n  <li><strong>सोना और सुहागा:</strong> यह मिलन सोने में सुहागा मिलने जैसा है, जिससे सोने की शुद्धता और चमक बढ़ जाती है।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चंदन-पानी, घन-मोर एवं चाँद-चकोर के उपमानों की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दीपक-बाती, मोती-धागा एवं सोना-सुहागा के उपमानों का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दास्य भाव की भक्ति का निष्कर्ष</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch22-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch22-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">दूसरे पद में रैदास ने ईश्वर की कृपा और समभाव का किस प्रकार वर्णन किया है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>दूसरे पद <em>('ऐसी लाल तुझ बिनु कउनु करै...')</em> में रैदास ने ईश्वर को <strong>'गरीब निवाजु' (दीनबंधु)</strong> और परम दयालु बताया है:</p>\n<ul>\n  <li><strong>छुआछूत का खंडन:</strong> जिस तथाकथित अछूत व्यक्ति की छाया पड़ने से भी संसार अपवित्र मानता था, उस पर केवल परमात्मा ही अपनी असीम कृपा बरसाते हैं और उसे अपने मस्तक पर राजाओं जैसा छत्र धारण करा देते हैं।</li>\n  <li><strong>निर्भीक समभाव:</strong> प्रभु किसी समाज या रूढ़ियों से नहीं डरते; वे निम्न जाति में जन्मे व्यक्ति को भी समाज में सर्वोच्च पद और सम्मान दिला देते हैं।</li>\n  <li><strong>संतों के उद्धार का प्रमाण:</strong> रैदास उदाहरण देते हैं कि प्रभु की कृपा से ही नामदेव, कबीर, त्रिलोचन, सधना और सैनु जैसे साधारण व निम्न वर्ग के भक्त संसार-सागर से तर गए और अमर संत बन गए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गरीब निवाजु एवं छत्र धारण कराने की महिमा का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नीचहु ऊच करने और सामाजिक निर्भीकता का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कबीर, नामदेव, सैनु आदि संतों के उद्धार के दृष्टांत</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 22</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">संत रैदास का 'नीचहु ऊच करै मेरो गोबिंदु' का संदेश भारत में सामाजिक समरसता और समानता स्थापित करने में किस प्रकार मार्गदर्शक है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>संत रैदास ने उस युग में सामाजिक समता का शंखनाद किया जब समाज में जाति-पाँति और छुआछूत अपनी चरम सीमा पर थी। उन्होंने स्पष्ट घोषणा की कि जन्म से कोई छोटा या बड़ा नहीं होता। परमात्मा के दरबार में केवल भक्ति, आचरण और प्रेम का मूल्य है।</p><p>यह संदेश आज के समाज में जातिगत भेदभाव को समाप्त करने और प्रत्येक नागरिक को समान गरिमा व अवसर प्रदान करने का सबसे बड़ा नैतिक आधार है। जब ईश्वर समदर्शी हैं, तो मनुष्य को भी समतावादी होना ही चाहिए।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">रैदास की भक्ति भावना में 'दास्य भाव' और 'अद्वैत भाव' का अनूठा समन्वय कैसे दिखाई देता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>एक ओर रैदास कहते हैं—'प्रभु जी तुम स्वामी हम दासा', जो उनकी परम विनम्रता और दास्य भाव (सच्चा सेवक भाव) को प्रकट करता है।</p><p>वहीं दूसरी ओर चंदन-पानी, मोती-धागा और सोना-सुहागा के माध्यम से वे आत्मा और परमात्मा के एकाकार (अद्वैत) हो जाने का निरूपण करते हैं जहाँ भक्त और भगवान में कोई द्वैत या भेद शेष नहीं रह जाता। यह समन्वय रैदास की काव्य-साधना को अद्वितीय ऊँचाई प्रदान करता है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(21)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(23)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "23": "<section class=\"chapter-section\" id=\"ch23\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">23</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (काव्य खंड)</div>\n      <h2>दोहे</h2>\n      <p>रहीम | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">रहिमन धागा प्रेम का, मत तोरो चटकाय।\nटूटे पे फिर ना जुरे, जुरे गाँठ परी जाय।।\nरहिमन निज मन की बिथा, मन ही राखो गोय।\nसुनि अठिलैहैं लोग सब, बाँटि न लैहै कोय।।\nएके साधे सब सधै, सब साधे सब जाय।\nरहिमन मूलहिं सींचिबो, फूलै फलै अघाय।।\nचित्रकूट में रमि रहे, रहिमन अवध-नरेस।\nजा पर बिपदा परत है, सो आवत यह देस।।\nदीरघ दोहा अरथ के, आखर थोरे आहिं।\nज्यों रहीम नट कुंडली, सिमटि कूदि चढ़ि जाहिं।।\nधनि रहीम जल पंक को, लघु जिय पिअत अघाय।\nउदधि बड़ाई कौन है, जगत पिआसो जाय।।\nनाद रीझि तन देत मृग, नर धन हेत समेत।\nते रहीम पसु से अधिक, रीझेहु कछू न देत।।\nबिगरी बात बनै नहीं, लाख करौ किन कोय।\nरहिमन फाटे दूध को, मथे न माखन होय।।\nरहिमन देखि बड़ेन को, लघु न दीजिए डारि।\nजहाँ काम आवै सुई, कहा करै तरवारि।।\nरहिमन पानी राखिए, बिनु पानी सब सून।\nपानी गए न ऊबरै, मोती, मानुष, चून।।</div>\n    <div class=\"poet-name\">— अब्दुर्रहीम खानखाना (रहीम)</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch23-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">‘रहिमन धागा प्रेम का, मत तोरो चटकाय’ — प्रेम के रिश्ते के संदर्भ में कवि क्या सीख देते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रहीम दास जी प्रेम के संबंध की तुलना एक अत्यंत कोमल और नाजुक धागे से करते हैं। वे सीख देते हैं कि प्रेम के रिश्ते को कभी क्रोध, अहंकार या जल्दबाजी में झटके से तोड़ना नहीं चाहिए।</p>\n<p>यदि प्रेम का धागा एक बार टूट जाता है, तो वह दोबारा सहज रूप से नहीं जुड़ता। और यदि बहुत प्रयास करके उसे जोड़ भी दिया जाए, तो उसमें 'गाँठ' पड़ जाती है—अर्थात मन में पहले जैसा सहज विश्वास और मिठास नहीं रहती, कहीं न कहीं अविश्वास और संदेह की टीस बनी रहती है। अतः प्रेम संबंधों की रक्षा बड़ी सावधानी और आदर से करनी चाहिए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">प्रेम की तुलना नाजुक धागे से करने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">टूटने पर न जुड़ने एवं जुड़ने पर गाँठ (अविश्वास) पड़ने की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch23-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">‘बिगरी बात बनै नहीं, लाख करौ किन कोय’ — फटे दूध के उदाहरण से रहीम क्या समझाते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रहीम दास जी समझाते हैं कि जिस प्रकार एक बार दूध फट जाए, तो उसे चाहे कितना भी मथा जाए, उससे कभी मक्खन नहीं निकाला जा सकता; उसी प्रकार यदि कटु वचनों या अनुचित व्यवहार से कोई बात या संबंध एक बार बिगड़ जाए, तो लाख उपाय करने पर भी वह पहले जैसा स्वाभाविक और मधुर नहीं बन पाता।</p>\n<p>अतः मनुष्य को सदैव सोच-समझकर, वाणी पर संयम रखकर और मर्यादा में रहकर व्यवहार करना चाहिए ताकि बात बिगड़ने की नौबत ही न आए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">फटे दूध से मक्खन न बनने के दृष्टांत का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बिगड़ी बात के पुनः न सुधरने और वाणी-संयम की सीख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch23-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">‘धनि रहीम जल पंक को, लघु जिय पिअत अघाय’ — कीचड़ के जल को सागर से श्रेष्ठ क्यों बताया गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रहीम जी ने कीचड़ (पंक) के तुच्छ और गंदले जल को भी अथाह विशाल सागर से अधिक धन्य (श्रेष्ठ) माना है।</p>\n<p><strong>कारण:</strong></p>\n<ul>\n  <li>कीचड़ के जल से छोटे-छोटे जीव-जंतु, कीड़े-मकोड़े और पक्षी अपनी प्यास बुझाकर तृप्त (अघाय) हो जाते हैं। वह दूसरों के काम आता है और जीवन देता है।</li>\n  <li>इसके विपरीत, समुद्र का जल यद्यपि अपार और असीम होता है, किंतु खारा होने के कारण वह किसी की प्यास नहीं बुझा सकता; संसार का सारा जीव-जगत उसके किनारे जाकर भी प्यासा ही लौटता है। रहीम की सीख है कि बड़प्पन आकार या धन में नहीं, बल्कि दूसरों के काम आने (परोपकार) में है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कीचड़ के जल द्वारा छोटे जीवों की प्यास बुझाने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सागर के खारे जल की अनुपयोगिता और परोपकार की महत्ता का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सटीक प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch23-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">‘रहिमन देखि बड़ेन को, लघु न दीजिए डारि’ — सुई और तलवार के उदाहरण से कवि क्या संदेश देते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रहीम जी संदेश देते हैं कि बड़ी, धनी या प्रभावशाली वस्तुओं/व्यक्तियों को देखकर हमें छोटी, साधारण और निर्धन वस्तुओं या लोगों की उपेक्षा नहीं करनी चाहिए।</p>\n<p>संसार में प्रत्येक वस्तु और व्यक्ति का अपना विशिष्ट महत्व और उपयोग होता है। उदाहरण के लिए, जहाँ फटे कपड़े को सीने के लिए छोटी-सी <strong>सुई</strong> काम आती है, वहाँ विशाल और भारी <strong>तलवार</strong> किसी काम नहीं आ सकती। तलवार केवल काट सकती है, जोड़ नहीं सकती। अतः समाज में छोटे से छोटे व्यक्ति का भी सम्मान होना चाहिए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बड़े को देखकर छोटे की उपेक्षा न करने का संदेश</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सुई (जोड़ने) और तलवार (काटने) के विशिष्ट उपयोग की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch23-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch23-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">‘रहिमन पानी राखिए, बिनु पानी सब सून’ — इस दोहे में 'पानी' के तीन अलग-अलग अर्थ स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>रहीम के इस प्रसिद्ध दोहे में <strong>श्लेष अलंकार</strong> का अत्यंत चमत्कारिक प्रयोग हुआ है, जहाँ 'पानी' शब्द के तीन अलग-अलग संदर्भों में तीन विशिष्ट अर्थ हैं:</p>\n<ol>\n  <li><strong>मोती के संदर्भ में 'आभा/चमक' (Lustre):</strong> यदि मोती की चमक (पानी) उतर जाए, तो वह एक साधारण कंकड़ बन जाता है और उसका कोई मूल्य नहीं रहता।</li>\n  <li><strong>मनुष्य (मानुष) के संदर्भ में 'आत्मसम्मान/मर्यादा/चरित्र' (Honor/Dignity):</strong> यदि मनुष्य का स्वाभिमान और चरित्र (पानी) नष्ट हो जाए, तो समाज में उसका जीवन व्यर्थ और महत्वहीन हो जाता है।</li>\n  <li><strong>चून (आटा) के संदर्भ में 'जल' (Water):</strong> जल के बिना सूखे आटे को गूँथा नहीं जा सकता और उससे रोटी नहीं बन सकती।</li>\n</ol>\n<p>इस प्रकार पानी के बिना इन तीनों का अस्तित्व शून्य (सून) हो जाता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्लेष अलंकार का उल्लेख</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मोती के संदर्भ में चमक/आभा का अर्थ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मनुष्य के संदर्भ में आत्मसम्मान/मर्यादा का अर्थ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चून (आटे) के संदर्भ में जल का अर्थ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 23</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">रहीम का नीति-काव्य आज के तनावग्रस्त और स्वार्थी समाज में नैतिक मूल्यों के विकास में किस प्रकार उपयोगी है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>रहीम के दोहे केवल कविता नहीं हैं, बल्कि वे जीवन जीने की व्यावहारिक संहिता (आचार-संहिता) हैं। उन्होंने अपने मन की व्यथा मन में रखने, विपत्ति में धैर्य बनाए रखने, प्रेम के रिश्ते को न तोड़ने और परोपकारी बनने की जो अमूल्य सीख दी है, वह आज अत्यंत प्रासंगिक है।</p><p>यदि मनुष्य रहीम के इन नीति-सूत्रों को अपने जीवन में उतारे, तो पारिवारिक कलह, मानसिक अवसाद और सामाजिक बिखराव से सहज ही बचा जा सकता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'एके साधे सब सधै, सब साधे सब जाय' - इस दोहे का छात्रों के अध्ययन और लक्ष्य निर्धारण में क्या व्यावहारिक उपयोग है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>रहीम कहते हैं कि जैसे पेड़ की जड़ को सींचने से तने, डालियाँ, पत्ते और फल सब स्वतः तृप्त हो जाते हैं, वैसे ही एक मुख्य लक्ष्य पर ध्यान केंद्रित करने से सारे कार्य सिद्ध हो जाते हैं; जबकि एक साथ दस दिशाओं में भागने से सब कुछ हाथ से निकल जाता है।</p><p>छात्रों के लिए सीख यह है कि वे एक समय में एक ही विषय या लक्ष्य पर अपनी पूर्ण एकाग्रता (Single-minded Focus) लगाएँ। मल्टीटास्किंग और भटकाव से बचकर मूल अवधारणाओं (जड़) को मजबूत करें, तभी सफलता प्राप्त होगी।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(22)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(24)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "24": "<section class=\"chapter-section\" id=\"ch24\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">24</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (काव्य खंड)</div>\n      <h2>गीत-अगीत</h2>\n      <p>रामधारी सिंह 'दिनकर' | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">गाकर गीत विरह के तटिनी वेगवती बहती जाती है,\nदिल हलका कर लेने को उपलों से कुछ कहती जाती है।\nतट पर एक गुलाब सोचता, \"देते स्वर यदि मुझे विधाता,\nअपने पतझर के सपनों का मैं भी जग को गीत सुनाता।\"\nगा-गाकर बह रही निर्झरी, पाटल मूक खड़ा तट पर है।\nगीत अगीत, कौन सुंदर है?\n\nबैठा शुक उस घनी डाल पर जो खोंते पर छाया देती,\nपंख फुलाए नीड़ में बैठी शुकी अंडों को सेती।\nगाता शुक जब किरण बसंती छूती अंग पर्ण से छनकर,\nकिंतु शुकी के स्वर दब जाते उसके हर्षित प्रेम मगन पर।\nगूँज रहा शुक का स्वर वन में, फूला मग्न शुकी का पर है।\nगीत अगीत, कौन सुंदर है?\n\nदो प्रेमी हैं यहाँ, एक जब बड़े सांझ आल्हा गाता है,\nपहला स्वर उसकी राधा को घर से यहाँ खींच लाता है।\nचोरी-चोरी खड़ी सुनती है, \"हुई न क्यों मैं कड़ी गीत की?\"\nवह गाता, पर किसी वेग से फूल रहा इसका अंतर है।\nगीत अगीत, कौन सुंदर है?</div>\n    <div class=\"poet-name\">— रामधारी सिंह 'दिनकर'</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch24-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">नदी का बहना 'गीत' है और गुलाब का मौन रहना 'अगीत' — कवि ने ऐसा क्यों कहा है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>नदी अपने विरह और वेग को पत्थरों व किनारों से टकराकर कल-कल छल-छल की मधुर ध्वनि में प्रकट करती हुई बह रही है। उसकी भावनाएँ शब्दों और स्वर के माध्यम से मुखरित हो रही हैं, इसलिए उसका बहना <strong>'गीत'</strong> है।</p>\n<p>इसके विपरीत, किनारे पर खड़ा लाल गुलाब अपने पतझड़ के सपनों और पीड़ा को केवल मन ही मन सोचता है; विधाता ने उसे स्वर या वाणी नहीं दी, अतः वह मौन रहकर केवल अपनी सुगंध और रूप से भावना व्यक्त करता है। आंतरिक अनुभूति का यह मौन प्रकटीकरण ही <strong>'अगीत'</strong> है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नदी के कल-कल स्वर और मुखर अभिव्यक्ति को 'गीत' मानना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गुलाब के वाणीहीन मौन और आंतरिक अनुभूति को 'अगीत' मानना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch24-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">शुक (तोता) और शुकी (तोती) के प्रसंग में कौन गा रहा है और किसकी अनुभूति अधिक सघन है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>घनी डाल पर बैठकर जब बसंती किरणें पत्तों से छनकर आती हैं, तब शुक (तोता) उल्लास में भरकर मधुर स्वर में गीत गाता है। उसका स्वर पूरे वन में गूँज उठता है (यह 'गीत' है)।</p>\n<p>घोंसले में बैठी शुकी अंडों को सेते हुए उस गीत को सुनती है। यद्यपि वह गा नहीं सकती, उसका स्वर कंठ में ही घुटकर रह जाता है, परंतु उसके पंख वात्सल्य और प्रेम के असीम आनंद से फूल उठते हैं। यहाँ शुकी की मौन अनुभूति (अगीत) शुक के मुखर गीत की तुलना में कहीं अधिक सघन, गहरी और मर्मस्पर्शी है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुक के गीत गाने और वन में गूँजने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शुकी के अंडों को सेने, मौन रहने और अधिक सघन प्रेम-अनुभूति का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch24-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch24-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">‘गीत अगीत, कौन सुंदर है?’ — कवि के इस संशय का क्या समाधान है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि दिनकर जी इस द्वंद्व में पड़ जाते हैं कि मुखर शब्दों में व्यक्त होने वाला 'गीत' अधिक सुंदर है या मौन हृदय में गूँजने वाली अव्यक्त भावना (अगीत) अधिक सुंदर है।</p>\n<p><strong>समाधान:</strong> वास्तव में दोनों ही अपने-अपने स्थान पर अद्वितीय और परम सुंदर हैं। यदि गीत भावना को वाणी और संगीत देता है, तो अगीत मौन रहकर भावना की गहराई और पवित्रता को सुरक्षित रखता है। अनुभूति एक ही है; जब वह कंठ से फूटती है तो गीत बन जाती है, और जब हृदय में मूक होकर स्पंदित होती है तो अगीत बन जाती है। दोनों का सौंदर्य एक समान है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गीत (मुखर अभिव्यक्ति) और अगीत (मौन अनुभूति) के सौंदर्य का तुलनात्मक विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दोनों को समान रूप से सुंदर और एक ही अनुभूति के दो रूप मानने का तार्किक निष्कर्ष</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 24</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">मौन (Silence) की अपनी एक सशक्त भाषा होती है। कविता 'गीत-अगीत' के आलोक में स्पष्ट कीजिए कि मौन प्रेम मुखर प्रेम से कमतर क्यों नहीं है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>संसार में केवल शब्दों से ही प्रेम सिद्ध नहीं होता; मौन में जो समर्पण, त्याग और गहराई होती है, वह अक्सर शब्दों की सीमाओं से परे होती है। शुकी का अंडों को सेते हुए चुपचाप प्रेम का अनुभव करना या प्रेमिका का छिपकर प्रेमी के आल्हा को सुनते हुए अंतर्मन में पुलकित होना यह सिद्ध करता है कि प्रेम का सबसे पवित्र रूप मौन अनुभूति है।</p><p>मौन प्रेम में दिखावा नहीं होता, केवल आत्मिक एकाकारिता होती है। अतः मौन प्रेम किसी भी दृष्टि से मुखर प्रेम से कमतर नहीं, बल्कि उससे अधिक गंभीर और शाश्वत होता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">दिनकर जी की इस कविता में प्रकृति और मानवीय अनुभूतियों के मध्य स्थापित समानांतर सौंदर्य पर प्रकाश डालिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>कवि ने तीन अलग-अलग स्तरों पर गीत और अगीत का समानांतर ताना-बाना बुना है—पहले अचेतन प्रकृति (नदी और गुलाब), दूसरे पशु-पक्षी जगत (शुक और शुकी), और तीसरे मानव जगत (आल्हा गाता प्रेमी और छिपकर सुनती प्रेमिका)।</p><p>यह संरचना दर्शाती है कि प्रेम और अभिव्यक्ति का यह द्वंद्व संपूर्ण सृष्टि के कण-कण में व्याप्त है। प्रकृति और मानव की आंतरिक भावनाएँ एक ही सार्वभौमिक नियम से संचालित होती हैं।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(23)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(25)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "25": "<section class=\"chapter-section\" id=\"ch25\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">25</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (काव्य खंड)</div>\n      <h2>अग्नि पथ</h2>\n      <p>हरिवंश राय बच्चन | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">अग्नि पथ! अग्नि पथ! अग्नि पथ!\nवृक्ष हों भले खड़े, हों घने, हों बड़े,\nएक पत्र-छाहँ भी माँग मत, माँग मत, माँग मत!\nअग्नि पथ! अग्नि पथ! अग्नि पथ!\nतू न थकेगा कभी! तू न थमेगा कभी!\nतू न मुड़ेगा कभी! कर शपथ, कर शपथ, कर शपथ!\nअग्नि पथ! अग्नि पथ! अग्नि पथ!\nयह महान दृश्य है, चल रहा मनुष्य है,\nअश्रु-स्वेद-रक्त से लथपथ, लथपथ, लथपथ!\nअग्नि पथ! अग्नि पथ! अग्नि पथ!</div>\n    <div class=\"poet-name\">— हरिवंश राय बच्चन</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch25-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">‘अग्नि पथ’ किसका प्रतीक है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'अग्नि पथ' (आग का मार्ग) मनुष्य के <strong>कठिनाइयों, संघर्षों, चुनौतियों, विपत्तियों और दुखों से भरे वास्तविक जीवन-मार्ग</strong> का प्रतीक है।</p>\n<p>कवि का मानना है कि जीवन कोई फूलों की सेज नहीं है, बल्कि यह निरंतर संघर्ष की अग्नि-परीक्षा है जहाँ पग-पग पर बाधाएँ और तपिश हैं, जिनका सामना मनुष्य को निडर होकर करना पड़ता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चुनौतियों, संघर्षों और कष्टों से भरे जीवन-मार्ग का प्रतीक होना</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch25-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">‘एक पत्र-छाहँ भी माँग मत, माँग मत, माँग मत!’ — कवि ऐसा क्यों कहते हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'एक पत्र-छाहँ' (एक पत्ते की छाया) जीवन में मिलने वाले छोटे-मोटे सुख-सुविधाओं, सहारे और आश्रय का प्रतीक है। कवि इसे माँगने से इसलिए मना करते हैं क्योंकि:</p>\n<ul>\n  <li>दूसरों का सहारा या छाया माँगने से मनुष्य में निर्भरता और आलस्य आ जाता है, उसका आत्मबल कमजोर हो जाता है।</li>\n  <li>सुख-सुविधाओं की छाया में विश्राम करने से संघर्ष की गति धीमी पड़ जाती है और व्यक्ति अपने मूल लक्ष्य से भटक जाता है। मनुष्य को पूर्णतः आत्मनिर्भर और स्वाभिमानी बनकर अपने पैरों पर चलना चाहिए।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक पत्ते की छाया (सुविधा/सहारे) का लाक्षणिक अर्थ</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">आत्मनिर्भरता, स्वाभिमान और लक्ष्य से न भटकने के कारण का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch25-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch25-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">‘यह महान दृश्य है, चल रहा मनुष्य है, अश्रु-स्वेद-रक्त से लथपथ’ — इस पंक्ति का भाव स्पष्ट कीजिए।</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि के अनुसार संसार का सबसे अलौकिक, भव्य और प्रेरणादायक (महान) दृश्य वह है जब मनुष्य जीवन के संघर्षों से घबराकर रुकता या झुकता नहीं, बल्कि निरंतर आगे बढ़ता रहता है।</p>\n<p>वह अपने लक्ष्य की प्राप्ति के लिए:</p>\n<ul>\n  <li><strong>अश्रु (आँसू):</strong> गहरी मानसिक वेदना और दुखों को सहता है,</li>\n  <li><strong>स्वेद (पसीना):</strong> अत्यधिक कठोर शारीरिक परिश्रम करता है,</li>\n  <li><strong>रक्त (खून):</strong> और आवश्यकता पड़ने पर अपना बलिदान देने से भी पीछे नहीं हटता।</li>\n</ul>\n<p>आँसू, पसीने और खून से पूरी तरह भीगा हुआ (लथपथ) कर्मठ मनुष्य ही जीवन की वास्तविक विजय और मानवीय गरिमा का प्रतीक है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संसार के सबसे महान दृश्य (संघर्षरत मनुष्य) की व्याख्या</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अश्रु (वेदना), स्वेद (परिश्रम) और रक्त (बलिदान) के प्रतीकार्थ का स्पष्टीकरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अदम्य जिजीविषा और कर्मठता का संदेश</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 25</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">कविता 'अग्नि पथ' आज के युवाओं को असफलताओं और निराशा से उबारने में किस प्रकार एक संजीवनी का कार्य करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज की प्रतिस्पर्धी दुनिया में युवा छोटी-सी असफलता से हताश होकर डिप्रेशन का शिकार हो जाते हैं। 'अग्नि पथ' उन्हें यह अमर संकल्प देती है—'तू न थकेगा कभी, तू न थमेगा कभी, तू न मुड़ेगा कभी।'</p><p>यह कविता सिखाती है कि असफलताएँ जीवन का अंत नहीं हैं। परिस्थितियाँ चाहे जितनी भी विषम हों, यदि मनुष्य बिना किसी बैसाखी के, आत्मनिर्भर होकर निरंतर परिश्रम करता रहे, तो वह हर अग्नि-पथ को पार करके सफलता के शिखर पर पहुँच सकता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">कविता में शब्दों और वाक्यांशों की पुनरावृत्ति (जैसे 'अग्नि पथ!', 'माँग मत!', 'कर शपथ!') का कविता के प्रभाव और ओज पर क्या असर पड़ता है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>इस प्रकार की ओजस्वी पुनरावृत्ति (Repetition) से कविता में अद्भुत नाद-सौंदर्य और लयबद्धता उत्पन्न होती है। यह पाठक के मन में सोए हुए साहस, उत्साह और संकल्प को बार-बार झकझोर कर जाग्रत करती है।</p><p>यह दोहराव एक सैनिक की तरह अनुशासन और दृढ़ता का वातावरण रचता है जिससे पाठक के भीतर भी कठिनाइयों से जूझने का अदम्य उत्साह संचारित हो जाता है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(24)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(26)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "26": "<section class=\"chapter-section\" id=\"ch26\" data-book=\"sparsh-kavya\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">26</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">स्पर्श भाग-1 (काव्य खंड)</div>\n      <h2>नए इलाके में / खुशबू रचते हैं हाथ</h2>\n      <p>अरुण कमल | काव्य खंड — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"poem-display-box\">\n    <div class=\"poem-body\">नए इलाके में:\nइन नए बसते इलाकों में\nजहाँ रोज बन रहे हैं नए-नए मकान\nमैं अक्सर रास्ता भूल जाता हूँ\nधोखा दे जाते हैं पुराने निशान\nखोजता हूँ ताकता पीपल का पेड़\nखोजता हूँ ढहा हुआ मकान\nऔर जमीन का खाली टुकड़ा जहाँ से बाएँ मुड़ना था मुझे\nयहाँ स्मृति का भरोसा नहीं\nएक ही दिन में पुरानी पड़ जाती है दुनिया...\n\nखुशबू रचते हैं हाथ:\nकई गलियों के बीच\nकई नालों के पार\nकूड़े-करकट के ढेरों के बाद\nबदबू से फटते जाते इस टोले के अंदर\nखुशबू रचते हैं हाथ\nखुशबू रचते हैं हाथ।\nउभरी नसों वाले हाथ\nघिसे नाखूनों वाले हाथ\nपीपल के पत्ते से नए-नए हाथ\nजूही की डाल से खुशबूदार हाथ\nगंदे कटे-पिटे हाथ\nजख्म से फटे हुए हाथ\nखुशबू रचते हैं हाथ\nखुशबू रचते हैं हाथ।</div>\n    <div class=\"poet-name\">— अरुण कमल</div>\n  </div>\n\n  <div class=\"ex-div\">प्रश्न-अभ्यास — नए इलाके में (100% कवरेज)</div>\n\n  <div class=\"q-card\" id=\"ch26-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">‘नए इलाके में’ कवि रास्ता क्यों भूल जाता है और यह हमारे आधुनिक समय की किस विडंबना को उजागर करता है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि नए बसते इलाकों में रास्ता इसलिए भूल जाता है क्योंकि अंधाधुंध शहरीकरण और निर्माण के कारण प्रतिदिन नए-नए मकान बन रहे हैं। वे पुराने निशान (जैसे पीपल का पेड़, ढहा हुआ मकान, खाली मैदान) जिनके आधार पर वह रास्ता तय करता था, रातों-रात गायब हो जाते हैं।</p>\n<p><strong>आधुनिक विडंबना:</strong> यह कविता इस बात को उजागर करती है कि आज का विकास इतना तेज, अनियंत्रित और आत्मकेंद्रित है कि स्मृतियों और आत्मीय पहचान का कोई मूल्य नहीं बचा। एक ही दिन में दुनिया पुरानी पड़ जाती है और मनुष्य अपने ही शहर में अजनबी और दिशाहीन महसूस करने लगता है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अंधाधुंध निर्माण एवं पुराने निशानों के गायब होने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">स्मृतियों के क्षरण एवं आत्मीयता के लोप की आधुनिक विडंबना का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास — खुशबू रचते हैं हाथ (100% कवरेज)</div>\n\n  <div class=\"q-card\" id=\"ch26-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">‘खुशबू रचते हैं हाथ’ कविता में समाज के किस वर्ग की त्रासदी को चित्रित किया गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>इस कविता में अरुण कमल जी ने <strong>अगरबत्ती बनाने वाले गरीब, शोषित और उपेक्षित असंगठित मजदूर वर्ग (विशेषकर महिलाओं, बच्चों और बुजुर्गों)</strong> की दारुण त्रासदी का यथार्थवादी चित्रण किया है।</p>\n<p>यह वह वर्ग है जो अपने हाथों से सुगंधित अगरबत्तियाँ (केवड़ा, गुलाब, खस, चमेली) बनाकर पूरे संसार के घरों और मंदिरों को महकाता है, परंतु स्वयं नारकीय, गंदी और अस्वास्थ्यकर बस्तियों में भूख और अभावों में जीने को विवश है। कवि ने इस भयानक सामाजिक विषमता और श्रम के क्रूर शोषण को उजागर किया है।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अगरबत्ती बनाने वाले शोषित मजदूर वर्ग की पहचान</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">संसार को महकाने बनाम स्वयं नारकीय जीवन जीने की त्रासदी का विश्लेषण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch26-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">खुशबू रचने वाले हाथ कैसी परिस्थितियों में रहने को विवश हैं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>संसार को सुगंध बाँटने वाले इन कामगारों का परिवेश अत्यंत अमानवीय, संड़ांध भरा और नारकीय है:</p>\n<ul>\n  <li>वे गंदे नालों के पार, सड़े हुए कूड़े-करकट के ढेरों के बीच बदबूदार तंग गलियों और झुग्गियों में रहते हैं जहाँ साँस लेना भी दूभर होता है।</li>\n  <li>रसायनों और बाँस की तीलियों पर दिन-रात लगातार काम करने के कारण उनके हाथों की नसें उभर आई हैं, नाखून घिस चुके हैं और हाथ गंदे, कटे-पिटे व जख्मों से भरे हुए हैं। वे बुनियादी स्वास्थ्य और मानवीय अधिकारों से पूरी तरह वंचित हैं।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">नालों, कूड़े के ढेरों और बदबूदार झुग्गियों के अमानवीय परिवेश का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उभरी नसों, घिसे नाखूनों और कटे-पिटे जख्मी हाथों की शारीरिक प्रताड़ना का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch26-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch26-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कवि ने 'खुशबू रचते हैं हाथ' पंक्ति की बार-बार आवृत्ति क्यों की है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कवि ने इस पंक्ति को ध्रुवपद की तरह बार-बार इसलिए दोहराया है ताकि वह समाज की अंतरात्मा पर गहरा आघात कर सके:</p>\n<ul>\n  <li><strong>तीखा विरोधाभास:</strong> एक ओर घोर गंदगी, बदबू और कटे-पिटे हाथ हैं, और दूसरी ओर उनसे रची जाने वाली दिव्य 'खुशबू' है। इस विरोधाभास को रेखांकित करने के लिए आवृत्ति की गई है।</li>\n  <li><strong>श्रम का सम्मान व संवेदना:</strong> यह पंक्ति पाठक को यह सोचने पर विवश करती है कि जिस सुगंध से हमारे पूजा-घर महकते हैं, उसके पीछे उन अनाम मजदूरों का कितना रक्त, पसीना और आँसू बहा हुआ है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गंदगी बनाम खुशबू के तीखे विरोधाभास का उद्घाटन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्रम की उपेक्षा पर प्रहार और सामाजिक संवेदनशीलता जाग्रत करने का उद्देश्य</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 26</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">असंगठित क्षेत्र के मजदूरों (सफाईकर्मी, अगरबत्ती निर्माता आदि) के प्रति समाज और सरकार का क्या कर्तव्य होना चाहिए?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>जो हाथ संसार को सुंदरता, स्वच्छता और सुगंध देते हैं, वे स्वयं उपेक्षा और बीमारी के अंधकार में जीने को विवश हैं। यह किसी भी सभ्य समाज के लिए अत्यंत शर्मनाक है।</p><p>सरकार का कर्तव्य है कि वह इन मजदूरों के लिए न्यूनतम उचित मजदूरी, दस्ताने/मास्क जैसी सुरक्षा किट, स्वास्थ्य बीमा और स्वच्छ आवास की व्यवस्था करे। समाज के रूप में हमारा कर्तव्य है कि हम उनके श्रम का आदर करें, उन्हें उचित पारिश्रमिक दें और उन्हें हेय दृष्टि से न देखकर मानवीय सम्मान दें।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'नए इलाके में' कविता की तुलना आज के जीपीएस (GPS) और स्मार्ट सिटीज के दौर में मानवीय एकाकीपन से कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज शहर स्मार्ट हो रहे हैं और हमारे पास जीपीएस मैप्स हैं, फिर भी मनुष्य का आंतरिक भटकाव और अकेलापन बढ़ता जा रहा है। जैसे-जैसे पुरानी बस्तियाँ और पेड़ कट रहे हैं, वैसे-वैसे लोगों के बीच का आत्मीय संपर्क भी टूट रहा है।</p><p>कवि की यह छटपटाहट भौतिक विकास के उस खोखलेपन को उजागर करती है जहाँ इमारतें तो ऊँची हो रही हैं, पर मानवीय रिश्ते और स्मृतियाँ एक ही दिन में पुरानी होकर मिट रही हैं।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(25)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(27)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "27": "<section class=\"chapter-section\" id=\"ch27\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">27</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>गिल्लू</h2>\n      <p>महादेवी वर्मा | पूरक पाठ्यपुस्तक (रेखाचित्र/संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch27-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">सोनजुही में लगी पीली कली को देखकर लेखिका के मन में कौन-से विचार उमड़ने लगे?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>सोनजुही की हरी-भरी लता में खिली एक नन्हीं पीली कली को देखकर महादेवी वर्मा जी के मन में अचानक अपने प्रिय और नन्हें जीव <strong>'गिल्लू' (गिलहरी के बच्चे)</strong> की सजीव स्मृति कौंध गई।</p>\n<p>गिल्लू को सोनजुही की घनी लताओं में छिपकर बैठना बहुत पसंद था। लेखिका सोचने लगीं कि गिल्लू को इसी सोनजुही की लता की जड़ के नीचे समाधि दी गई थी। संभवतः वही नन्हा जीव आज इस पीली कली के रूप में फूटकर मुझे चौंकाने और अपना स्नेह प्रकट करने आ गया है। इस विचार ने लेखिका के हृदय को एक साथ विरह और वात्सल्य से भर दिया।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोनजुही की कली देखकर गिल्लू की स्मृति कौंधने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गिल्लू के लता में बैठने और समाधि के प्रसंग का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कली के रूप में गिल्लू के पुनरागमन की काव्यात्मक कल्पना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch27-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">पाठ के आधार पर कौए को एक साथ 'समादरित' और 'अनादरित' प्राणी क्यों कहा गया है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>भारतीय समाज और परंपरा में कौए की स्थिति अत्यंत विचित्र और विरोधाभासी है:</p>\n<ul>\n  <li><strong>समादरित (आदरणीय) रूप:</strong> श्राद्ध पक्ष (पितृपक्ष) में हमारे पूर्वज (पितर) गरुड़ या हंस बनकर नहीं आते, बल्कि उन्हें कौए का रूप धारण करके ही आना पड़ता है। जब तक कौआ हमारे दिए भोजन (पिंड) को नहीं खाता, तब तक पितरों की तृप्ति नहीं मानी जाती। साथ ही घर की मुँडेर पर कौए का बोलना किसी प्रिय अतिथि के आने का शुभ संकेत माना जाता है।</li>\n  <li><strong>अनादरित (अपमानित) रूप:</strong> इसके विपरीत, दैनिक जीवन में कौए की कर्कश और तीखी 'काँव-काँव' को अमंगलकारी और अप्रिय माना जाता है। किसी की उपेक्षा या तिरस्कार करने के लिए कौए की तुलना की जाती है। अतः कौआ एक साथ समादरित और अनादरित प्राणी है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">श्राद्ध पक्ष व अतिथि आगमन के संदर्भ में समादरित होने का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कर्कश स्वर एवं तिरस्कार के संदर्भ में अनादरित होने का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch27-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">गिलहरी के घायल बच्चे (गिल्लू) का उपचार किस प्रकार किया गया?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>गमले की संधि में पड़े गिलहरी के नन्हें बच्चे को दो कौओं ने अपनी तीखी चोंचों से मार-मारकर अधमरा और लहूलुहान कर दिया था।</p>\n<p>लेखिका ने अत्यंत करुणा और ममता से उसका उपचार निम्नलिखित प्रकार से किया:</p>\n<ul>\n  <li>उसे कोमलता से उठाकर अपने कमरे में लाईं और रुई से उसके घावों से बहता हुआ रक्त पोंछा।</li>\n  <li>घावों पर 'पेनिसिलिन' का मरहम लगाया।</li>\n  <li>रूई की पतली बत्ती बनाकर दूध में भिगोई और बड़ी मुश्किल से उसके नन्हें अधखुले मुँह में बूँद-बूँद दूध टपकाया। कई घंटों के अथक परिश्रम के बाद उसने एक बूँद पानी पिया और तीसरे दिन वह इतना स्वस्थ हो गया कि अपनी चमकीली आँखों से देखने लगा।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कौओं के हमले से लहूलुहान होने की स्थिति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घाव साफ कर पेनिसिलिन मरहम लगाने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">रूई की बत्ती से दूध और पानी पिलाकर प्राण बचाने का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch27-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">लेखिका का ध्यान आकर्षित करने के लिए गिल्लू क्या-क्या नटखट चेष्टाएँ करता था?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>जब महादेवी वर्मा जी लिखने-पढ़ने बैठती थीं, तो गिल्लू का बाल-सुलभ मन लेखिका का ध्यान अपनी ओर खींचने के लिए मचल उठता था। इसके लिए उसने एक अनोखा उपाय खोज निकाला था:</p>\n<ul>\n  <li>वह तेजी से लेखिका की मेज पर आता, उनके पैरों के पास से दौड़ता हुआ सीधे उनके कंधे पर चढ़ जाता और फिर सर्र से नीचे उतर जाता। यह दौड़-कूद का क्रम तब तक चलता जब तक लेखिका उसे पकड़ न लें।</li>\n  <li>कभी वह कलमदान में छिपकर बैठ जाता, कभी मेज पर रखे कागजों के नीचे केवल अपना सिर बाहर निकाल कर छिप जाता, और कभी पर्दे की चुन्नटों या फूलदान के फूलों के बीच छिपकर लेखिका की दृष्टि का इंतजार करता था।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कंधे पर चढ़ने और नीचे दौड़ने की नटखट क्रिया का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कागजों, फूलदान, पर्दे और कलमदान में छिपने की शरारतों का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की सजीवता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch27-q5\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q5')\">\n      <div class=\"q-num\">प्रश्न 5</div>\n      <div class=\"q-text\">गिल्लू को मुक्त करने की आवश्यकता क्यों समझी गई और उसके लिए लेखिका ने क्या व्यवस्था की?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>वसंत ऋतु के आगमन पर जब बाहर की जंगली गिलहरियाँ खिड़की की जाली के पास आकर 'चिक-चिक' करके बातें करती थीं, तब गिल्लू जाली से सटकर बैठ जाता था और बाहर की ओर उदास नजरों से ताकता रहता था।</p>\n<p>लेखिका ने उसकी इस स्वाभाविक स्वतंत्रता की छटपटाहट को पहचान लिया और समझा कि अब इसे प्रकृति के मुक्त आँगन में छोड़ना ही उचित है।</p>\n<p><strong>व्यवस्था:</strong> लेखिका ने कीलें निकालकर खिड़की की लोहे की जाली का एक कोना खोल दिया। इस मार्ग से गिल्लू अपनी मर्जी से दिन भर बाहर गिलहरियों के झुंड में उछल-कूद करता और शाम होते ही कमरे में अपने झूले में लौट आता था।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">अन्य गिलहरियों को देखकर स्वतंत्रता की स्वाभाविक चाह का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">खिड़की की जाली का एक कोना खोलकर स्वच्छंद आवागमन की व्यवस्था</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch27-q6\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q6')\">\n      <div class=\"q-num\">प्रश्न 6</div>\n      <div class=\"q-text\">गिल्लू की किन चेष्टाओं से यह आभास मिलने लगा था कि अब उसका अंत समय समीप है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>गिलहरियों का जीवन-काल सामान्यतः दो वर्ष से अधिक नहीं होता। जब गिल्लू के जीवन के दो वर्ष पूरे होने को आए, तो निम्नलिखित लक्षणों से स्पष्ट हो गया कि उसका अंतिम समय आ गया है:</p>\n<ul>\n  <li>उसने दिन भर न तो कुछ खाया और न ही वह बाहर घूमने गया। उसका सबसे प्रिय भोजन 'काजू' भी जब उसके झूले में रखा गया, तो उसने उसे छुआ तक नहीं।</li>\n  <li>रात को अत्यंत ठंड और असह्य पीड़ा होने पर वह अपने झूले से उतरकर लेखिका के बिस्तर पर आ गया और उसी उँगली को अपने ठंडे पंजों से पकड़कर चिपक गया, जिसे उसने बचपन में मृत्यु-शैया पर पकड़ा था। उसके पंजे बर्फ की तरह ठंडे हो रहे थे।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">गिलहरियों के दो वर्ष के संक्षिप्त जीवन-काल का संदर्भ</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भोजन (काजू) का त्याग और बाहर न जाने का लक्षण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">लेखिका की उँगली को ठंडे पंजों से पकड़ने का मार्मिक दृश्य</span><span class=\"marking-marks\">1.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch27-q7\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch27-q7')\">\n      <div class=\"q-num\">प्रश्न 7</div>\n      <div class=\"q-text\">सोनजुही की लता के नीचे गिल्लू को समाधि क्यों दी गई?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>महादेवी वर्मा जी ने गिल्लू को सोनजुही की लता के नीचे समाधि निम्नलिखित दो मुख्य कारणों से दी:</p>\n<ul>\n  <li><strong>गिल्लू का प्रिय स्थल:</strong> अपने जीवन काल में गिल्लू को सोनजुही की घनी, हरी-भरी लताओं में छिपकर बैठना, झूलना और विश्राम करना सबसे अधिक प्रिय था। अतः उसके सबसे प्रिय स्थल पर ही उसे चिर-विश्राम दिया गया।</li>\n  <li><strong>लेखिका का विश्वास व संबल:</strong> लेखिका को यह दृढ़ विश्वास था कि वसंत के मौसम में किसी दिन गिल्लू इस सोनजुही की लता में एक नन्हीं, पीली, सुगंधित कली के रूप में पुनः खिलकर उनके सामने आ जाएगा। यह समाधि उनके अमर प्रेम का पावन प्रतीक थी।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सोनजुही लता के गिल्लू का सर्वाधिक प्रिय स्थान होने का कारण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">पीली कली के रूप में गिल्लू के पुनरागमन के विश्वास और स्नेह का स्पष्टीकरण</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 27</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">महादेवी वर्मा का गिल्लू के प्रति यह वात्सल्य और संवेदनशीलता मनुष्य और मूक पशु-पक्षियों के बीच किस आदर्श रिश्ते को रेखांकित करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज का मनुष्य स्वार्थ और विकास की अंधी दौड़ में मूक पशु-पक्षियों के प्राकृतिक आवासों को नष्ट कर रहा है। ऐसे समय में महादेवी वर्मा का गिल्लू के प्रति व्यवहार सह-अस्तित्व और करुणा का सर्वोच्च शिखर प्रस्तुत करता है।</p><p>उन्होंने एक नन्हें से घायल जीव की जान बचाई, उसकी स्वतंत्रता का सम्मान किया और उसे परिवार के सदस्य जैसा प्रेम दिया। यह पाठ सिखाता है कि मूक प्राणी भी केवल प्रेम और आदर की भाषा समझते हैं। यदि मनुष्य उनके प्रति संवेदनशील बने, तो प्रकृति और मानव का यह रिश्ता समस्त सृष्टि को सुंदर बना सकता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">जब लेखिका अस्वस्थ थीं, तब गिल्लू द्वारा की गई परिचर्या (सेवा) किस प्रकार पशुओं की अंतःप्रज्ञा (Intuition) को प्रमाणित करती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>जब महादेवी वर्मा एक मोटर दुर्घटना में घायल होकर अस्पताल से लौटीं, तो गिल्लू ने अपने झूले से उतरकर उनके सिरहाने बैठकर अपने नन्हें पंजों से उनके बालों और सिर को आहिस्ता-आहिस्ता सहलाना शुरू कर दिया।</p><p>यह दृश्य यह सिद्ध करता है कि पशुओं में भी गहरी संवेदना, कृतज्ञता और अपने रक्षक की पीड़ा को भाँप लेने की दिव्य अंतःप्रज्ञा होती है। उसका यह स्पर्श किसी स्नेहमयी नर्स या पारिवारिक सदस्य की सांत्वना से भी अधिक भावपूर्ण था।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(26)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(28)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "28": "<section class=\"chapter-section\" id=\"ch28\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">28</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>स्मृति</h2>\n      <p>श्रीराम शर्मा | पूरक पाठ्यपुस्तक (शिकार-कथा/साहसिक संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch28-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">भाई के बुलाने पर घर लौटते समय लेखक के मन में किस बात का डर था?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>उस शीतकाल की दोपहर में लेखक अपने छोटे भाई और साथियों के साथ जंगल में बेर तोड़कर खा रहे थे। तभी गाँव के एक व्यक्ति ने पुकारा कि उनके बड़े भाई साहब बुला रहे हैं।</p>\n<p>यह सुनते ही लेखक का दिल दहल गया और वे काँपने लगे। उनके मन में यह तीव्र भय था कि बड़े भाई साहब को निश्चित ही उनके बेर खाने, मटर चुराने या पढ़ाई छोड़कर घूमने की शरारत का पता चल गया है, और अब घर पहुँचते ही उनकी लाठियों या डंडों से भीषण पिटाई (मरम्मत) होगी। वे अत्यंत सहमे हुए कदमों से घर की ओर चले।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बेर तोड़ने और पढ़ाई छोड़कर घूमने की शरारत की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बड़े भाई के अनुशासन और पिटाई के भय की सजीव अभिव्यक्ति</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch28-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">मक्खनपुर पढ़ने जाने वाले बच्चों की टोली रास्ते में पड़ने वाले कुएँ में ढेला क्यों फेंकती थी?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>मक्खनपुर के रास्ते में एक सूखा और गहरा कच्चा कुआँ था, जिसमें एक अत्यंत विशाल और विषैला काला साँप (साँप) रहता था।</p>\n<p>बच्चों की टोली जब भी उस कुएँ के पास से गुजरती थी, तो वे कुएँ की मुँडेर पर खड़े होकर नीचे एक ढेला (मिट्टी या पत्थर का टुकड़ा) फेंकते थे। ढेला गिरते ही नीचे बैठा साँप क्रोध से फुंकार मारता था। उस शांत और गहरे कुएँ में साँप की वह प्रतिध्वनित होने वाली तीखी फुसकार सुनकर बच्चों को एक अद्भुत, रोमांचकारी और बाल-सुलभ आनंद की अनुभूति होती थी।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">सूखे कुएँ में विषैले काले साँप के होने का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">ढेला फेंककर साँप की भयानक फुसकार सुनने के रोमांचकारी कौतूहल का वर्णन</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch28-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">कुएँ में गिरी चिट्ठियों को निकालने के लिए लेखक ने क्या योजना बनाई और क्या तैयारी की?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>जब कुएँ में ढेला फेंकते समय लेखक की टोपी में रखी तीनों जरूरी सरकारी चिट्ठियाँ फिसलकर कुएँ के पाताल में साँप के पास गिर गईं, तो लेखक ने बड़े भाई की पिटाई और कर्तव्य के दबाव में कुएँ में उतरने का साहसिक निर्णय लिया।</p>\n<p><strong>योजना एवं तैयारी:</strong></p>\n<ol>\n  <li><strong>धोतियों की रस्सी बनाना:</strong> लेखक और उनके छोटे भाई ने अपने शरीर से चार-पाँच धोतियाँ उतारीं और उनके सिरों को आपस में बहुत मजबूत गाँठें लगाकर एक लंबी रस्सी तैयार की।</li>\n  <li><strong>डंडे को बाँधना:</strong> रस्सी के एक छोर पर लेखक का प्रिय और आज्ञाकारी शिकार-डंडा बाँधा गया तथा दूसरे छोर को कुएँ के ऊपर खड़े छोटे भाई ने कुएँ के पास के पेड़ या मुँडेर पर मजबूती से पकड़ लिया।</li>\n  <li><strong>कुएँ में उतरना:</strong> लेखक ने धोती की रस्सी को पकड़कर अपने पैरों को कुएँ की कच्ची दीवारों पर टिकाते हुए धीरे-धीरे उस काल-कोठरी रूपी कुएँ में उतरना शुरू किया।</li>\n</ol>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">चिट्ठियों के गिरने और कर्तव्य के भय की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">धोतियों को जोड़कर मजबूत रस्सी बनाने की तैयारी</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">डंडा बाँधकर पैरों के सहारे कुएँ में उतरने की साहसिक योजना</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्रमबद्ध एवं शुद्ध भाषा</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch28-q4\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch28-q4')\">\n      <div class=\"q-num\">प्रश्न 4</div>\n      <div class=\"q-text\">कुएँ में उतरकर लेखक और भयानक काले विषधर के बीच जो द्वंद्व हुआ, उसका रोंगटे खड़े कर देने वाला वर्णन कीजिए।</div>\n      <div class=\"q-marks\">5 अंक (100-120 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>कुएँ के धरातल पर मात्र चार-पाँच गज का संकरा स्थान था। जैसे ही लेखक के पैर नीचे पहुँचे, उनके ठीक सामने फन फैलाए, जीभ लपलपाता हुआ साक्षात यमदूत के समान एक भयानक काला साँप बैठा था।</p>\n<p><strong>रोमांचक द्वंद्व:</strong></p>\n<ul>\n  <li>कुएँ में इतना स्थान नहीं था कि डंडे को घुमाकर प्रहार किया जा सके। जैसे ही लेखक ने डंडे से चिट्ठियों को खिसकाने का प्रयास किया, साँप ने बिजली की तेजी से डंडे पर फुंकारते हुए जबर्दस्त वार किया। उसकी विषैली फुंकार की हवा लेखक के चेहरे को छूकर निकल गई।</li>\n  <li>डंडा लेखक के हाथ से छूट गया। लेखक दीवार से चिपककर खड़े हो गए। ऊपर से छोटा भाई रो-रोकर लेखक को मरा समझकर चिल्लाने लगा।</li>\n  <li>लेखक ने असीम धैर्य और शीतलता दिखाई। उन्होंने साँप का ध्यान दूसरी ओर भटकाने के लिए कुएँ की दीवार से थोड़ी-सी मिट्टी खुरचकर साँप के दाईं ओर फेंकी। जैसे ही साँप मिट्टी पर झपटा, लेखक ने बिजली की फुर्ती से अपना डंडा और तीनों चिट्ठियाँ उठा लीं और अपनी धोती में खोंस लीं।</li>\n  <li>इसके बाद वे हाथों के बल रस्सी पकड़कर तेजी से ऊपर चढ़ आए। इस प्रकार लेखक ने मौत के मुँह से निकलकर विजय प्राप्त की।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कुएँ के संकरे स्थान और फन फैलाए काले नाग के दृश्य का विवरण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">साँप द्वारा डंडे पर भीषण प्रहार एवं डंडा छूटने का संकट</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">मिट्टी फेंककर ध्यान भटकाने की चतुराई और चिट्ठियाँ उठाकर बाहर आने का रोमांच</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उत्कृष्ट, सजीव और रोंगटे खड़े करने वाली भाषा-शैली</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 28</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">श्रीराम शर्मा के इस संस्मरण से विपरीत और जानलेवा परिस्थितियों में 'धैर्य, सूझबूझ और साहस' की क्या सीख मिलती है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>जब लेखक कुएँ में फन फैलाए विषधर के सामने खड़े थे, तब जरा-सा भी घबराना या हड़बड़ाना उनकी तत्काल मृत्यु का कारण बन सकता था। लेखक ने मृत्यु को इतने निकट देखकर भी चीखने-चिल्लाने के बजाय अपने मस्तिष्क को पूरी तरह शांत और एकाग्र रखा।</p><p>उन्होंने मिट्टी फेंककर साँप का ध्यान भटकाया और अपनी जान बचाई। यह सिखाता है कि संकट के समय भयभीत होकर हथियार डाल देने के बजाय यदि धैर्य, बुद्धि और रणनीतिक सूझबूझ से काम लिया जाए, तो असंभव लगने वाली चुनौतियों और निश्चित दिखती पराजय को भी विजय में बदला जा सकता है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">बड़े भाई के प्रति लेखक का जो अगाध आदर और कर्तव्य-बोध था, उसकी तुलना आज की पारिवारिक व्यवस्था से कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>लेखक जानते थे कि यदि चिट्ठियाँ डाकखाने नहीं पहुँचीं, तो बड़े भाई नाराज होंगे। बड़े भाई की डाँट और अपने कर्तव्य को पूरा करने के लिए लेखक ने अपनी जान दाँव पर लगा दी। घर लौटने पर उन्होंने माँ की गोद में सिर रखकर आँसू बहाए, पर भाई से कुछ नहीं कहा।</p><p>यह उस दौर के पारिवारिक अनुशासन, बड़ों के प्रति असीम निष्ठा और जिम्मेदारी की भावना को दर्शाता है। आज के समय में जहाँ बच्चे अनुशासनहीन हो रहे हैं और जिम्मेदारियों से भागते हैं, यह संस्मरण पारिवारिक मर्यादा और कर्तव्य-निष्ठा का अद्भुत पाठ पढ़ाता है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(27)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(29)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "29": "<section class=\"chapter-section\" id=\"ch29\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">29</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>कल्लू कुम्हार की उनाकोटी</h2>\n      <p>के. विक्रम सिंह | पूरक पाठ्यपुस्तक (यात्रा-वृत्तांत) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch29-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">‘उनाकोटी’ का क्या अर्थ है और यह स्थान कहाँ स्थित है?</div>\n      <div class=\"q-marks\">2 अंक (30-40 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>'उनाकोटी' का शाब्दिक अर्थ होता है—<strong>'एक करोड़ से एक कम'</strong> (अर्थात 99 लाख, 99 हजार, 999)।</p>\n<p>यह अद्भुत और रहस्यमयी पुरातात्विक तीर्थस्थल भारत के पूर्वोत्तर राज्य <strong>त्रिपुरा</strong> के उत्तरी जिले (कैलाशहर से लगभग 9 किलोमीटर दूर घने जंगलों और पहाड़ियों के बीच) में स्थित है। यहाँ पत्थरों और विशाल चट्टानों को काटकर उकेरी गई भगवान शिव और अन्य देवी-देवताओं की सहस्रों विशालकाय मूर्तियाँ हैं।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">उनाकोटी के शाब्दिक अर्थ (एक करोड़ से एक कम) का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">त्रिपुरा के उत्तरी जिले में भौगोलिक स्थिति का वर्णन</span><span class=\"marking-marks\">0.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं वर्तनी</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch29-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">उनाकोटी के संदर्भ में 'कल्लू कुम्हार' की क्या पौराणिक व लोक कथा प्रचलित है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>उनाकोटी की मूर्तियों के निर्माण के पीछे स्थानीय लोक-संस्कृति में कल्लू कुम्हार की निम्नलिखित रोचक कथा प्रचलित है:</p>\n<ul>\n  <li>कल्लू कुम्हार भगवान शिव और पार्वती का अनन्य भक्त था और वह उनके साथ साक्षात कैलाश पर्वत पर जाना चाहता था।</li>\n  <li>पार्वती जी के अनुरोध पर भगवान शिव ने उसके सामने एक कठिन शर्त रखी कि—<em>'यदि तुम केवल एक ही रात में भगवान शिव और उनके गणों की एक करोड़ मूर्तियाँ बना दोगे, तो तुम्हें कैलाश चलने की अनुमति मिलेगी।'</em></li>\n  <li>कल्लू रात भर बिना रुके पूरी तन्मयता से मूर्तियाँ गढ़ता रहा। जब सुबह भोर की पहली किरण फूटी और शिव जी ने मूर्तियों की गिनती की, तो पाया कि मूर्तियाँ पूरी एक करोड़ न होकर <strong>एक करोड़ से एक कम (उनाकोटी)</strong> रह गईं।</li>\n  <li>शर्त पूरी न होने के कारण शिव जी कल्लू को वहीं छोड़कर आगे बढ़ गए और इस प्रकार उस स्थान का नाम 'उनाकोटी' पड़ गया।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कल्लू कुम्हार की कैलाश जाने की इच्छा और शिव जी की शर्त का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक रात में एक करोड़ मूर्तियाँ बनाने के संकल्प का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">एक मूर्ति कम रह जाने और 'उनाकोटी' नामकरण की सार्थकता</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की स्पष्टता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch29-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch29-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">त्रिपुरा के जनजीवन में 'बाँस' (Bamboo) का क्या महत्व है?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>त्रिपुरा के सामाजिक, सांस्कृतिक और आर्थिक जीवन की रीढ़ 'बाँस' है:</p>\n<ul>\n  <li><strong>घरेलू उपयोग एवं हस्तशिल्प:</strong> वहाँ के घर, चारदीवारी, पुल, टोकरियाँ, चटाइयाँ, फर्नीचर और दैनिक उपयोग के बर्तन सब बाँस से बनते हैं। त्रिपुरा का बाँस-शिल्प विश्व भर में प्रसिद्ध है।</li>\n  <li><strong>भोजन में उपयोग:</strong> बाँस के कोमल अंकुरों (बैम्बू शूट्स) का उपयोग स्थानीय लोग अत्यंत स्वादिष्ट पारंपरिक सब्जी और आचार बनाने में करते हैं। बाँस वहाँ केवल एक वनस्पति नहीं, बल्कि जीवन जीने का अनिवार्य साधन है।</li>\n</ul>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घरों, पुलों, टोकरियों और हस्तशिल्प में बाँस के उपयोग का उल्लेख</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भोजन (बैम्बू शूट्स) और आर्थिक आजीविका के साधन के रूप में महत्व</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 29</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">पूर्वोत्तर भारत (त्रिपुरा आदि राज्यों) की समृद्ध सांस्कृतिक विरासत और प्राकृतिक संपदा को मुख्यधारा के भारतीयों द्वारा समझना क्यों आवश्यक है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>अक्सर भौगोलिक दूरी और अज्ञानता के कारण शेष भारत पूर्वोत्तर राज्यों की समृद्ध संस्कृति, कला और परंपराओं से अनभिज्ञ रहता है। 'कल्लू कुम्हार की उनाकोटी' जैसे पाठ हमें यह अहसास कराते हैं कि त्रिपुरा की पुरातात्विक संपदा, जनजातीय संगीत और बाँस-कला भारत के सांस्कृतिक मुकुट का अनमोल रत्न हैं।</p><p>राष्ट्रीय एकता और अखंडता को सुदृढ़ करने के लिए पूर्वोत्तर के जनजीवन, इतिहास और लोक-कथाओं का सम्मान करना और उन्हें मुख्यधारा के पाठ्यक्रम व पर्यटन में बढ़ावा देना नितांत आवश्यक है।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">उनाकोटी में स्थित 'उन्मुक्त आकाश के नीचे चट्टानों पर उकेरी गई मूर्तियों' के संरक्षण के लिए आधुनिक युग में क्या कदम उठाए जाने चाहिए?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>उनाकोटी की मूर्तियाँ खुले आकाश में स्थित हैं, जहाँ तेज मानसूनी वर्षा, एसिड रेन, काई और जंगलों के क्षरण के कारण प्राचीन नक्काशीदार चट्टानें घिस रही हैं।</p><p>भारतीय पुरातत्व सर्वेक्षण (ASI) को इन मूर्तियों पर रासायनिक लेप लगाना चाहिए, जल निकासी की वैज्ञानिक व्यवस्था करनी चाहिए तथा पर्यावरण-अनुकूल पर्यटन (Eco-tourism) को बढ़ावा देना चाहिए ताकि हमारी यह अमूल्य ऐतिहासिक विरासत आने वाली पीढ़ियों के लिए सुरक्षित रह सके।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(28)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(30)\">अगला पाठ (Next) →</button>\n  </div>\n</section>\n",
  "30": "<section class=\"chapter-section\" id=\"ch30\" data-book=\"sanchayan\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">30</div>\n    <div class=\"chapter-header-info\">\n      <div class=\"ch-category\">संचयन भाग-1 (पूरक पाठ्यपुस्तक)</div>\n      <h2>मेरा छोटा-सा निजी पुस्तकालय</h2>\n      <p>धर्मवीर भारती | पूरक पाठ्यपुस्तक (आत्मकथात्मक संस्मरण) — CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n  <div class=\"ex-div\">प्रश्न-अभ्यास (पाठ्यपुस्तक के प्रश्न-उत्तर) — 100% कवरेज</div>\n\n  <div class=\"q-card\" id=\"ch30-q1\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q1')\">\n      <div class=\"q-num\">प्रश्न 1</div>\n      <div class=\"q-text\">लेखक का पुस्तकों के प्रति अनुराग बचपन में किस प्रकार शुरू हुआ? उनके घर में कौन-सी पत्रिकाएँ आती थीं?</div>\n      <div class=\"q-marks\">3 अंक (50-60 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>धर्मवीर भारती के घर में बचपन से ही एक सुंदर बौद्धिक और साहित्यिक वातावरण था। उनके पिता आर्यसमाजी थे और घर में नियमित रूप से पत्र-पत्रिकाएँ मँगाई जाती थीं:</p>\n<ul>\n  <li>पिता के लिए 'सरस्वती', 'गृहलक्ष्मी', और आर्यसमाज का पत्र 'अभ्युदय' आता था।</li>\n  <li>बालक भारती के लिए विशेष रूप से दो बाल पत्रिकाएँ—<strong>'बालसखा'</strong> और <strong>'चमचम'</strong> आती थीं।</li>\n</ul>\n<p>इन पत्रिकाओं में छपी रंग-बिरंगी परियों, राजकुमारों और शेरों की कहानियों को पढ़ने की उत्सुकता ने लेखक के मन में पढ़ने की ऐसी तीव्र भूख जगा दी कि वे बचपन में ही पुस्तकों के अनन्य प्रेमी बन गए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">घर के साहित्यिक परिवेश और पिता के आर्यसमाजी संस्कारों का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">बालसखा, चमचम, सरस्वती, गृहलक्ष्मी पत्रिकाओं के नामों का उल्लेख</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">कहानियों से पढ़ने की तीव्र जिज्ञासा और अनुराग जागने का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch30-q2\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q2')\">\n      <div class=\"q-num\">प्रश्न 2</div>\n      <div class=\"q-text\">अपनी पहली पुस्तक खरीदने का प्रसंग लेखक ने किस प्रकार वर्णित किया है?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>आर्थिक तंगी के दिनों में लेखक इंटरमीडिएट (बारहवीं) पास कर चुके थे। एक दिन माँ ने उन्हें दो रुपये दिए और कहा कि जाकर सिनेमा हॉल में 'देवदास' फिल्म देख आओ।</p>\n<p>लेखक फिल्म देखने निकले, परंतु रास्ते में एक सेकंड-हैंड किताबों की दुकान पर उनकी नजर शरतचंद्र चट्टोपाध्याय के प्रसिद्ध उपन्यास <strong>'देवदास'</strong> पर पड़ गई, जिसकी कीमत मात्र दस आने थी।</p>\n<p>लेखक के भीतर का पुस्तक-प्रेमी जाग उठा। उन्होंने सोचा कि तीन घंटे फिल्म देखने के बाद सब समाप्त हो जाएगा, परंतु यदि वे पुस्तक खरीद लेंगे, तो वह जीवन भर उनके पास रहेगी और वे उसे बार-बार पढ़ सकेंगे। उन्होंने फिल्म देखने का विचार त्याग दिया और दस आने में 'देवदास' पुस्तक खरीद ली। बचे हुए पैसे उन्होंने माँ को वापस सौंप दिए। इस प्रकार उनके निजी पुस्तकालय की पहली पुस्तक का जन्म हुआ।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">माँ द्वारा फिल्म देखने के लिए दो रुपये दिए जाने की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">दुकान पर शरतचंद्र के उपन्यास 'देवदास' को देखने का प्रसंग</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">क्षणिक सिनेमा बनाम स्थायी पुस्तक के मूल्य का विवेकपूर्ण निर्णय</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा एवं प्रस्तुति</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"q-card\" id=\"ch30-q3\">\n    <div class=\"q-head\" onclick=\"toggleQ('ch30-q3')\">\n      <div class=\"q-num\">प्रश्न 3</div>\n      <div class=\"q-text\">गंभीर बीमारी (हार्ट अटैक) के दौरान पुस्तकों ने लेखक को किस प्रकार नया जीवन और संबल दिया?</div>\n      <div class=\"q-marks\">4 अंक (60-80 शब्द)</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer (अधिकतम शब्द-सीमा / Max Word Count)</div>\n        <div class=\"answer-text\">\n<p>1989 में लेखक धर्मवीर भारती को लगातार तीन भीषण दिल के दौरे (हार्ट अटैक) पड़े। उनकी नब्ज बंद हो गई थी और डॉक्टरों ने उन्हें मृतप्राय मान लिया था। परंतु 'इलेक्ट्रिक शॉक' देकर किसी तरह उनके प्राण वापस लाए गए।</p>\n<p>अस्पताल से घर लौटने पर डॉक्टरों ने उन्हें पूर्ण विश्राम और किसी से भी न मिलने की सख्त हिदायत दी। ऐसी एकाकी और निराशाजनक स्थिति में उनके शयनकक्ष को ही उनके निजी पुस्तकालय में बदल दिया गया।</p>\n<p><strong>पुस्तकों का संबल:</strong> चारों ओर अलमारियों में सजी टॉल्स्टॉय, गोर्की, शेक्सपियर, कालिदास, कबीर और टैगोर की अमर कृतियों ने लेखक को यह अहसास कराया कि वे अकेले नहीं हैं; विश्व के महानतम विचारकों की अमर आत्माएँ उनके साथ बैठी हैं। इन पुस्तकों की प्राणवान उपस्थिति ने लेखक के भीतर जीने की अदम्य इच्छाशक्ति और प्राण-ऊर्जा भर दी, जिससे वे रोगमुक्त हो गए।</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE अंक योजना (Marking Scheme) 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">तीन हार्ट अटैक और डॉक्टरों द्वारा मृतप्राय माने जाने की पृष्ठभूमि</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">शयनकक्ष को पुस्तकालय बनाने और एकांत की स्थिति का वर्णन</span><span class=\"marking-marks\">1.0 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">महान विचारकों की पुस्तकों से प्राण-ऊर्जा और जीने की जिजीविषा मिलने का विश्लेषण</span><span class=\"marking-marks\">1.5 अंक</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">भाषा की शुद्धता</span><span class=\"marking-marks\">0.5 अंक</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\"><span>🎯 योग्यता एवं मूल्य आधारित प्रश्न (Competency-Based Questions) — पाठ 30</span><span class=\"cbq-badge\">CBSE 2026-27</span></div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\" style=\"border-left:4px solid #f59e0b;\">\n        <div class=\"cbq-type\" style=\"color:#d97706;\">मूल्यपरक प्रश्न (Value-Based Question)</div>\n        <div class=\"cbq-question\">डिजिटल युग में जहाँ बच्चे और युवा स्मार्टफोन्स व रील्स (Reels) के आदी हो रहे हैं, वहाँ धर्मवीर भारती के 'निजी पुस्तकालय' का क्या महत्व है?</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>आज का युवा इंटरनेट और सोशल मीडिया की सतही, भ्रामक और क्षणिक सूचनाओं में भटककर अपनी एकाग्रता और सोचने की गहराई खो रहा है।</p><p>धर्मवीर भारती का संस्मरण याद दिलाता है कि पुस्तकें मनुष्य की सबसे सच्ची, निष्कपट और स्थायी मित्र हैं। अच्छी पुस्तकें हमारे चरित्र का निर्माण करती हैं, संकट में संबल बनती हैं और हमें जीवन की वास्तविक दिशा दिखाती हैं। प्रत्येक घर में एक छोटा-सा निजी पुस्तकालय होना चाहिए जो नई पीढ़ी को संवेदनशील, विचारवान और सुसंस्कृत नागरिक बना सके।</p></div>\n      </div>\n      <div class=\"cbq-card\" style=\"border-left:4px solid #3b82f6;\">\n        <div class=\"cbq-type\" style=\"color:#2563eb;\">दक्षता आधारित प्रश्न (Competency-Based Question)</div>\n        <div class=\"cbq-question\">'किताबें केवल कागज के पन्ने नहीं, वे जीवित आत्माओं का संवाद हैं' - पाठ के आधार पर इस कथन की पुष्टि कीजिए।</div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ उत्तर देखें / Show Answer</button>\n        <div class=\"cbq-answer\"><p>लेखक जब अपनी बीमारी के दौरान पुस्तकालय में बैठे थे, तो उन्हें लगता था कि कबीर, तुलसी, चेखव और रोम्यां रोलां जीवित होकर उनसे बातें कर रहे हैं। किताबें सदियों की दूरी को मिटाकर महान विचारकों के विचारों को पाठक के हृदय में स्पंदित कर देती हैं।</p><p>पुस्तकें लेखक के अनुभवों, संवेदनाओं और जीवन-दर्शन का जीवित दस्तावेज होती हैं। इसलिए जब पाठक किसी पुस्तक को पढ़ता है, तो वह केवल शब्द नहीं पढ़ता, बल्कि उस लेखक की अंतरात्मा से सीधा साक्षात्कार करता है।</p></div>\n      </div>\n    </div>\n  </div>\n  <div class=\"chapter-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(29)\">← पिछला पाठ (Previous)</button>\n    <button class=\"ch-nav-btn\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑ शीर्ष पर जाएँ (Top)</button>\n    <div></div>\n  </div>\n</section>\n"
};
